/** Типовые ISO-коды типоразмеров (подставляются по умолчанию при создании). */
export const DEFAULT_ISO_CODE: Record<SizeType, string> = {
  "20DC": "22G1",
  "20HQ": "25G1",
  "40DC": "42G1",
  "40HC": "45G1",
