  "20DC": { tare: 2230, gross: 30480 },
  "20HQ": { tare: 2350, gross: 30480 },
  "40DC": { tare: 3750, gross: 30480 },
  "40HC": { tare: 3900, gross: 32500 },
  "40HR": { tare: 4800, gross: 34000 },
  "20OT": { tare: 2350, gross: 30480 },
  "40FR": { tare: 5600, gross: 45000 },
