import { addDays, diffDays } from "@/lib/dates";
import { THRESHOLDS, type StoredTripStatus, type TripStatus } from "./constants";

export interface TripTimingInput {
  status: string;
  handoverDate: Date;
  freeDays: number;
  deadlineDate: Date;
  actualReturnDate: Date | null;
  detentionRatePerDayUsd: number;
}

export interface TripTiming {
  /** Эффективный статус: ACTIVE с прошедшим дедлайном становится OVERDUE. */
  status: TripStatus;
  /** Сколько свободных дней осталось (только для ACTIVE). */
  daysLeft: number | null;
  /** Дней просрочки на сегодня или на дату фактического возврата. */
  overdueDays: number;
  /** Начисленный детеншн, USD. */
  detentionUsd: number;
  /** Дедлайн ≤ 5 дней и ещё не наступил. */
  isHot: boolean;
  /** Доля использованных свободных дней 0..1 (для прогресс-бара). */
  freeDaysUsedRatio: number;
}

export function computeDeadline(handoverDate: Date, freeDays: number): Date {
  return addDays(handoverDate, freeDays);
}

export function computeTripTiming(trip: TripTimingInput, now: Date): TripTiming {
  const stored = trip.status as StoredTripStatus;
  const isClosed = stored === "COMPLETED" || stored === "DISPUTE";
  const referenceDate = isClosed && trip.actualReturnDate ? trip.actualReturnDate : now;

  const daysToDeadline = diffDays(referenceDate, trip.deadlineDate);
  const overdueDays = Math.max(0, -daysToDeadline);
  const detentionUsd = overdueDays * trip.detentionRatePerDayUsd;
  const usedDays = diffDays(trip.handoverDate, referenceDate);
  const freeDaysUsedRatio = trip.freeDays > 0 ? Math.min(1, Math.max(0, usedDays / trip.freeDays)) : 1;

  if (isClosed) {
    return { status: stored, daysLeft: null, overdueDays, detentionUsd, isHot: false, freeDaysUsedRatio };
  }

  const isOverdue = overdueDays > 0;
  return {
    status: isOverdue ? "OVERDUE" : "ACTIVE",
    daysLeft: isOverdue ? null : daysToDeadline,
    overdueDays,
    detentionUsd,
    isHot: !isOverdue && daysToDeadline <= THRESHOLDS.oneWayHotDays,
    freeDaysUsedRatio,
  };
}

import { addDays, daysInMonthUtc, diffDays, startOfMonthUtc } from "@/lib/dates";
import { THRESHOLDS } from "./constants";

export interface LeaseItemInput {
  onHireDate: Date;
  offHireDate: Date | null;
}

export interface LeaseInput {
  status: string;
  endDate: Date;
  dailyRateUsd: number;
  paymentStatus: string;
  items: readonly LeaseItemInput[];
}

export type LeaseExpiryLevel = "EXPIRED" | "CRITICAL" | "WARNING" | "OK" | "CLOSED";

export interface LeaseMetrics {
  activeUnits: number;
  totalUnits: number;
  daysToEnd: number;
  expiryLevel: LeaseExpiryLevel;
  /** Начислено за текущий календарный месяц по сегодняшний день включительно. */
  accruedThisMonthUsd: number;
  /** Начислено за весь срок договора. */
  accruedTotalUsd: number;
  /** Плановый доход в месяц при текущем числе единиц на руках. */
  monthlyRunRateUsd: number;
  needsAttention: boolean;
}

/** Дни аренды единицы в интервале [from, to] включительно, с учётом On-Hire/Off-Hire. */
export function rentalDaysInRange(item: LeaseItemInput, from: Date, to: Date): number {
  const start = item.onHireDate > from ? item.onHireDate : from;
  // День Off-Hire не тарифицируется, поэтому последний оплачиваемый день — накануне.
  const lastBillable = item.offHireDate ? addDays(item.offHireDate, -1) : to;
  const end = lastBillable < to ? lastBillable : to;
  const days = diffDays(start, end) + 1;
  return Math.max(0, days);
}

export function expiryLevelOf(daysToEnd: number, isClosed: boolean): LeaseExpiryLevel {
  if (isClosed) return "CLOSED";
  if (daysToEnd < 0) return "EXPIRED";
  if (daysToEnd <= THRESHOLDS.leaseExpiringCriticalDays) return "CRITICAL";
  if (daysToEnd <= THRESHOLDS.leaseExpiringWarningDays) return "WARNING";
  return "OK";
}

export function computeLeaseMetrics(lease: LeaseInput, now: Date): LeaseMetrics {
  const isClosed = lease.status === "COMPLETED";
  const activeUnits = lease.items.filter((i) => !i.offHireDate).length;
  const daysToEnd = diffDays(now, lease.endDate);
  const monthStart = startOfMonthUtc(now);
  const farPast = new Date(0);

  const accruedThisMonthUsd = lease.items.reduce(
    (sum, item) => sum + rentalDaysInRange(item, monthStart, now) * lease.dailyRateUsd,
    0,
  );
  const accruedTotalUsd = lease.items.reduce(
    (sum, item) => sum + rentalDaysInRange(item, farPast, now) * lease.dailyRateUsd,
    0,
  );
  const expiryLevel = expiryLevelOf(daysToEnd, isClosed);

  return {
    activeUnits,
    totalUnits: lease.items.length,
    daysToEnd,
    expiryLevel,
    accruedThisMonthUsd,
    accruedTotalUsd,
    monthlyRunRateUsd: activeUnits * lease.dailyRateUsd * daysInMonthUtc(now),
    needsAttention:
      !isClosed && (lease.paymentStatus === "OVERDUE" || expiryLevel === "CRITICAL" || expiryLevel === "WARNING" || expiryLevel === "EXPIRED"),
  };
}

export function parseLocodeList(csv: string): string[] {
  return csv
    .split(",")
    .map((s) => s.trim().toUpperCase())
    .filter(Boolean);
}

import { diffDays } from "@/lib/dates";
import { THRESHOLDS } from "./constants";

export type CscLevel = "EXPIRED" | "EXPIRING" | "OK";

export interface CscState {
  level: CscLevel;
  daysLeft: number;
}

export function cscStateOf(cscPlateExpiry: Date, now: Date): CscState {
  const daysLeft = diffDays(now, cscPlateExpiry);
  if (daysLeft < 0) return { level: "EXPIRED", daysLeft };
  if (daysLeft <= THRESHOLDS.cscWarningDays) return { level: "EXPIRING", daysLeft };
  return { level: "OK", daysLeft };
}

export interface StorageInput {
  operationalStatus: string;
  storageStartDate: Date | null;
  storageRatePerDayUsd: number | null;
}

export interface StorageState {
  /** Дней на стоке (null — контейнер не на стоке). */
  idleDays: number | null;
  isIdleTooLong: boolean;
  /** Накопленная стоимость хранения, USD. */
  storageCostUsd: number;
}

export function storageStateOf(container: StorageInput, now: Date): StorageState {
  const onStock = container.operationalStatus === "AVAILABLE" && container.storageStartDate !== null;
  if (!onStock || !container.storageStartDate) {
    return { idleDays: null, isIdleTooLong: false, storageCostUsd: 0 };
  }
  const idleDays = Math.max(0, diffDays(container.storageStartDate, now));
  return {
    idleDays,
    isIdleTooLong: idleDays > THRESHOLDS.idleStockDays,
    storageCostUsd: idleDays * (container.storageRatePerDayUsd ?? 0),
  };
}

export interface EconomicsInput {
  purchasePriceUsd: number;
  currentBookValueUsd: number;
  totalRevenueUsd: number;
  totalRepairCostUsd: number;
}

export interface UnitEconomics {
  depreciationUsd: number;
  /** Выручка − ремонты − амортизация. */
  netResultUsd: number;
  /** netResult / цена покупки. */
  roi: number;
  /** Окупаемость: доля цены покупки, покрытая чистой выручкой (выручка − ремонты). */
  paybackRatio: number;
}

export function unitEconomicsOf(c: EconomicsInput): UnitEconomics {
  const depreciationUsd = Math.max(0, c.purchasePriceUsd - c.currentBookValueUsd);
  const netResultUsd = c.totalRevenueUsd - c.totalRepairCostUsd - depreciationUsd;
  const roi = c.purchasePriceUsd > 0 ? netResultUsd / c.purchasePriceUsd : 0;
  const paybackRatio = c.purchasePriceUsd > 0 ? (c.totalRevenueUsd - c.totalRepairCostUsd) / c.purchasePriceUsd : 0;
  return { depreciationUsd, netResultUsd, roi, paybackRatio };
}

export interface AttentionInput extends StorageInput {
  techStatus: string;
  cscPlateExpiry: Date;
}

export interface AttentionFlags {
  csc: CscState;
  storage: StorageState;
  needsRepair: boolean;
  any: boolean;
}

export function attentionFlagsOf(c: AttentionInput, now: Date): AttentionFlags {
  const csc = cscStateOf(c.cscPlateExpiry, now);
  const storage = storageStateOf(c, now);
  const needsRepair = c.techStatus === "DAMAGED" || c.techStatus === "IN_REPAIR";
  return { csc, storage, needsRepair, any: csc.level !== "OK" || storage.isIdleTooLong || needsRepair };
}

