export const HISTORY_ROUTES: readonly [from: [string, string], to: [string, string]][] = [
  [["CNSHA", "Shanghai SIPG"], ["RUMOW", "ТЛЦ Ворсино"]],
  [["RUVVO", "ВМТП"], ["RUMOW", "ТЛЦ Ховрино"]],
