@import "tailwindcss";

@theme {
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: var(--font-jetbrains), ui-monospace, "SFMono-Regular", Consolas, monospace;
  --breakpoint-xs: 420px;
}

@layer base {
  html {
    -webkit-tap-highlight-color: transparent;
  }
  body {
    @apply bg-slate-50 text-slate-900 antialiased;
    font-feature-settings: "cv11", "ss01";
  }
  :focus-visible {
    @apply outline-2 outline-offset-2 outline-indigo-500;
  }
}

@utility tabular {
  font-variant-numeric: tabular-nums;
}

@utility safe-bottom {
  padding-bottom: env(safe-area-inset-bottom);
}

@utility scrollbar-thin {
  scrollbar-width: thin;
}

@keyframes sheet-in-right {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}
@keyframes sheet-in-bottom {
  from { transform: translateY(100%); }
  to { transform: translateY(0); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

.animate-sheet {
  animation: sheet-in-bottom 220ms cubic-bezier(0.22, 1, 0.36, 1);
}
@media (min-width: 1024px) {
  .animate-sheet {
    animation: sheet-in-right 240ms cubic-bezier(0.22, 1, 0.36, 1);
  }
}
.animate-fade {
  animation: fade-in 180ms ease-out;
}

@media (prefers-reduced-motion: reduce) {
  .animate-sheet,
  .animate-fade {
    animation: none;
  }
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

export function getErrorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  return "Непредвиденная ошибка";
}

import { forwardRef, type ButtonHTMLAttributes } from "react";
import { LoaderCircle } from "lucide-react";
import { cn } from "@/lib/utils";

const VARIANTS = {
  default: "bg-indigo-600 text-white shadow-sm hover:bg-indigo-700 active:bg-indigo-800",
  secondary: "bg-slate-100 text-slate-900 hover:bg-slate-200",
  outline: "border border-slate-300 bg-white text-slate-700 shadow-sm hover:bg-slate-50",
  ghost: "text-slate-600 hover:bg-slate-100 hover:text-slate-900",
  destructive: "bg-rose-600 text-white shadow-sm hover:bg-rose-700",
  success: "bg-emerald-600 text-white shadow-sm hover:bg-emerald-700",
  warning: "bg-amber-500 text-white shadow-sm hover:bg-amber-600",
} as const;

const SIZES = {
  sm: "h-8 px-3 text-xs gap-1.5 rounded-md",
  md: "h-10 px-4 text-sm gap-2 rounded-lg",
  lg: "h-12 px-5 text-base gap-2 rounded-xl",
  icon: "h-10 w-10 rounded-lg",
} as const;

export type ButtonVariant = keyof typeof VARIANTS;

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: keyof typeof SIZES;
  loading?: boolean;
}

export function buttonClasses(variant: ButtonVariant = "default", size: keyof typeof SIZES = "md", className?: string): string {
  return cn(
    "inline-flex shrink-0 items-center justify-center font-medium whitespace-nowrap transition-colors disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-4 [&_svg]:shrink-0",
    VARIANTS[variant],
    SIZES[size],
    className,
  );
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  { variant = "default", size = "md", loading = false, className, children, disabled, type = "button", ...props },
  ref,
) {
  return (
    <button ref={ref} type={type} className={buttonClasses(variant, size, className)} disabled={disabled || loading} {...props}>
      {loading && <LoaderCircle className="animate-spin" aria-hidden />}
      {children}
    </button>
  );
});

