import "server-only";
import { prisma } from "@/lib/prisma";
import { attentionFlagsOf, unitEconomicsOf, type CscState } from "@/lib/domain/container";
import { computeTripTiming, type TripTiming } from "@/lib/domain/one-way";
import { locodeCity } from "@/lib/domain/constants";

export interface ContainerEventDto {
  id: string;
  type: string;
  occurredAt: Date;
  locode: string | null;
  terminal: string | null;
  description: string;
  amountUsd: number | null;
  actor: string | null;
}

export interface ContainerRow {
  id: string;
  bicCode: string;
  sizeType: string;
  isoCode: string;
  manufactureYear: number;
  manufacturer: string;
  conditionGrade: string;
  techStatus: string;
  operationalStatus: string;
  currentLocode: string;
  currentTerminal: string;
  cscPlateExpiry: Date;
  csc: CscState;
  idleDays: number | null;
  isIdleTooLong: boolean;
  storageCostUsd: number;
  eorAmountUsd: number | null;
  roi: number;
  totalRevenueUsd: number;
  needsAttention: boolean;
  needsRepair: boolean;
  /** Краткое описание текущей операции: «OW-2026-0912 → Москва» / «LC-2025/014». */
  activity: string | null;
  activityHref: string | null;
  tripTiming: TripTiming | null;
  recentEvents: ContainerEventDto[];
}

const RECENT_EVENTS = 4;

export async function getContainerRows(now: Date): Promise<ContainerRow[]> {
  const containers = await prisma.container.findMany({
    orderBy: { bicCode: "asc" },
    include: {
      events: { orderBy: { occurredAt: "desc" }, take: RECENT_EVENTS },
      oneWayTrips: { where: { status: "ACTIVE" }, take: 1 },
      leaseItems: { where: { offHireDate: null, lease: { status: "ACTIVE" } }, include: { lease: true }, take: 1 },
    },
  });

  return containers.map((c) => {
    const flags = attentionFlagsOf(c, now);
    const trip = c.oneWayTrips[0];
    const leaseItem = c.leaseItems[0];
    const activity = trip
      ? `${trip.bookingRef} → ${locodeCity(trip.dropoffLocode)}`
      : leaseItem
        ? `${leaseItem.lease.contractNumber} · ${leaseItem.lease.lesseeName}`
        : null;
    const activityHref = trip ? `/one-way?focus=${trip.id}` : leaseItem ? `/leases/${leaseItem.lease.id}` : null;

    return {
      id: c.id,
      bicCode: c.bicCode,
      sizeType: c.sizeType,
      isoCode: c.isoCode,
      manufactureYear: c.manufactureYear,
      manufacturer: c.manufacturer,
      conditionGrade: c.conditionGrade,
      techStatus: c.techStatus,
      operationalStatus: c.operationalStatus,
      currentLocode: c.currentLocode,
      currentTerminal: c.currentTerminal,
      cscPlateExpiry: c.cscPlateExpiry,
      csc: flags.csc,
      idleDays: flags.storage.idleDays,
      isIdleTooLong: flags.storage.isIdleTooLong,
      storageCostUsd: flags.storage.storageCostUsd,
      eorAmountUsd: c.eorAmountUsd,
      roi: unitEconomicsOf(c).roi,
      totalRevenueUsd: c.totalRevenueUsd,
      needsAttention: flags.any,
      needsRepair: flags.needsRepair,
      activity,
      activityHref,
      tripTiming: trip ? computeTripTiming(trip, now) : null,
      recentEvents: c.events,
    };
  });
}

export async function getContainerProfile(id: string) {
  return prisma.container.findUnique({
    where: { id },
    include: {
      events: { orderBy: { occurredAt: "desc" } },
      oneWayTrips: { orderBy: { handoverDate: "desc" } },
      leaseItems: { orderBy: { onHireDate: "desc" }, include: { lease: true } },
    },
  });
}

export type ContainerProfile = NonNullable<Awaited<ReturnType<typeof getContainerProfile>>>;

/** Контейнеры, которые можно выдать (One-Way / аренда): свободны и исправны. */
export async function getIssuableContainers() {
  return prisma.container.findMany({
    where: { operationalStatus: "AVAILABLE", techStatus: "SOUND" },
    orderBy: [{ currentLocode: "asc" }, { bicCode: "asc" }],
    select: { id: true, bicCode: true, sizeType: true, currentLocode: true, currentTerminal: true, conditionGrade: true },
  });
}

export type IssuableContainer = Awaited<ReturnType<typeof getIssuableContainers>>[number];

import "server-only";
import { prisma } from "@/lib/prisma";
import { computeTripTiming, type TripTiming } from "@/lib/domain/one-way";
import { computeLeaseMetrics, parseLocodeList, type LeaseMetrics } from "@/lib/domain/lease";
import type { NavBadges } from "@/components/layout/nav-items";

export interface TripRow {
  id: string;
  containerId: string;
  bicCode: string;
  sizeType: string;
  counterpartyName: string;
  counterpartyInn: string | null;
  counterpartyContact: string | null;
  bookingRef: string;
  pickupLocode: string;
  pickupTerminal: string;
  dropoffLocode: string;
  dropoffTerminal: string;
  handoverDate: Date;
  freeDays: number;
  deadlineDate: Date;
  actualReturnDate: Date | null;
  feeUsd: number;
  detentionRatePerDayUsd: number;
  returnCondition: string | null;
  returnEorUsd: number | null;
  notes: string | null;
  timing: TripTiming;
}

export async function getTripRows(now: Date): Promise<TripRow[]> {
  const trips = await prisma.oneWayTrip.findMany({
    include: { container: { select: { bicCode: true, sizeType: true } } },
    orderBy: { deadlineDate: "asc" },
  });
  return trips.map(({ container, createdAt: _c, updatedAt: _u, status: _s, ...trip }) => ({
    ...trip,
    bicCode: container.bicCode,
    sizeType: container.sizeType,
    timing: computeTripTiming({ ...trip, status: _s }, now),
  }));
}

export interface LeaseRow {
  id: string;
  contractNumber: string;
  lesseeName: string;
  lesseeInn: string | null;
  contactPerson: string;
  contactPhone: string | null;
  contactEmail: string | null;
  startDate: Date;
  endDate: Date;
  autoRenewal: boolean;
  dailyRateUsd: number;
  currency: string;
  depositUsd: number;
  paymentStatus: string;
  allowedReturnLocodes: string[];
  onHireSurvey: string;
  offHireSurvey: string;
  status: string;
  notes: string | null;
  metrics: LeaseMetrics;
  items: {
    id: string;
    containerId: string;
    bicCode: string;
    sizeType: string;
    techStatus: string;
    onHireDate: Date;
    offHireDate: Date | null;
    returnLocode: string | null;
  }[];
}

const leaseInclude = {
  items: { include: { container: { select: { bicCode: true, sizeType: true, techStatus: true } } }, orderBy: { onHireDate: "asc" as const } },
};

type LeaseWithItems = Awaited<ReturnType<typeof prisma.leaseContract.findMany<{ include: typeof leaseInclude }>>>[number];

function toLeaseRow(lease: LeaseWithItems, now: Date): LeaseRow {
  return {
    id: lease.id,
    contractNumber: lease.contractNumber,
    lesseeName: lease.lesseeName,
    lesseeInn: lease.lesseeInn,
    contactPerson: lease.contactPerson,
    contactPhone: lease.contactPhone,
    contactEmail: lease.contactEmail,
    startDate: lease.startDate,
    endDate: lease.endDate,
    autoRenewal: lease.autoRenewal,
    dailyRateUsd: lease.dailyRateUsd,
    currency: lease.currency,
    depositUsd: lease.depositUsd,
    paymentStatus: lease.paymentStatus,
    allowedReturnLocodes: parseLocodeList(lease.allowedReturnLocodes),
    onHireSurvey: lease.onHireSurvey,
    offHireSurvey: lease.offHireSurvey,
    status: lease.status,
    notes: lease.notes,
    metrics: computeLeaseMetrics(lease, now),
    items: lease.items.map((item) => ({
      id: item.id,
      containerId: item.containerId,
      bicCode: item.container.bicCode,
      sizeType: item.container.sizeType,
      techStatus: item.container.techStatus,
      onHireDate: item.onHireDate,
      offHireDate: item.offHireDate,
      returnLocode: item.returnLocode,
    })),
  };
}

export async function getLeaseRows(now: Date): Promise<LeaseRow[]> {
  const leases = await prisma.leaseContract.findMany({ include: leaseInclude, orderBy: [{ status: "asc" }, { endDate: "asc" }] });
  return leases.map((l) => toLeaseRow(l, now));
}

export async function getLeaseRow(id: string, now: Date): Promise<LeaseRow | null> {
  const lease = await prisma.leaseContract.findUnique({ where: { id }, include: leaseInclude });
  return lease ? toLeaseRow(lease, now) : null;
}

export async function getNavBadges(now: Date): Promise<NavBadges> {
  const [trips, leases] = await Promise.all([
    prisma.oneWayTrip.findMany({ where: { status: "ACTIVE" } }),
    prisma.leaseContract.findMany({ where: { status: "ACTIVE" }, include: { items: true } }),
  ]);
  return {
    oneWayOverdue: trips.filter((t) => computeTripTiming(t, now).status === "OVERDUE").length,
    leaseAttention: leases.filter((l) => computeLeaseMetrics(l, now).needsAttention).length,
  };
}

import { AppShell } from "@/components/layout/app-shell";
import { requireSession } from "@/lib/auth/dal";
import { getNavBadges } from "@/lib/queries/operations";

export default async function ProtectedLayout({ children }: { children: React.ReactNode }) {
  const session = await requireSession();
  const badges = await getNavBadges(new Date());
  return (
    <AppShell user={{ name: session.name, email: session.email, role: session.role }} badges={badges}>
      {children}
    </AppShell>
  );
}

