import "server-only";
import { z } from "zod";
import { parseDateInput } from "@/lib/dates";
import type { ActionResult } from "./types";

export type Parsed<T> = { ok: true; data: T } | { ok: false; result: ActionResult };

export function parseInput<S extends z.ZodType>(schema: S, input: unknown): Parsed<z.infer<S>> {
  const parsed = schema.safeParse(input);
  if (parsed.success) return { ok: true, data: parsed.data };
  const fieldErrors: Record<string, string> = {};
  for (const issue of parsed.error.issues) {
    const key = issue.path.join(".") || "_";
    if (!fieldErrors[key]) fieldErrors[key] = issue.message;
  }
  return { ok: false, result: { ok: false, error: parsed.error.issues[0]?.message ?? "Проверьте данные формы", fieldErrors } };
}

/** "2026-10-26" → Date (полночь UTC). */
export const dateField = z
  .string({ error: "Укажите дату" })
  .refine((v) => parseDateInput(v) !== null, "Некорректная дата")
  .transform((v) => parseDateInput(v) as Date);

export const moneyField = z.coerce.number({ error: "Введите число" }).min(0, "Не может быть отрицательным").max(10_000_000, "Слишком большое значение");

export const optionalText = (max = 500) =>
  z
    .string()
    .trim()
    .max(max, `Не более ${max} символов`)
    .optional()
    .transform((v) => (v ? v : null));

export const requiredText = (label: string, max = 200) => z.string({ error: `Укажите: ${label}` }).trim().min(1, `Укажите: ${label}`).max(max);

export const locodeField = z
  .string()
  .trim()
  .toUpperCase()
  .regex(/^[A-Z]{2}[A-Z2-9]{3}$/, "UN/LOCODE: 5 символов, например RUVVO");

export const innField = z
  .string()
  .trim()
  .regex(/^(\d{10}|\d{12})?$/, "ИНН: 10 или 12 цифр")
  .optional()
  .transform((v) => (v ? v : null));

export function notFound(entity: string): ActionResult {
  return { ok: false, error: `${entity} не найден(а) — возможно, данные были сброшены` };
}

"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { requireSession } from "@/lib/auth/dal";
import { validateBic, formatBic } from "@/lib/iso6346";
import { startOfDayUtc } from "@/lib/dates";
import {
  CONDITION_GRADES,
  EVENT_TYPES,
  OPERATIONAL_STATUSES,
  SIZE_TYPES,
  TECH_STATUSES,
  OPERATIONAL_STATUS_LABELS,
  TECH_STATUS_LABELS,
} from "@/lib/domain/constants";
import { getErrorMessage } from "@/lib/utils";
import { dateField, locodeField, moneyField, notFound, optionalText, parseInput, requiredText } from "./helpers";
import type { ActionResult } from "./types";

const baseContainerSchema = z.object({
  bicCode: z.string().trim(),
  sizeType: z.enum(SIZE_TYPES, { error: "Выберите типоразмер" }),
  isoCode: z.string().trim().toUpperCase().regex(/^[0-9A-Z]{4}$/, "ISO-код типа: 4 символа, например 45G1"),
  manufactureYear: z.coerce.number().int().min(1990, "Год не ранее 1990").max(new Date().getUTCFullYear() + 1, "Год из будущего"),
  colorRal: requiredText("цвет RAL", 60),
  manufacturer: requiredText("завод-изготовитель", 120),
  tareWeightKg: z.coerce.number().int().min(500, "Тара от 500 кг").max(15_000),
  maxGrossWeightKg: z.coerce.number().int().min(10_000).max(60_000),
  conditionGrade: z.enum(CONDITION_GRADES),
  techStatus: z.enum(TECH_STATUSES),
  cscPlateExpiry: dateField,
  eorAmountUsd: z.union([moneyField, z.literal("").transform(() => null), z.null()]).optional().transform((v) => v ?? null),
  operationalStatus: z.enum(OPERATIONAL_STATUSES),
  currentLocode: locodeField,
  currentTerminal: requiredText("терминал / депо", 120),
  storageRatePerDayUsd: z.union([moneyField, z.literal("").transform(() => null), z.null()]).optional().transform((v) => v ?? null),
  purchaseDate: dateField,
  purchasePriceUsd: moneyField,
  currentBookValueUsd: moneyField,
  notes: optionalText(1000),
});

const containerSchema = baseContainerSchema.superRefine((value, ctx) => {
  const bic = validateBic(value.bicCode);
  if (!bic.valid) ctx.addIssue({ code: "custom", path: ["bicCode"], message: bic.errors[0] ?? "Некорректный номер" });
  if (value.tareWeightKg >= value.maxGrossWeightKg) {
    ctx.addIssue({ code: "custom", path: ["tareWeightKg"], message: "Тара должна быть меньше брутто" });
  }
  if (value.currentBookValueUsd > value.purchasePriceUsd) {
    ctx.addIssue({ code: "custom", path: ["currentBookValueUsd"], message: "Остаточная стоимость не может превышать цену покупки" });
  }
});

export type ContainerInput = z.input<typeof baseContainerSchema>;

/** Операционные статусы, которые управляются только через модули One-Way / аренды. */
const MANAGED_STATUSES = new Set(["ONE_WAY", "LONG_TERM_LEASE"]);

export async function createContainerAction(input: ContainerInput): Promise<ActionResult> {
  const session = await requireSession();
  const parsed = parseInput(containerSchema, input);
  if (!parsed.ok) return parsed.result;
  const data = parsed.data;
  if (MANAGED_STATUSES.has(data.operationalStatus)) {
    return { ok: false, error: "Статусы One-Way и аренды назначаются через соответствующие модули", fieldErrors: { operationalStatus: "Недоступно при создании" } };
  }
  const bicCode = validateBic(data.bicCode).normalized;

  const exists = await prisma.container.findUnique({ where: { bicCode }, select: { id: true } });
  if (exists) return { ok: false, error: `Контейнер ${formatBic(bicCode)} уже есть в реестре`, fieldErrors: { bicCode: "Номер уже существует" } };

  try {
    const now = new Date();
    const container = await prisma.container.create({
      data: {
        ...data,
        bicCode,
        maxPayloadKg: data.maxGrossWeightKg - data.tareWeightKg,
        storageStartDate: data.operationalStatus === "AVAILABLE" ? startOfDayUtc(now) : null,
        events: {
          create: [
            {
              type: "PURCHASE",
              occurredAt: now,
              locode: data.currentLocode,
              terminal: data.currentTerminal,
              description: `Контейнер введён в реестр. Покупка ${data.purchaseDate.toISOString().slice(0, 10)} у ${data.manufacturer}.`,
              amountUsd: data.purchasePriceUsd,
              actor: session.name,
            },
          ],
        },
      },
    });
    revalidatePath("/", "layout");
    return { ok: true, message: `Контейнер ${formatBic(bicCode)} добавлен в парк`, id: container.id };
  } catch (error) {
    return { ok: false, error: `Не удалось сохранить: ${getErrorMessage(error)}` };
  }
}

export async function updateContainerAction(id: string, input: ContainerInput): Promise<ActionResult> {
  const session = await requireSession();
  const parsed = parseInput(containerSchema, input);
  if (!parsed.ok) return parsed.result;
  const data = parsed.data;
  const bicCode = validateBic(data.bicCode).normalized;

  const current = await prisma.container.findUnique({ where: { id } });
  if (!current) return notFound("Контейнер");

  const statusChangedToManaged = data.operationalStatus !== current.operationalStatus && MANAGED_STATUSES.has(data.operationalStatus);
  const leavingManaged = data.operationalStatus !== current.operationalStatus && MANAGED_STATUSES.has(current.operationalStatus);
  if (statusChangedToManaged || leavingManaged) {
    return {
      ok: false,
      error: "Выдача/возврат One-Way и аренды оформляются в соответствующих модулях",
      fieldErrors: { operationalStatus: "Используйте модуль One-Way или «Долгосрочная аренда»" },
    };
  }
  if (bicCode !== current.bicCode) {
    const clash = await prisma.container.findUnique({ where: { bicCode }, select: { id: true } });
    if (clash) return { ok: false, error: "Такой номер уже есть в реестре", fieldErrors: { bicCode: "Номер уже существует" } };
  }

  const changes: string[] = [];
  if (current.techStatus !== data.techStatus) changes.push(`тех. статус: ${TECH_STATUS_LABELS[current.techStatus as keyof typeof TECH_STATUS_LABELS] ?? current.techStatus} → ${TECH_STATUS_LABELS[data.techStatus]}`);
  if (current.operationalStatus !== data.operationalStatus) changes.push(`режим: ${OPERATIONAL_STATUS_LABELS[current.operationalStatus as keyof typeof OPERATIONAL_STATUS_LABELS] ?? current.operationalStatus} → ${OPERATIONAL_STATUS_LABELS[data.operationalStatus]}`);
  if (current.conditionGrade !== data.conditionGrade) changes.push(`грейд: ${current.conditionGrade} → ${data.conditionGrade}`);
  if (current.currentLocode !== data.currentLocode || current.currentTerminal !== data.currentTerminal) changes.push(`локация: ${data.currentLocode}, ${data.currentTerminal}`);

  const becameAvailable = data.operationalStatus === "AVAILABLE" && current.operationalStatus !== "AVAILABLE";
  try {
    await prisma.container.update({
      where: { id },
      data: {
        ...data,
        bicCode,
        maxPayloadKg: data.maxGrossWeightKg - data.tareWeightKg,
        storageStartDate: data.operationalStatus !== "AVAILABLE" ? null : becameAvailable ? startOfDayUtc(new Date()) : current.storageStartDate,
        events: changes.length
          ? {
              create: {
                type: "STATUS_CHANGE",
                occurredAt: new Date(),
                locode: data.currentLocode,
                terminal: data.currentTerminal,
                description: `Карточка обновлена: ${changes.join("; ")}.`,
                actor: session.name,
              },
            }
          : undefined,
      },
    });
    revalidatePath("/", "layout");
    return { ok: true, message: "Карточка контейнера сохранена" };
  } catch (error) {
    return { ok: false, error: `Не удалось сохранить: ${getErrorMessage(error)}` };
  }
}

export async function deleteContainerAction(id: string): Promise<ActionResult> {
  await requireSession();
  const container = await prisma.container.findUnique({ where: { id }, select: { bicCode: true, operationalStatus: true } });
  if (!container) return notFound("Контейнер");
  if (MANAGED_STATUSES.has(container.operationalStatus)) {
    return { ok: false, error: "Нельзя удалить контейнер в активном One-Way или аренде — сначала оформите возврат" };
  }
  await prisma.container.delete({ where: { id } });
  revalidatePath("/", "layout");
  return { ok: true, message: `Контейнер ${formatBic(container.bicCode)} списан из реестра` };
}

const eventSchema = z.object({
  type: z.enum(EVENT_TYPES),
  occurredAt: dateField,
  description: requiredText("описание", 1000),
  amountUsd: z.union([moneyField, z.literal("").transform(() => null), z.null()]).optional().transform((v) => v ?? null),
});

export async function addContainerEventAction(containerId: string, input: z.input<typeof eventSchema>): Promise<ActionResult> {
  const session = await requireSession();
  const parsed = parseInput(eventSchema, input);
  if (!parsed.ok) return parsed.result;
  const container = await prisma.container.findUnique({ where: { id: containerId }, select: { currentLocode: true, currentTerminal: true } });
  if (!container) return notFound("Контейнер");
  await prisma.containerEvent.create({
    data: {
      containerId,
      ...parsed.data,
      locode: container.currentLocode,
      terminal: container.currentTerminal,
      actor: session.name,
    },
  });
  revalidatePath(`/containers/${containerId}`);
  return { ok: true, message: "Событие добавлено в журнал" };
}

"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { prisma } from "@/lib/prisma";
import { requireSession } from "@/lib/auth/dal";
import { computeDeadline, computeTripTiming } from "@/lib/domain/one-way";
import { locodeCity } from "@/lib/domain/constants";
import { formatBic } from "@/lib/iso6346";
import { formatDate, formatUsd } from "@/lib/format";
import { startOfDayUtc } from "@/lib/dates";
import { getErrorMessage } from "@/lib/utils";
import { dateField, innField, locodeField, moneyField, notFound, optionalText, parseInput, requiredText } from "./helpers";
import type { ActionResult } from "./types";

const createTripSchema = z.object({
  containerId: z.string().min(1, "Выберите контейнер"),
  counterpartyName: requiredText("контрагент", 200),
  counterpartyInn: innField,
  counterpartyContact: optionalText(200),
  bookingRef: requiredText("номер заявки/договора", 60),
  dropoffLocode: locodeField,
  dropoffTerminal: requiredText("депо возврата", 120),
  handoverDate: dateField,
  freeDays: z.coerce.number().int().min(1, "Минимум 1 день").max(365, "Не более 365 дней"),
  feeUsd: moneyField,
  detentionRatePerDayUsd: moneyField,
  notes: optionalText(1000),
});

export type CreateTripInput = z.input<typeof createTripSchema>;

export async function createOneWayAction(input: CreateTripInput): Promise<ActionResult> {
  const session = await requireSession();
  const parsed = parseInput(createTripSchema, input);
  if (!parsed.ok) return parsed.result;
  const data = parsed.data;

  const container = await prisma.container.findUnique({ where: { id: data.containerId } });
  if (!container) return notFound("Контейнер");
  if (container.operationalStatus !== "AVAILABLE" || container.techStatus !== "SOUND") {
    return { ok: false, error: `${formatBic(container.bicCode)} недоступен для выдачи: нужен статус «Свободен» и тех. состояние «Исправен»` };
  }

  const deadline = computeDeadline(data.handoverDate, data.freeDays);
  try {
    const trip = await prisma.$transaction(async (tx) => {
      const created = await tx.oneWayTrip.create({
        data: {
          containerId: container.id,
          counterpartyName: data.counterpartyName,
          counterpartyInn: data.counterpartyInn,
          counterpartyContact: data.counterpartyContact,
          bookingRef: data.bookingRef,
          pickupLocode: container.currentLocode,
          pickupTerminal: container.currentTerminal,
          dropoffLocode: data.dropoffLocode,
          dropoffTerminal: data.dropoffTerminal,
          handoverDate: data.handoverDate,
          freeDays: data.freeDays,
          deadlineDate: deadline,
          feeUsd: data.feeUsd,
          detentionRatePerDayUsd: data.detentionRatePerDayUsd,
          status: "ACTIVE",
          notes: data.notes,
        },
      });
      await tx.container.update({
        where: { id: container.id },
        data: {
          operationalStatus: "ONE_WAY",
          currentTerminal: `Выдан: ${data.counterpartyName}`,
          storageStartDate: null,
          totalRevenueUsd: { increment: data.feeUsd },
          events: {
            create: {
              type: "ONE_WAY_OUT",
              occurredAt: new Date(),
              locode: container.currentLocode,
              terminal: container.currentTerminal,
              description: `Gate-Out: выдан в One-Way ${data.bookingRef} контрагенту ${data.counterpartyName}. Возврат: ${locodeCity(data.dropoffLocode)}, ${data.dropoffTerminal} до ${formatDate(deadline)} (${data.freeDays} своб. дней), детеншн ${formatUsd(data.detentionRatePerDayUsd)}/сут.`,
              amountUsd: data.feeUsd || null,
              actor: session.name,
            },
          },
        },
      });
      return created;
    });
    revalidatePath("/", "layout");
    return { ok: true, message: `${formatBic(container.bicCode)} выдан в One-Way до ${formatDate(deadline)}`, id: trip.id };
  } catch (error) {
    return { ok: false, error: `Не удалось оформить выдачу: ${getErrorMessage(error)}` };
  }
}

const returnSchema = z
  .object({
    returnDate: dateField,
    terminal: requiredText("терминал приёмки", 120),
    condition: z.enum(["SOUND", "DAMAGED"]),
    eorUsd: z.union([moneyField, z.literal("").transform(() => null), z.null()]).optional().transform((v) => v ?? null),
    note: optionalText(1000),
  })
  .superRefine((v, ctx) => {
    if (v.condition === "DAMAGED" && !v.eorUsd) ctx.addIssue({ code: "custom", path: ["eorUsd"], message: "Укажите оценку ремонта (EOR)" });
  });

export type TripReturnInput = z.input<typeof returnSchema>;

/** Gate-In по One-Way: закрывает рейс, начисляет детеншн, ставит контейнер на сток депо назначения. */
export async function registerOneWayReturnAction(tripId: string, input: TripReturnInput): Promise<ActionResult> {
  const session = await requireSession();
  const parsed = parseInput(returnSchema, input);
  if (!parsed.ok) return parsed.result;
  const data = parsed.data;

  const trip = await prisma.oneWayTrip.findUnique({ where: { id: tripId }, include: { container: true } });
  if (!trip) return notFound("Рейс One-Way");
  if (trip.status !== "ACTIVE") return { ok: false, error: "Возврат по этому рейсу уже зафиксирован" };
  if (data.returnDate < startOfDayUtc(trip.handoverDate)) return { ok: false, error: "Дата возврата раньше даты выдачи", fieldErrors: { returnDate: "Раньше даты выдачи" } };
  if (data.returnDate > new Date()) return { ok: false, error: "Дата возврата не может быть в будущем", fieldErrors: { returnDate: "Дата в будущем" } };

  const timing = computeTripTiming({ ...trip, status: "COMPLETED", actualReturnDate: data.returnDate }, new Date());
  const isDamaged = data.condition === "DAMAGED";
  const detentionNote = timing.overdueDays > 0 ? ` Просрочка ${timing.overdueDays} дн., начислен детеншн ${formatUsd(timing.detentionUsd)}.` : " Возврат в пределах свободных дней.";

  try {
    await prisma.$transaction([
      prisma.oneWayTrip.update({
        where: { id: trip.id },
        data: {
          status: isDamaged ? "DISPUTE" : "COMPLETED",
          actualReturnDate: data.returnDate,
          dropoffTerminal: data.terminal,
          returnCondition: data.condition,
          returnEorUsd: isDamaged ? data.eorUsd : null,
          notes: data.note ?? trip.notes,
        },
      }),
      prisma.container.update({
        where: { id: trip.containerId },
        data: {
          operationalStatus: "AVAILABLE",
          currentLocode: trip.dropoffLocode,
          currentTerminal: data.terminal,
          storageStartDate: data.returnDate,
          techStatus: isDamaged ? "DAMAGED" : trip.container.techStatus,
          conditionGrade: isDamaged ? "DAMAGED" : trip.container.conditionGrade,
          eorAmountUsd: isDamaged ? data.eorUsd : trip.container.eorAmountUsd,
          totalRevenueUsd: { increment: timing.detentionUsd },
          events: {
            create: [
              {
                type: "ONE_WAY_IN",
                occurredAt: new Date(),
                locode: trip.dropoffLocode,
                terminal: data.terminal,
                description: `Gate-In по One-Way ${trip.bookingRef} (${trip.counterpartyName}).${detentionNote}${isDamaged ? ` Повреждение при приёмке, открыта претензия (EOR ${formatUsd(data.eorUsd ?? 0)}).` : " Состояние: исправен."}${data.note ? ` ${data.note}` : ""}`,
                amountUsd: timing.detentionUsd || null,
                actor: session.name,
              },
              ...(isDamaged
                ? [{ type: "INSPECTION", occurredAt: new Date(), locode: trip.dropoffLocode, terminal: data.terminal, description: `Акт осмотра при приёмке: повреждение. EOR ${formatUsd(data.eorUsd ?? 0)}.`, amountUsd: data.eorUsd, actor: session.name }]
                : []),
            ],
          },
        },
      }),
    ]);
    revalidatePath("/", "layout");
    return {
      ok: true,
      message: `${formatBic(trip.container.bicCode)} принят на ${data.terminal}.${timing.detentionUsd > 0 ? ` Детеншн: ${formatUsd(timing.detentionUsd)}.` : ""}${isDamaged ? " Открыта претензия." : ""}`,
    };
  } catch (error) {
    return { ok: false, error: `Не удалось зафиксировать возврат: ${getErrorMessage(error)}` };
  }
}

const resolveSchema = z.object({ compensationUsd: moneyField, note: optionalText(500) });

export async function resolveDisputeAction(tripId: string, input: z.input<typeof resolveSchema>): Promise<ActionResult> {
  const session = await requireSession();
  const parsed = parseInput(resolveSchema, input);
  if (!parsed.ok) return parsed.result;
  const trip = await prisma.oneWayTrip.findUnique({ where: { id: tripId }, include: { container: { select: { bicCode: true, currentLocode: true, currentTerminal: true } } } });
  if (!trip) return notFound("Рейс One-Way");
  if (trip.status !== "DISPUTE") return { ok: false, error: "По рейсу нет открытой претензии" };

  const { compensationUsd, note } = parsed.data;
  await prisma.$transaction([
    prisma.oneWayTrip.update({ where: { id: tripId }, data: { status: "COMPLETED", notes: [trip.notes, `Претензия закрыта: компенсация ${formatUsd(compensationUsd)}. ${note ?? ""}`].filter(Boolean).join("\n") } }),
    prisma.container.update({
      where: { id: trip.containerId },
      data: {
        totalRevenueUsd: { increment: compensationUsd },
        events: {
          create: {
            type: "STATUS_CHANGE",
            occurredAt: new Date(),
            locode: trip.container.currentLocode,
            terminal: trip.container.currentTerminal,
            description: `Претензия по One-Way ${trip.bookingRef} урегулирована: компенсация ${formatUsd(compensationUsd)} от ${trip.counterpartyName}.${note ? ` ${note}` : ""}`,
            amountUsd: compensationUsd || null,
            actor: session.name,
          },
        },
      },
    }),
  ]);
  revalidatePath("/", "layout");
  return { ok: true, message: `Претензия по ${trip.bookingRef} закрыта` };
}

