              {!compact && (
                <p className="mt-1 flex flex-wrap gap-x-3 text-xs text-slate-400">
                  {event.locode && (
                    <span>
                      <span className="font-mono">{event.locode}</span> · {locodeCity(event.locode)}
                      {event.terminal ? `, ${event.terminal}` : ""}
                    </span>
                  )}
                  {event.actor && <span>{event.actor}</span>}
                  {event.amountUsd ? <span className="font-mono text-slate-500">{formatUsd(event.amountUsd)}</span> : null}
                </p>
              )}
            </div>
          </li>
        );
      })}
    </ol>
  );
}

"use client";

import { useState } from "react";
import { CircleCheck, TriangleAlert } from "lucide-react";
import { createContainerAction, updateContainerAction, type ContainerInput } from "@/actions/containers";
import { Button } from "@/components/ui/button";
import { Field, Input, Select, Textarea } from "@/components/ui/primitives";
import { useServerAction } from "@/components/use-server-action";
import {
  CONDITION_GRADES,
  CONDITION_GRADE_LABELS,
  DEFAULT_ISO_CODE,
  DEFAULT_WEIGHTS,
  LOCATIONS,
  OPERATIONAL_STATUSES,
  OPERATIONAL_STATUS_LABELS,
  SIZE_TYPES,
  SIZE_TYPE_LABELS,
  TECH_STATUSES,
  TECH_STATUS_LABELS,
  isOneOf,
  terminalsOf,
} from "@/lib/domain/constants";
import { formatBic, validateBic } from "@/lib/iso6346";
import { addDays, toDateInput } from "@/lib/dates";
import { formatNumber } from "@/lib/format";

export interface ContainerFormValues {
  bicCode: string;
  sizeType: string;
  isoCode: string;
  manufactureYear: string;
  colorRal: string;
  manufacturer: string;
  tareWeightKg: string;
  maxGrossWeightKg: string;
  conditionGrade: string;
  techStatus: string;
  cscPlateExpiry: string;
  eorAmountUsd: string;
  operationalStatus: string;
  currentLocode: string;
  currentTerminal: string;
  storageRatePerDayUsd: string;
  purchaseDate: string;
  purchasePriceUsd: string;
  currentBookValueUsd: string;
  notes: string;
}

export function emptyContainerForm(): ContainerFormValues {
  const today = new Date();
  return {
    bicCode: "",
    sizeType: "40HC",
    isoCode: DEFAULT_ISO_CODE["40HC"],
    manufactureYear: String(today.getUTCFullYear()),
    colorRal: "RAL 5013 (кобальтовый синий)",
    manufacturer: "CIMC Qingdao",
    tareWeightKg: String(DEFAULT_WEIGHTS["40HC"].tare),
    maxGrossWeightKg: String(DEFAULT_WEIGHTS["40HC"].gross),
    conditionGrade: "IICL6",
    techStatus: "SOUND",
    cscPlateExpiry: toDateInput(addDays(today, 365 * 5)),
    eorAmountUsd: "",
    operationalStatus: "AVAILABLE",
    currentLocode: "CNSHA",
    currentTerminal: "Shanghai SIPG",
    storageRatePerDayUsd: "2",
    purchaseDate: toDateInput(today),
    purchasePriceUsd: "4350",
    currentBookValueUsd: "4350",
    notes: "",
  };
}

interface ContainerFormProps {
  containerId?: string;
  initial: ContainerFormValues;
  onDone: (id?: string) => void;
}

const FORM_ID = "container-form";

export function ContainerForm({ containerId, initial, onDone }: ContainerFormProps) {
  const [values, setValues] = useState(initial);
  const { run, isPending, fieldErrors } = useServerAction();
  const isEdit = Boolean(containerId);
  const bic = validateBic(values.bicCode);
  const isManaged = values.operationalStatus === "ONE_WAY" || values.operationalStatus === "LONG_TERM_LEASE";
  const terminals = terminalsOf(values.currentLocode);
  const payload = Number(values.maxGrossWeightKg) - Number(values.tareWeightKg);

  function set<K extends keyof ContainerFormValues>(key: K, value: ContainerFormValues[K]) {
    setValues((prev) => ({ ...prev, [key]: value }));
  }

  function handleSizeChange(size: string) {
    if (!isOneOf(SIZE_TYPES, size)) return;
    setValues((prev) => ({
      ...prev,
      sizeType: size,
      isoCode: DEFAULT_ISO_CODE[size],
      tareWeightKg: String(DEFAULT_WEIGHTS[size].tare),
      maxGrossWeightKg: String(DEFAULT_WEIGHTS[size].gross),
    }));
  }

  function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const input: ContainerInput = { ...values, eorAmountUsd: values.eorAmountUsd, storageRatePerDayUsd: values.storageRatePerDayUsd } as ContainerInput;
    run(
      () => (containerId ? updateContainerAction(containerId, input) : createContainerAction(input)),
      (result) => onDone(result.id),
    );
  }

  const err = (key: string) => fieldErrors[key];

  return (
    <>
      <form id={FORM_ID} onSubmit={handleSubmit} className="space-y-6">
        <fieldset className="space-y-3">
          <legend className="mb-1 text-xs font-semibold tracking-wide text-slate-400 uppercase">Паспорт и идентификация</legend>
          <Field label="Номер контейнера (ISO 6346)" htmlFor="bicCode" error={err("bicCode")}>
            <Input
              id="bicCode"
              value={values.bicCode}
              onChange={(e) => set("bicCode", e.target.value.toUpperCase())}
              placeholder="EXEX 402918-4"
              className="font-mono text-base tracking-wide uppercase"
              aria-invalid={values.bicCode.length > 0 && !bic.valid}
              autoComplete="off"
              required
            />
          </Field>
          {values.bicCode.length >= 10 && (
            <div className={`rounded-lg px-3 py-2 text-xs ring-1 ${bic.valid ? "bg-emerald-50 text-emerald-800 ring-emerald-200" : "bg-rose-50 text-rose-800 ring-rose-200"}`}>
              {bic.valid ? (
                <p className="flex items-center gap-1.5">
                  <CircleCheck className="size-3.5" /> Номер корректен: <span className="font-mono font-semibold">{formatBic(bic.normalized)}</span>
                </p>
              ) : (
                <p className="flex items-center gap-1.5">
                  <TriangleAlert className="size-3.5" /> {bic.errors[0]}
                  {bic.expectedCheckDigit !== null && (
                    <button type="button" className="ml-auto font-medium underline" onClick={() => set("bicCode", formatBic(bic.normalized.slice(0, 10) + bic.expectedCheckDigit))}>
                      Подставить
                    </button>
                  )}
                </p>
              )}
              {bic.warnings.map((w) => (
                <p key={w} className="mt-1 text-amber-700">⚠ {w}</p>
              ))}
            </div>
          )}
          <div className="grid grid-cols-2 gap-3">
            <Field label="Типоразмер" htmlFor="sizeType" error={err("sizeType")}>
              <Select id="sizeType" value={values.sizeType} onChange={(e) => handleSizeChange(e.target.value)}>
                {SIZE_TYPES.map((s) => (
                  <option key={s} value={s}>{SIZE_TYPE_LABELS[s]}</option>
                ))}
              </Select>
            </Field>
            <Field label="ISO-код типа" htmlFor="isoCode" error={err("isoCode")}>
              <Input id="isoCode" value={values.isoCode} onChange={(e) => set("isoCode", e.target.value.toUpperCase())} className="font-mono" maxLength={4} />
            </Field>
            <Field label="Год выпуска" htmlFor="manufactureYear" error={err("manufactureYear")}>
              <Input id="manufactureYear" type="number" inputMode="numeric" value={values.manufactureYear} onChange={(e) => set("manufactureYear", e.target.value)} />
            </Field>
            <Field label="Цвет (RAL)" htmlFor="colorRal" error={err("colorRal")}>
              <Input id="colorRal" value={values.colorRal} onChange={(e) => set("colorRal", e.target.value)} />
            </Field>
            <Field label="Завод-изготовитель" htmlFor="manufacturer" error={err("manufacturer")} className="col-span-2">
              <Input id="manufacturer" value={values.manufacturer} onChange={(e) => set("manufacturer", e.target.value)} />
            </Field>
            <Field label="Тара, кг" htmlFor="tare" error={err("tareWeightKg")}>
              <Input id="tare" type="number" inputMode="numeric" value={values.tareWeightKg} onChange={(e) => set("tareWeightKg", e.target.value)} />
            </Field>
            <Field label="Брутто (MGW), кг" htmlFor="gross" error={err("maxGrossWeightKg")} hint={payload > 0 ? `Макс. загрузка: ${formatNumber(payload)} кг` : undefined}>
              <Input id="gross" type="number" inputMode="numeric" value={values.maxGrossWeightKg} onChange={(e) => set("maxGrossWeightKg", e.target.value)} />
            </Field>
          </div>
        </fieldset>

        <fieldset className="space-y-3">
          <legend className="mb-1 text-xs font-semibold tracking-wide text-slate-400 uppercase">Техническое состояние</legend>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Грейд" htmlFor="grade" error={err("conditionGrade")}>
              <Select id="grade" value={values.conditionGrade} onChange={(e) => set("conditionGrade", e.target.value)}>
                {CONDITION_GRADES.map((g) => (
                  <option key={g} value={g}>{CONDITION_GRADE_LABELS[g]}</option>
                ))}
              </Select>
            </Field>
            <Field label="Тех. статус" htmlFor="tech" error={err("techStatus")}>
              <Select id="tech" value={values.techStatus} onChange={(e) => set("techStatus", e.target.value)}>
                {TECH_STATUSES.map((t) => (
                  <option key={t} value={t}>{TECH_STATUS_LABELS[t]}</option>
                ))}
              </Select>
            </Field>
            <Field label="КБК (CSC) действует до" htmlFor="csc" error={err("cscPlateExpiry")}>
              <Input id="csc" type="date" value={values.cscPlateExpiry} onChange={(e) => set("cscPlateExpiry", e.target.value)} />
            </Field>
            <Field label="EOR, $" htmlFor="eor" error={err("eorAmountUsd")} hint="Оценка ремонта">
              <Input id="eor" type="number" inputMode="decimal" min={0} value={values.eorAmountUsd} onChange={(e) => set("eorAmountUsd", e.target.value)} />
            </Field>
          </div>
        </fieldset>

        <fieldset className="space-y-3">
          <legend className="mb-1 text-xs font-semibold tracking-wide text-slate-400 uppercase">Дислокация</legend>
          <Field label="Операционный статус" htmlFor="op" error={err("operationalStatus")} hint={isManaged ? "Управляется модулем One-Way / аренды" : undefined}>
            <Select id="op" value={values.operationalStatus} onChange={(e) => set("operationalStatus", e.target.value)} disabled={isEdit && isManaged}>
              {OPERATIONAL_STATUSES.map((s) => (
                <option key={s} value={s} disabled={(s === "ONE_WAY" || s === "LONG_TERM_LEASE") && !isManaged}>
                  {OPERATIONAL_STATUS_LABELS[s]}
                </option>
              ))}
            </Select>
          </Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label="UN/LOCODE" htmlFor="locode" error={err("currentLocode")}>
              <Select
                id="locode"
                value={values.currentLocode}
                disabled={isManaged}
                onChange={(e) => setValues((prev) => ({ ...prev, currentLocode: e.target.value, currentTerminal: terminalsOf(e.target.value)[0] ?? "" }))}
              >
                {LOCATIONS.map((l) => (
                  <option key={l.code} value={l.code}>{l.code} · {l.city}</option>
                ))}
              </Select>
            </Field>
            <Field label="Терминал / депо" htmlFor="terminal" error={err("currentTerminal")}>
              <Input id="terminal" list="terminal-options" value={values.currentTerminal} disabled={isManaged} onChange={(e) => set("currentTerminal", e.target.value)} />
              <datalist id="terminal-options">
                {terminals.map((t) => (
                  <option key={t} value={t} />
                ))}
              </datalist>
            </Field>
            <Field label="Хранение, $/сутки" htmlFor="storageRate" error={err("storageRatePerDayUsd")}>
              <Input id="storageRate" type="number" inputMode="decimal" step="0.1" min={0} value={values.storageRatePerDayUsd} onChange={(e) => set("storageRatePerDayUsd", e.target.value)} />
            </Field>
          </div>
        </fieldset>

        <fieldset className="space-y-3">
          <legend className="mb-1 text-xs font-semibold tracking-wide text-slate-400 uppercase">Финансы</legend>
          <div className="grid grid-cols-2 gap-3">
            <Field label="Дата покупки" htmlFor="purchaseDate" error={err("purchaseDate")}>
              <Input id="purchaseDate" type="date" value={values.purchaseDate} onChange={(e) => set("purchaseDate", e.target.value)} />
            </Field>
            <Field label="Цена покупки, $" htmlFor="price" error={err("purchasePriceUsd")}>
              <Input id="price" type="number" inputMode="decimal" min={0} value={values.purchasePriceUsd} onChange={(e) => set("purchasePriceUsd", e.target.value)} />
            </Field>
            <Field label="Остаточная стоимость, $" htmlFor="book" error={err("currentBookValueUsd")} className="col-span-2">
              <Input id="book" type="number" inputMode="decimal" min={0} value={values.currentBookValueUsd} onChange={(e) => set("currentBookValueUsd", e.target.value)} />
            </Field>
          </div>
          <Field label="Примечания" htmlFor="notes" error={err("notes")}>
            <Textarea id="notes" value={values.notes} onChange={(e) => set("notes", e.target.value)} rows={3} />
          </Field>
        </fieldset>
      </form>
    </>
  );
}

export function ContainerFormFooter({ isEdit, onCancel }: { isEdit: boolean; onCancel: () => void }) {
  return (
    <div className="flex gap-2">
      <Button variant="outline" className="flex-1 lg:flex-none" onClick={onCancel}>
        Отмена
      </Button>
      <Button type="submit" form={FORM_ID} className="flex-1">
        {isEdit ? "Сохранить изменения" : "Добавить в парк"}
      </Button>
    </div>
  );
}

input.content:
"use client";

import Link from "next/link";
import { useMemo, useState } from "react";
import { ArrowDown, ArrowUp, ArrowUpDown, ChevronRight, MapPin, PackageOpen, Plus, Search, SlidersHorizontal, TriangleAlert, X } from "lucide-react";
import { Button, buttonClasses } from "@/components/ui/button";
import { Badge, Card, DataList, EmptyState, Input, Select } from "@/components/ui/primitives";
import { Sheet } from "@/components/ui/sheet";
import { BicCode, CscBadge, GradeBadge, OperationalStatusBadge, TechStatusBadge } from "@/components/status-badges";
import { EventTimeline } from "./event-timeline";
import { ContainerForm, emptyContainerForm } from "./container-form";
import {
  CONDITION_GRADES,
  CONDITION_GRADE_LABELS,
  LOCATIONS,
  OPERATIONAL_STATUSES,
  OPERATIONAL_STATUS_LABELS,
  SIZE_TYPES,
  TECH_STATUSES,
  TECH_STATUS_LABELS,
  locodeCity,
} from "@/lib/domain/constants";
import { normalizeBic } from "@/lib/iso6346";
import { formatDate, formatDays, formatPercent, formatUsd } from "@/lib/format";
import { cn } from "@/lib/utils";
import type { ContainerRow } from "@/lib/queries/containers";

export interface RegistryFilters {
  q: string;
  locode: string;
  size: string;
  status: string;
  grade: string;
  tech: string;
  attention: boolean;
}

type SortKey = "bicCode" | "sizeType" | "operationalStatus" | "currentLocode" | "csc" | "idle" | "roi";
type SortState = { key: SortKey; dir: "asc" | "desc" };

const EMPTY_FILTERS: RegistryFilters = { q: "", locode: "", size: "", status: "", grade: "", tech: "", attention: false };

function sortValue(row: ContainerRow, key: SortKey): string | number {
  switch (key) {
    case "csc":
      return row.csc.daysLeft;
    case "idle":
      return row.idleDays ?? -1;
    case "roi":
      return row.roi;
    default:
      return row[key];
  }
}

function matches(row: ContainerRow, f: RegistryFilters): boolean {
  const q = normalizeBic(f.q);
  if (q && !row.bicCode.includes(q)) return false;
  if (f.locode && row.currentLocode !== f.locode) return false;
  if (f.size && row.sizeType !== f.size) return false;
  if (f.status && row.operationalStatus !== f.status) return false;
  if (f.grade && row.conditionGrade !== f.grade) return false;
  if (f.tech && row.techStatus !== f.tech) return false;
  if (f.attention && !row.needsAttention) return false;
  return true;
}

interface ContainerRegistryProps {
  rows: ContainerRow[];
  initialFilters: Partial<RegistryFilters>;
}

export function ContainerRegistry({ rows, initialFilters }: ContainerRegistryProps) {
  const [filters, setFilters] = useState<RegistryFilters>({ ...EMPTY_FILTERS, ...initialFilters });
  const [sort, setSort] = useState<SortState>({ key: "bicCode", dir: "asc" });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);

  const visible = useMemo(() => {
    const filtered = rows.filter((r) => matches(r, filters));
    const factor = sort.dir === "asc" ? 1 : -1;
    return [...filtered].sort((a, b) => {
      const av = sortValue(a, sort.key);
      const bv = sortValue(b, sort.key);
      return (typeof av === "number" && typeof bv === "number" ? av - bv : String(av).localeCompare(String(bv))) * factor;
    });
  }, [rows, filters, sort]);

  const selected = rows.find((r) => r.id === selectedId) ?? null;
  const activeFilterCount = [filters.locode, filters.size, filters.status, filters.grade, filters.tech].filter(Boolean).length + (filters.attention ? 1 : 0);
  const usedLocodes = LOCATIONS.filter((l) => rows.some((r) => r.currentLocode === l.code));

  function update<K extends keyof RegistryFilters>(key: K, value: RegistryFilters[K]) {
    setFilters((prev) => ({ ...prev, [key]: value }));
  }

  function toggleSort(key: SortKey) {
    setSort((prev) => (prev.key === key ? { key, dir: prev.dir === "asc" ? "desc" : "asc" } : { key, dir: "asc" }));
  }

  const filterControls = (
    <>
      <Select aria-label="Локация" value={filters.locode} onChange={(e) => update("locode", e.target.value)}>
        <option value="">Все локации</option>
        {usedLocodes.map((l) => (
          <option key={l.code} value={l.code}>{l.code} · {l.city}</option>
        ))}
      </Select>
      <Select aria-label="Типоразмер" value={filters.size} onChange={(e) => update("size", e.target.value)}>
        <option value="">Все типоразмеры</option>
        {SIZE_TYPES.map((s) => (
          <option key={s} value={s}>{s}</option>
        ))}
      </Select>
      <Select aria-label="Статус" value={filters.status} onChange={(e) => update("status", e.target.value)}>
        <option value="">Все статусы</option>
        {OPERATIONAL_STATUSES.map((s) => (
          <option key={s} value={s}>{OPERATIONAL_STATUS_LABELS[s]}</option>
        ))}
      </Select>
      <Select aria-label="Грейд" value={filters.grade} onChange={(e) => update("grade", e.target.value)}>
        <option value="">Все грейды</option>
        {CONDITION_GRADES.map((g) => (
          <option key={g} value={g}>{CONDITION_GRADE_LABELS[g]}</option>
        ))}
      </Select>
      <Select aria-label="Тех. статус" value={filters.tech} onChange={(e) => update("tech", e.target.value)}>
        <option value="">Любое тех. состояние</option>
        {TECH_STATUSES.map((t) => (
          <option key={t} value={t}>{TECH_STATUS_LABELS[t]}</option>
        ))}
      </Select>
    </>
  );

  return (
    <>
      {/* Панель поиска и фильтров */}
      <div className="sticky top-14 z-20 -mx-4 mb-4 space-y-3 bg-slate-50/95 px-4 py-2 backdrop-blur sm:-mx-6 sm:px-6 lg:static lg:mx-0 lg:bg-transparent lg:p-0 lg:backdrop-blur-none">
        <div className="flex gap-2">
          <div className="relative flex-1">
            <Search className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-slate-400" aria-hidden />
            <Input
              value={filters.q}
              onChange={(e) => update("q", e.target.value)}
              placeholder="Поиск по номеру: EXEX, 2918, 402918-4…"
              className="pl-9 font-mono"
              aria-label="Поиск по номеру контейнера"
              inputMode="search"
            />
            {filters.q && (
              <button type="button" onClick={() => update("q", "")} className="absolute top-1/2 right-2 -translate-y-1/2 rounded p-1 text-slate-400 hover:text-slate-700" aria-label="Очистить поиск">
                <X className="size-4" />
              </button>
            )}
          </div>
          <Button variant="outline" size="icon" className="relative h-11 w-11 lg:hidden" onClick={() => setFiltersOpen(true)} aria-label="Фильтры">
            <SlidersHorizontal />
            {activeFilterCount > 0 && <span className="absolute -top-1 -right-1 rounded-full bg-indigo-600 px-1.5 text-[10px] leading-4 font-semibold text-white">{activeFilterCount}</span>}
          </Button>
          <Button className="h-11 lg:h-10" onClick={() => setCreateOpen(true)}>
            <Plus />
            <span className="hidden sm:inline">Добавить</span>
          </Button>
        </div>
        <div className="hidden gap-2 lg:grid lg:grid-cols-5">{filterControls}</div>
        <div className="flex flex-wrap items-center gap-2 text-sm">
          <button
            type="button"
            onClick={() => update("attention", !filters.attention)}
            aria-pressed={filters.attention}
            className={cn(
              "inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-medium ring-1 transition-colors",
              filters.attention ? "bg-amber-500 text-white ring-amber-500" : "bg-white text-slate-600 ring-slate-200 hover:ring-slate-300",
            )}
          >
            <TriangleAlert className="size-3.5" /> Требуют внимания
          </button>
          <span className="text-xs text-slate-500">
            Найдено: <span className="font-mono font-semibold text-slate-900">{visible.length}</span> из {rows.length}
          </span>
          {(activeFilterCount > 0 || filters.q) && (
            <button type="button" onClick={() => setFilters(EMPTY_FILTERS)} className="text-xs font-medium text-indigo-600 hover:underline">
              Сбросить фильтры
            </button>
          )}
        </div>
      </div>

      {visible.length === 0 ? (
        <Card>
          <EmptyState icon={<PackageOpen />} title="Ничего не найдено" description="Измените условия поиска или сбросьте фильтры." action={<Button variant="outline" onClick={() => setFilters(EMPTY_FILTERS)}>Сбросить фильтры</Button>} />
        </Card>
      ) : (
        <>
          {/* ПК: таблица */}
          <Card className="hidden overflow-hidden lg:block">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-slate-50 text-left text-xs text-slate-500">
                  <tr>
                    <SortHeader label="Номер" sortKey="bicCode" sort={sort} onSort={toggleSort} />
                    <SortHeader label="Тип" sortKey="sizeType" sort={sort} onSort={toggleSort} />
                    <SortHeader label="Статус / операция" sortKey="operationalStatus" sort={sort} onSort={toggleSort} />
                    <SortHeader label="Локация" sortKey="currentLocode" sort={sort} onSort={toggleSort} />
                    <th className="px-3 py-2.5 font-medium">Состояние</th>
                    <SortHeader label="КБК" sortKey="csc" sort={sort} onSort={toggleSort} />
                    <SortHeader label="На стоке" sortKey="idle" sort={sort} onSort={toggleSort} align="right" />
                    <SortHeader label="ROI" sortKey="roi" sort={sort} onSort={toggleSort} align="right" />
                    <th className="w-8" />
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {visible.map((row) => (
                    <tr
                      key={row.id}
                      onClick={() => setSelectedId(row.id)}
                      className={cn("cursor-pointer transition-colors hover:bg-indigo-50/40", selectedId === row.id && "bg-indigo-50/60", row.needsAttention && "border-l-2 border-l-amber-400")}
                    >
                      <td className="px-3 py-3">
                        <BicCode code={row.bicCode} />
                        <p className="text-xs text-slate-400">{row.manufactureYear} · {row.manufacturer.split(" ")[0]}</p>
                      </td>
                      <td className="px-3 py-3">
                        <span className="font-mono font-medium">{row.sizeType}</span>
                        <p className="font-mono text-xs text-slate-400">{row.isoCode}</p>
                      </td>
                      <td className="px-3 py-3">
                        <OperationalStatusBadge status={row.operationalStatus} />
                        {row.activity && <p className="mt-1 max-w-56 truncate text-xs text-slate-500">{row.activity}</p>}
                      </td>
                      <td className="px-3 py-3">
                        <span className="font-mono text-xs font-semibold text-slate-700">{row.currentLocode}</span>
                        <p className="max-w-44 truncate text-xs text-slate-500">{row.currentTerminal}</p>
                      </td>
                      <td className="px-3 py-3">
                        <div className="flex flex-wrap gap-1">
                          <GradeBadge grade={row.conditionGrade} />
                          {row.techStatus !== "SOUND" && <TechStatusBadge status={row.techStatus} />}
                        </div>
                        {row.eorAmountUsd ? <p className="mt-1 font-mono text-xs text-orange-600">EOR {formatUsd(row.eorAmountUsd)}</p> : null}
                      </td>
                      <td className="px-3 py-3">
                        {row.csc.level === "OK" ? <span className="font-mono text-xs text-slate-500">{formatDate(row.cscPlateExpiry)}</span> : <CscBadge csc={row.csc} />}
                      </td>
                      <td className="px-3 py-3 text-right">
                        {row.idleDays !== null ? (
                          <span className={cn("font-mono text-xs", row.isIdleTooLong ? "font-semibold text-violet-700" : "text-slate-600")}>{formatDays(row.idleDays)}</span>
                        ) : (
                          <span className="text-slate-300">—</span>
                        )}
                      </td>
                      <td className={cn("px-3 py-3 text-right font-mono text-xs font-medium", row.roi >= 0 ? "text-emerald-600" : "text-rose-600")}>{formatPercent(row.roi)}</td>
                      <td className="pr-3 text-slate-300"><ChevronRight className="size-4" /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Card>

          {/* Телефон / планшет: карточки */}
          <ul className="grid gap-3 sm:grid-cols-2 lg:hidden">
            {visible.map((row) => (
              <li key={row.id}>
                <button
                  type="button"
                  onClick={() => setSelectedId(row.id)}
                  className={cn("w-full rounded-xl border bg-white p-4 text-left shadow-sm transition active:scale-[0.99]", row.needsAttention ? "border-amber-300" : "border-slate-200")}
                >
                  <div className="flex items-start justify-between gap-2">
                    <BicCode code={row.bicCode} size="lg" />
                    <span className="rounded-md bg-slate-100 px-2 py-0.5 font-mono text-xs font-semibold text-slate-700">{row.sizeType}</span>
                  </div>
                  <div className="mt-2 flex flex-wrap gap-1.5">
                    <OperationalStatusBadge status={row.operationalStatus} />
                    <GradeBadge grade={row.conditionGrade} />
                    {row.techStatus !== "SOUND" && <TechStatusBadge status={row.techStatus} />}
                  </div>
                  <p className="mt-2.5 flex items-center gap-1.5 text-sm text-slate-600">
                    <MapPin className="size-3.5 shrink-0 text-slate-400" />
                    <span className="truncate">{locodeCity(row.currentLocode)} · {row.currentTerminal}</span>
                  </p>
                  {row.activity && <p className="mt-1 truncate text-xs text-slate-500">{row.activity}</p>}
                  {(row.csc.level !== "OK" || row.isIdleTooLong || row.eorAmountUsd) && (
                    <div className="mt-2.5 flex flex-wrap gap-1.5 border-t border-dashed border-slate-200 pt-2.5">
                      <CscBadge csc={row.csc} />
                      {row.isIdleTooLong && <Badge tone="violet">Простой {formatDays(row.idleDays ?? 0)}</Badge>}
                      {row.eorAmountUsd ? <Badge tone="orange">EOR {formatUsd(row.eorAmountUsd)}</Badge> : null}
                    </div>
                  )}
                </button>
              </li>
            ))}
          </ul>
        </>
      )}

      {/* Быстрый просмотр */}
      <Sheet
        open={selected !== null}
        onClose={() => setSelectedId(null)}
        title={selected ? <BicCode code={selected.bicCode} size="lg" /> : ""}
        description={selected ? `${selected.sizeType} · ISO ${selected.isoCode} · ${selected.manufactureYear} г.` : undefined}
        footer={
          selected && (
            <Link href={`/containers/${selected.id}`} className={buttonClasses("default", "lg", "w-full")}>
              Открыть полный профиль <ChevronRight />
            </Link>
          )
        }
      >
        {selected && <QuickView row={selected} />}
      </Sheet>

      {/* Фильтры (моб.) */}
      <Sheet open={filtersOpen} onClose={() => setFiltersOpen(false)} title="Фильтры" footer={<Button size="lg" className="w-full" onClick={() => setFiltersOpen(false)}>Показать {visible.length}</Button>}>
        <div className="space-y-3">{filterControls}</div>
      </Sheet>

      {/* Создание */}
      <Sheet open={createOpen} onClose={() => setCreateOpen(false)} title="Новый контейнер" description="Номер проверяется по ISO 6346 с расчётом контрольной цифры" size="lg">
        <ContainerForm initial={emptyContainerForm()} onDone={() => setCreateOpen(false)} />
      </Sheet>
    </>
  );
}

function SortHeader({ label, sortKey, sort, onSort, align = "left" }: { label: string; sortKey: SortKey; sort: SortState; onSort: (k: SortKey) => void; align?: "left" | "right" }) {
  const active = sort.key === sortKey;
  const Icon = !active ? ArrowUpDown : sort.dir === "asc" ? ArrowUp : ArrowDown;
  return (
    <th className={cn("px-3 py-2.5 font-medium", align === "right" && "text-right")} aria-sort={active ? (sort.dir === "asc" ? "ascending" : "descending") : "none"}>
      <button type="button" onClick={() => onSort(sortKey)} className={cn("inline-flex items-center gap-1 hover:text-slate-900", active && "text-slate-900")}>
        {label}
        <Icon className={cn("size-3", !active && "opacity-40")} />
      </button>
    </th>
  );
}

function QuickView({ row }: { row: ContainerRow }) {
  return (
    <div className="space-y-5">
      <div className="flex flex-wrap gap-1.5">
        <OperationalStatusBadge status={row.operationalStatus} />
        <TechStatusBadge status={row.techStatus} />
        <GradeBadge grade={row.conditionGrade} full />
        <CscBadge csc={row.csc} />
      </div>
      {row.activity && (
        <Link href={row.activityHref ?? "#"} className="flex items-center justify-between rounded-lg bg-indigo-50 px-3 py-2.5 text-sm text-indigo-800 ring-1 ring-indigo-100 hover:bg-indigo-100">
          <span className="truncate">{row.activity}</span>
          {row.tripTiming && (
            <span className={cn("ml-2 shrink-0 font-mono text-xs font-semibold", row.tripTiming.status === "OVERDUE" ? "text-rose-600" : "text-indigo-700")}>
              {row.tripTiming.status === "OVERDUE" ? `+${row.tripTiming.overdueDays} дн.` : `${row.tripTiming.daysLeft} дн.`}
            </span>
          )}
        </Link>
      )}
      <DataList
        items={[
          { label: "Локация", value: `${row.currentLocode} · ${locodeCity(row.currentLocode)}` },
          { label: "Терминал / депо", value: row.currentTerminal },
          { label: "КБК (CSC) до", value: formatDate(row.cscPlateExpiry), mono: true },
          { label: "EOR", value: row.eorAmountUsd ? formatUsd(row.eorAmountUsd) : "—", mono: true },
          { label: "На стоке", value: row.idleDays !== null ? `${formatDays(row.idleDays)} · ${formatUsd(row.storageCostUsd)}` : "—" },
          { label: "Выручка / ROI", value: `${formatUsd(Math.round(row.totalRevenueUsd))} · ${formatPercent(row.roi)}`, mono: true },
        ]}
      />
      <div>
        <h3 className="mb-3 text-xs font-semibold tracking-wide text-slate-400 uppercase">Последние события</h3>
        <EventTimeline events={row.recentEvents} compact />
      </div>
    </div>
  );
}

import type { Metadata } from "next";
import { PageHeader } from "@/components/ui/primitives";
import { ContainerRegistry, type RegistryFilters } from "@/components/containers/container-registry";
import { getContainerRows } from "@/lib/queries/containers";
import { teuOf } from "@/lib/domain/constants";

export const metadata: Metadata = { title: "Реестр контейнеров" };

type SearchParams = Promise<Record<string, string | string[] | undefined>>;

function first(value: string | string[] | undefined): string {
  return (Array.isArray(value) ? value[0] : value) ?? "";
}

export default async function ContainersPage({ searchParams }: { searchParams: SearchParams }) {
  const params = await searchParams;
  const rows = await getContainerRows(new Date());
  const initialFilters: Partial<RegistryFilters> = {
    q: first(params.q),
    status: first(params.status),
    locode: first(params.locode),
    size: first(params.size),
    tech: first(params.tech),
    attention: first(params.attention) === "1",
  };
  const teu = rows.reduce((s, r) => s + teuOf(r.sizeType), 0);

  return (
    <>
      <PageHeader title="Реестр контейнеров" description={`База парка SOC: ${rows.length} ед. · ${teu} TEU. Нажмите на строку для быстрого просмотра.`} />
      <ContainerRegistry rows={rows} initialFilters={initialFilters} />
    </>
  );
}

toolUseResult.content:
"use client";

import Link from "next/link";
import { useMemo, useState } from "react";
import { ArrowDown, ArrowUp, ArrowUpDown, ChevronRight, MapPin, PackageOpen, Plus, Search, SlidersHorizontal, TriangleAlert, X } from "lucide-react";
import { Button, buttonClasses } from "@/components/ui/button";
import { Badge, Card, DataList, EmptyState, Input, Select } from "@/components/ui/primitives";
import { Sheet } from "@/components/ui/sheet";
import { BicCode, CscBadge, GradeBadge, OperationalStatusBadge, TechStatusBadge } from "@/components/status-badges";
import { EventTimeline } from "./event-timeline";
import { ContainerForm, emptyContainerForm } from "./container-form";
import {
  CONDITION_GRADES,
  CONDITION_GRADE_LABELS,
  LOCATIONS,
  OPERATIONAL_STATUSES,
  OPERATIONAL_STATUS_LABELS,
  SIZE_TYPES,
  TECH_STATUSES,
  TECH_STATUS_LABELS,
  locodeCity,
} from "@/lib/domain/constants";
import { normalizeBic } from "@/lib/iso6346";
import { formatDate, formatDays, formatPercent, formatUsd } from "@/lib/format";
import { cn } from "@/lib/utils";
import type { ContainerRow } from "@/lib/queries/containers";

export interface RegistryFilters {
  q: string;
  locode: string;
  size: string;
  status: string;
  grade: string;
  tech: string;
  attention: boolean;
}

type SortKey = "bicCode" | "sizeType" | "operationalStatus" | "currentLocode" | "csc" | "idle" | "roi";
type SortState = { key: SortKey; dir: "asc" | "desc" };

const EMPTY_FILTERS: RegistryFilters = { q: "", locode: "", size: "", status: "", grade: "", tech: "", attention: false };

function sortValue(row: ContainerRow, key: SortKey): string | number {
  switch (key) {
    case "csc":
      return row.csc.daysLeft;
    case "idle":
      return row.idleDays ?? -1;
    case "roi":
      return row.roi;
    default:
      return row[key];
  }
}

function matches(row: ContainerRow, f: RegistryFilters): boolean {
  const q = normalizeBic(f.q);
  if (q && !row.bicCode.includes(q)) return false;
  if (f.locode && row.currentLocode !== f.locode) return false;
  if (f.size && row.sizeType !== f.size) return false;
  if (f.status && row.operationalStatus !== f.status) return false;
  if (f.grade && row.conditionGrade !== f.grade) return false;
  if (f.tech && row.techStatus !== f.tech) return false;
  if (f.attention && !row.needsAttention) return false;
  return true;
}

interface ContainerRegistryProps {
  rows: ContainerRow[];
  initialFilters: Partial<RegistryFilters>;
}

export function ContainerRegistry({ rows, initialFilters }: ContainerRegistryProps) {
  const [filters, setFilters] = useState<RegistryFilters>({ ...EMPTY_FILTERS, ...initialFilters });
  const [sort, setSort] = useState<SortState>({ key: "bicCode", dir: "asc" });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);

  const visible = useMemo(() => {
    const filtered = rows.filter((r) => matches(r, filters));
    const factor = sort.dir === "asc" ? 1 : -1;
    return [...filtered].sort((a, b) => {
      const av = sortValue(a, sort.key);
      const bv = sortValue(b, sort.key);
      return (typeof av === "number" && typeof bv === "number" ? av - bv : String(av).localeCompare(String(bv))) * factor;
    });
  }, [rows, filters, sort]);

  const selected = rows.find((r) => r.id === selectedId) ?? null;
  const activeFilterCount = [filters.locode, filters.size, filters.status, filters.grade, filters.tech].filter(Boolean).length + (filters.attention ? 1 : 0);
  const usedLocodes = LOCATIONS.filter((l) => rows.some((r) => r.currentLocode === l.code));

  function update<K extends keyof RegistryFilters>(key: K, value: RegistryFilters[K]) {
    setFilters((prev) => ({ ...prev, [key]: value }));
  }

  function toggleSort(key: SortKey) {
    setSort((prev) => (prev.key === key ? { key, dir: prev.dir === "asc" ? "desc" : "asc" } : { key, dir: "asc" }));
  }

  const filterControls = (
    <>
      <Select aria-label="Локация" value={filters.locode} onChange={(e) => update("locode", e.target.value)}>
        <option value="">Все локации</option>
        {usedLocodes.map((l) => (
          <option key={l.code} value={l.code}>{l.code} · {l.city}</option>
        ))}
      </Select>
      <Select aria-label="Типоразмер" value={filters.size} onChange={(e) => update("size", e.target.value)}>
        <option value="">Все типоразмеры</option>
        {SIZE_TYPES.map((s) => (
          <option key={s} value={s}>{s}</option>
        ))}
      </Select>
      <Select aria-label="Статус" value={filters.status} onChange={(e) => update("status", e.target.value)}>
        <option value="">Все статусы</option>
        {OPERATIONAL_STATUSES.map((s) => (
          <option key={s} value={s}>{OPERATIONAL_STATUS_LABELS[s]}</option>
        ))}
      </Select>
      <Select aria-label="Грейд" value={filters.grade} onChange={(e) => update("grade", e.target.value)}>
        <option value="">Все грейды</option>
        {CONDITION_GRADES.map((g) => (
          <option key={g} value={g}>{CONDITION_GRADE_LABELS[g]}</option>
        ))}
      </Select>
      <Select aria-label="Тех. статус" value={filters.tech} onChange={(e) => update("tech", e.target.value)}>
        <option value="">Любое тех. состояние</option>
        {TECH_STATUSES.map((t) => (
          <option key={t} value={t}>{TECH_STATUS_LABELS[t]}</option>
        ))}
      </Select>
    </>
  );

  return (
    <>
      {/* Панель поиска и фильтров */}
      <div className="sticky top-14 z-20 -mx-4 mb-4 space-y-3 bg-slate-50/95 px-4 py-2 backdrop-blur sm:-mx-6 sm:px-6 lg:static lg:mx-0 lg:bg-transparent lg:p-0 lg:backdrop-blur-none">
        <div className="flex gap-2">
          <div className="relative flex-1">
            <Search className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-slate-400" aria-hidden />
            <Input
              value={filters.q}
              onChange={(e) => update("q", e.target.value)}
              placeholder="Поиск по номеру: EXEX, 2918, 402918-4…"
              className="pl-9 font-mono"
              aria-label="Поиск по номеру контейнера"
              inputMode="search"
            />
            {filters.q && (
              <button type="button" onClick={() => update("q", "")} className="absolute top-1/2 right-2 -translate-y-1/2 rounded p-1 text-slate-400 hover:text-slate-700" aria-label="Очистить поиск">
                <X className="size-4" />
              </button>
            )}
          </div>
          <Button variant="outline" size="icon" className="relative h-11 w-11 lg:hidden" onClick={() => setFiltersOpen(true)} aria-label="Фильтры">
            <SlidersHorizontal />
            {activeFilterCount > 0 && <span className="absolute -top-1 -right-1 rounded-full bg-indigo-600 px-1.5 text-[10px] leading-4 font-semibold text-white">{activeFilterCount}</span>}
          </Button>
          <Button className="h-11 lg:h-10" onClick={() => setCreateOpen(true)}>
            <Plus />
            <span className="hidden sm:inline">Добавить</span>
          </Button>
        </div>
        <div className="hidden gap-2 lg:grid lg:grid-cols-5">{filterControls}</div>
        <div className="flex flex-wrap items-center gap-2 text-sm">
          <button
            type="button"
            onClick={() => update("attention", !filters.attention)}
            aria-pressed={filters.attention}
            className={cn(
              "inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-medium ring-1 transition-colors",
              filters.attention ? "bg-amber-500 text-white ring-amber-500" : "bg-white text-slate-600 ring-slate-200 hover:ring-slate-300",
            )}
          >
            <TriangleAlert className="size-3.5" /> Требуют внимания
          </button>
          <span className="text-xs text-slate-500">
            Найдено: <span className="font-mono font-semibold text-slate-900">{visible.length}</span> из {rows.length}
          </span>
          {(activeFilterCount > 0 || filters.q) && (
            <button type="button" onClick={() => setFilters(EMPTY_FILTERS)} className="text-xs font-medium text-indigo-600 hover:underline">
              Сбросить фильтры
            </button>
          )}
        </div>
      </div>

      {visible.length === 0 ? (
        <Card>
          <EmptyState icon={<PackageOpen />} title="Ничего не найдено" description="Измените условия поиска или сбросьте фильтры." action={<Button variant="outline" onClick={() => setFilters(EMPTY_FILTERS)}>Сбросить фильтры</Button>} />
        </Card>
      ) : (
        <>
          {/* ПК: таблица */}
          <Card className="hidden overflow-hidden lg:block">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-slate-50 text-left text-xs text-slate-500">
                  <tr>
                    <SortHeader label="Номер" sortKey="bicCode" sort={sort} onSort={toggleSort} />
                    <SortHeader label="Тип" sortKey="sizeType" sort={sort} onSort={toggleSort} />
                    <SortHeader label="Статус / операция" sortKey="operationalStatus" sort={sort} onSort={toggleSort} />
                    <SortHeader label="Локация" sortKey="currentLocode" sort={sort} onSort={toggleSort} />
                    <th className="px-3 py-2.5 font-medium">Состояние</th>
                    <SortHeader label="КБК" sortKey="csc" sort={sort} onSort={toggleSort} />
                    <SortHeader label="На стоке" sortKey="idle" sort={sort} onSort={toggleSort} align="right" />
                    <SortHeader label="ROI" sortKey="roi" sort={sort} onSort={toggleSort} align="right" />
                    <th className="w-8" />
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {visible.map((row) => (
                    <tr
                      key={row.id}
                      onClick={() => setSelectedId(row.id)}
                      className={cn("cursor-pointer transition-colors hover:bg-indigo-50/40", selectedId === row.id && "bg-indigo-50/60", row.needsAttention && "border-l-2 border-l-amber-400")}
                    >
                      <td className="px-3 py-3">
                        <BicCode code={row.bicCode} />
                        <p className="text-xs text-slate-400">{row.manufactureYear} · {row.manufacturer.split(" ")[0]}</p>
                      </td>
                      <td className="px-3 py-3">
                        <span className="font-mono font-medium">{row.sizeType}</span>
                        <p className="font-mono text-xs text-slate-400">{row.isoCode}</p>
                      </td>
                      <td className="px-3 py-3">
                        <OperationalStatusBadge status={row.operationalStatus} />
                        {row.activity && <p className="mt-1 max-w-56 truncate text-xs text-slate-500">{row.activity}</p>}
                      </td>
                      <td className="px-3 py-3">
                        <span className="font-mono text-xs font-semibold text-slate-700">{row.currentLocode}</span>
                        <p className="max-w-44 truncate text-xs text-slate-500">{row.currentTerminal}</p>
                      </td>
                      <td className="px-3 py-3">
                        <div className="flex flex-wrap gap-1">
                          <GradeBadge grade={row.conditionGrade} />
                          {row.techStatus !== "SOUND" && <TechStatusBadge status={row.techStatus} />}
                        </div>
                        {row.eorAmountUsd ? <p className="mt-1 font-mono text-xs text-orange-600">EOR {formatUsd(row.eorAmountUsd)}</p> : null}
                      </td>
                      <td className="px-3 py-3">
                        {row.csc.level === "OK" ? <span className="font-mono text-xs text-slate-500">{formatDate(row.cscPlateExpiry)}</span> : <CscBadge csc={row.csc} />}
                      </td>
                      <td className="px-3 py-3 text-right">
                        {row.idleDays !== null ? (
                          <span className={cn("font-mono text-xs", row.isIdleTooLong ? "font-semibold text-violet-700" : "text-slate-600")}>{formatDays(row.idleDays)}</span>
                        ) : (
                          <span className="text-slate-300">—</span>
                        )}
                      </td>
                      <td className={cn("px-3 py-3 text-right font-mono text-xs font-medium", row.roi >= 0 ? "text-emerald-600" : "text-rose-600")}>{formatPercent(row.roi)}</td>
                      <td className="pr-3 text-slate-300"><ChevronRight className="size-4" /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Card>

          {/* Телефон / планшет: карточки */}
          <ul className="grid gap-3 sm:grid-cols-2 lg:hidden">
            {visible.map((row) => (
              <li key={row.id}>
                <button
                  type="button"
                  onClick={() => setSelectedId(row.id)}
                  className={cn("w-full rounded-xl border bg-white p-4 text-left shadow-sm transition active:scale-[0.99]", row.needsAttention ? "border-amber-300" : "border-slate-200")}
                >
                  <div className="flex items-start justify-between gap-2">
                    <BicCode code={row.bicCode} size="lg" />
                    <span className="rounded-md bg-slate-100 px-2 py-0.5 font-mono text-xs font-semibold text-slate-700">{row.sizeType}</span>
                  </div>
                  <div className="mt-2 flex flex-wrap gap-1.5">
                    <OperationalStatusBadge status={row.operationalStatus} />
                    <GradeBadge grade={row.conditionGrade} />
                    {row.techStatus !== "SOUND" && <TechStatusBadge status={row.techStatus} />}
                  </div>
                  <p className="mt-2.5 flex items-center gap-1.5 text-sm text-slate-600">
                    <MapPin className="size-3.5 shrink-0 text-slate-400" />
                    <span className="truncate">{locodeCity(row.currentLocode)} · {row.currentTerminal}</span>
                  </p>
                  {row.activity && <p className="mt-1 truncate text-xs text-slate-500">{row.activity}</p>}
                  {(row.csc.level !== "OK" || row.isIdleTooLong || row.eorAmountUsd) && (
                    <div className="mt-2.5 flex flex-wrap gap-1.5 border-t border-dashed border-slate-200 pt-2.5">
                      <CscBadge csc={row.csc} />
                      {row.isIdleTooLong && <Badge tone="violet">Простой {formatDays(row.idleDays ?? 0)}</Badge>}
                      {row.eorAmountUsd ? <Badge tone="orange">EOR {formatUsd(row.eorAmountUsd)}</Badge> : null}
                    </div>
                  )}
                </button>
              </li>
            ))}
          </ul>
        </>
      )}

      {/* Быстрый просмотр */}
      <Sheet
        open={selected !== null}
        onClose={() => setSelectedId(null)}
        title={selected ? <BicCode code={selected.bicCode} size="lg" /> : ""}
        description={selected ? `${selected.sizeType} · ISO ${selected.isoCode} · ${selected.manufactureYear} г.` : undefined}
        footer={
          selected && (
            <Link href={`/containers/${selected.id}`} className={buttonClasses("default", "lg", "w-full")}>
              Открыть полный профиль <ChevronRight />
            </Link>
          )
        }
      >
        {selected && <QuickView row={selected} />}
      </Sheet>

      {/* Фильтры (моб.) */}
      <Sheet open={filtersOpen} onClose={() => setFiltersOpen(false)} title="Фильтры" footer={<Button size="lg" className="w-full" onClick={() => setFiltersOpen(false)}>Показать {visible.length}</Button>}>
        <div className="space-y-3">{filterControls}</div>
      </Sheet>

      {/* Создание */}
      <Sheet open={createOpen} onClose={() => setCreateOpen(false)} title="Новый контейнер" description="Номер проверяется по ISO 6346 с расчётом контрольной цифры" size="lg">
        <ContainerForm initial={emptyContainerForm()} onDone={() => setCreateOpen(false)} />
      </Sheet>
    </>
  );
}

function SortHeader({ label, sortKey, sort, onSort, align = "left" }: { label: string; sortKey: SortKey; sort: SortState; onSort: (k: SortKey) => void; align?: "left" | "right" }) {
  const active = sort.key === sortKey;
  const Icon = !active ? ArrowUpDown : sort.dir === "asc" ? ArrowUp : ArrowDown;
  return (
    <th className={cn("px-3 py-2.5 font-medium", align === "right" && "text-right")} aria-sort={active ? (sort.dir === "asc" ? "ascending" : "descending") : "none"}>
      <button type="button" onClick={() => onSort(sortKey)} className={cn("inline-flex items-center gap-1 hover:text-slate-900", active && "text-slate-900")}>
        {label}
        <Icon className={cn("size-3", !active && "opacity-40")} />
      </button>
    </th>
  );
}

function QuickView({ row }: { row: ContainerRow }) {
  return (
    <div className="space-y-5">
      <div className="flex flex-wrap gap-1.5">
        <OperationalStatusBadge status={row.operationalStatus} />
        <TechStatusBadge status={row.techStatus} />
        <GradeBadge grade={row.conditionGrade} full />
        <CscBadge csc={row.csc} />
      </div>
      {row.activity && (
        <Link href={row.activityHref ?? "#"} className="flex items-center justify-between rounded-lg bg-indigo-50 px-3 py-2.5 text-sm text-indigo-800 ring-1 ring-indigo-100 hover:bg-indigo-100">
          <span className="truncate">{row.activity}</span>
          {row.tripTiming && (
            <span className={cn("ml-2 shrink-0 font-mono text-xs font-semibold", row.tripTiming.status === "OVERDUE" ? "text-rose-600" : "text-indigo-700")}>
              {row.tripTiming.status === "OVERDUE" ? `+${row.tripTiming.overdueDays} дн.` : `${row.tripTiming.daysLeft} дн.`}
            </span>
          )}
        </Link>
      )}
      <DataList
        items={[
          { label: "Локация", value: `${row.currentLocode} · ${locodeCity(row.currentLocode)}` },
          { label: "Терминал / депо", value: row.currentTerminal },
          { label: "КБК (CSC) до", value: formatDate(row.cscPlateExpiry), mono: true },
          { label: "EOR", value: row.eorAmountUsd ? formatUsd(row.eorAmountUsd) : "—", mono: true },
          { label: "На стоке", value: row.idleDays !== null ? `${formatDays(row.idleDays)} · ${formatUsd(row.storageCostUsd)}` : "—" },
          { label: "Выручка / ROI", value: `${formatUsd(Math.round(row.totalRevenueUsd))} · ${formatPercent(row.roi)}`, mono: true },
        ]}
      />
      <div>
        <h3 className="mb-3 text-xs font-semibold tracking-wide text-slate-400 uppercase">Последние события</h3>
        <EventTimeline events={row.recentEvents} compact />
      </div>
    </div>
  );
}

import type { Metadata } from "next";
import { PageHeader } from "@/components/ui/primitives";
import { ContainerRegistry, type RegistryFilters } from "@/components/containers/container-registry";
import { getContainerRows } from "@/lib/queries/containers";
import { teuOf } from "@/lib/domain/constants";

export const metadata: Metadata = { title: "Реестр контейнеров" };

type SearchParams = Promise<Record<string, string | string[] | undefined>>;

function first(value: string | string[] | undefined): string {
  return (Array.isArray(value) ? value[0] : value) ?? "";
}

export default async function ContainersPage({ searchParams }: { searchParams: SearchParams }) {
  const params = await searchParams;
  const rows = await getContainerRows(new Date());
  const initialFilters: Partial<RegistryFilters> = {
    q: first(params.q),
    status: first(params.status),
    locode: first(params.locode),
    size: first(params.size),
    tech: first(params.tech),
    attention: first(params.attention) === "1",
  };
  const teu = rows.reduce((s, r) => s + teuOf(r.sizeType), 0);

  return (
    <>
      <PageHeader title="Реестр контейнеров" description={`База парка SOC: ${rows.length} ед. · ${teu} TEU. Нажмите на строку для быстрого просмотра.`} />
      <ContainerRegistry rows={rows} initialFilters={initialFilters} />
    </>
  );
}

input.content:
"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import { ClipboardCheck, Pencil, Plus, Trash2 } from "lucide-react";
import { addContainerEventAction, deleteContainerAction } from "@/actions/containers";
import { Button } from "@/components/ui/button";
import { Field, Input, Select, Textarea } from "@/components/ui/primitives";
import { Sheet } from "@/components/ui/sheet";
import { useServerAction } from "@/components/use-server-action";
import { EVENT_TYPES, EVENT_TYPE_LABELS } from "@/lib/domain/constants";
import { toDateInput } from "@/lib/dates";
import { ContainerForm, type ContainerFormValues } from "./container-form";

interface ContainerProfileActionsProps {
  containerId: string;
  bicLabel: string;
  formValues: ContainerFormValues;
  canDelete: boolean;
}

export function ContainerProfileActions({ containerId, bicLabel, formValues, canDelete }: ContainerProfileActionsProps) {
  const router = useRouter();
  const [editOpen, setEditOpen] = useState(false);
  const [eventOpen, setEventOpen] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const deletion = useServerAction();

  return (
    <>
      <div className="grid grid-cols-3 gap-2 sm:flex">
        <Button variant="outline" onClick={() => setEventOpen(true)}>
          <Plus /> <span className="truncate">Событие</span>
        </Button>
        <Button variant="outline" onClick={() => setEditOpen(true)}>
          <Pencil /> <span className="truncate">Изменить</span>
        </Button>
        <Button variant="ghost" className="text-rose-600 hover:bg-rose-50 hover:text-rose-700" onClick={() => setDeleteOpen(true)}>
          <Trash2 /> <span className="truncate">Списать</span>
        </Button>
      </div>

      <Sheet open={editOpen} onClose={() => setEditOpen(false)} title={`Редактирование ${bicLabel}`} size="lg">
        <ContainerForm containerId={containerId} initial={formValues} onDone={() => setEditOpen(false)} />
      </Sheet>

      <Sheet open={eventOpen} onClose={() => setEventOpen(false)} title="Запись в журнал" description="Акт осмотра, ремонт, перемещение или иное событие">
        <EventForm containerId={containerId} onDone={() => setEventOpen(false)} />
      </Sheet>

      <Sheet
        open={deleteOpen}
        onClose={() => setDeleteOpen(false)}
        title={`Списать ${bicLabel}?`}
        footer={
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => setDeleteOpen(false)}>Отмена</Button>
            <Button
              variant="destructive"
              className="flex-1"
              disabled={!canDelete}
              loading={deletion.isPending}
              onClick={() => deletion.run(() => deleteContainerAction(containerId), () => router.push("/containers"))}
            >
              Списать из парка
            </Button>
          </div>
        }
      >
        <p className="text-sm text-slate-600">
          {canDelete
            ? "Контейнер и вся его история (события, рейсы One-Way, строки договоров аренды) будут удалены из базы. Действие необратимо."
            : "Контейнер находится в активном One-Way или аренде. Сначала оформите возврат (Gate-In / Off-Hire)."}
        </p>
      </Sheet>
    </>
  );
}

function EventForm({ containerId, onDone }: { containerId: string; onDone: () => void }) {
  const [type, setType] = useState<string>("INSPECTION");
  const [occurredAt, setOccurredAt] = useState(toDateInput(new Date()));
  const [description, setDescription] = useState("");
  const [amountUsd, setAmountUsd] = useState("");
  const { run, isPending, fieldErrors } = useServerAction();

  return (
    <form
      className="space-y-4"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => addContainerEventAction(containerId, { type: type as (typeof EVENT_TYPES)[number], occurredAt, description, amountUsd }), onDone);
      }}
    >
      <Field label="Тип события" htmlFor="ev-type" error={fieldErrors.type}>
        <Select id="ev-type" value={type} onChange={(e) => setType(e.target.value)}>
          {EVENT_TYPES.filter((t) => t !== "PURCHASE").map((t) => (
            <option key={t} value={t}>{EVENT_TYPE_LABELS[t]}</option>
          ))}
        </Select>
      </Field>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Дата" htmlFor="ev-date" error={fieldErrors.occurredAt}>
          <Input id="ev-date" type="date" value={occurredAt} onChange={(e) => setOccurredAt(e.target.value)} />
        </Field>
        <Field label="Сумма, $" htmlFor="ev-amount" hint="Необязательно" error={fieldErrors.amountUsd}>
          <Input id="ev-amount" type="number" inputMode="decimal" min={0} value={amountUsd} onChange={(e) => setAmountUsd(e.target.value)} />
        </Field>
      </div>
      <Field label="Описание" htmlFor="ev-desc" error={fieldErrors.description}>
        <Textarea id="ev-desc" rows={4} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Например: осмотр на ВМТП, повреждений не выявлено" required />
      </Field>
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <ClipboardCheck /> Сохранить в журнал
      </Button>
    </form>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { ArrowLeft, Banknote, ClipboardList, History, MapPin, Route, ShieldCheck, Wrench, FileText } from "lucide-react";
import { Badge, Card, CardContent, CardHeader, DataList, Progress } from "@/components/ui/primitives";
import { BicCode, CscBadge, GradeBadge, OperationalStatusBadge, TechStatusBadge, TripStatusBadge } from "@/components/status-badges";
import { EventTimeline } from "@/components/containers/event-timeline";
import { ContainerProfileActions } from "@/components/containers/container-profile-actions";
import type { ContainerFormValues } from "@/components/containers/container-form";
import { getContainerProfile } from "@/lib/queries/containers";
import { attentionFlagsOf, unitEconomicsOf } from "@/lib/domain/container";
import { computeTripTiming } from "@/lib/domain/one-way";
import { rentalDaysInRange } from "@/lib/domain/lease";
import { CONDITION_GRADE_LABELS, SIZE_TYPE_LABELS, isOneOf, CONDITION_GRADES, SIZE_TYPES, locodeCity, teuOf } from "@/lib/domain/constants";
import { formatBic } from "@/lib/iso6346";
import { toDateInput } from "@/lib/dates";
import { formatDate, formatDays, formatNumber, formatPercent, formatUsd } from "@/lib/format";
import { cn } from "@/lib/utils";

type Params = Promise<{ id: string }>;

export async function generateMetadata({ params }: { params: Params }): Promise<Metadata> {
  const { id } = await params;
  const c = await getContainerProfile(id);
  return { title: c ? formatBic(c.bicCode) : "Контейнер не найден" };
}

export default async function ContainerProfilePage({ params }: { params: Params }) {
  const { id } = await params;
  const c = await getContainerProfile(id);
  if (!c) notFound();

  const now = new Date();
  const flags = attentionFlagsOf(c, now);
  const economics = unitEconomicsOf(c);
  const activeTrip = c.oneWayTrips.find((t) => t.status === "ACTIVE");
  const activeLease = c.leaseItems.find((i) => !i.offHireDate && i.lease.status === "ACTIVE");
  const tripTiming = activeTrip ? computeTripTiming(activeTrip, now) : null;
  const ageYears = now.getUTCFullYear() - c.manufactureYear;

  const formValues: ContainerFormValues = {
    bicCode: formatBic(c.bicCode),
    sizeType: c.sizeType,
    isoCode: c.isoCode,
    manufactureYear: String(c.manufactureYear),
    colorRal: c.colorRal,
    manufacturer: c.manufacturer,
    tareWeightKg: String(c.tareWeightKg),
    maxGrossWeightKg: String(c.maxGrossWeightKg),
    conditionGrade: c.conditionGrade,
    techStatus: c.techStatus,
    cscPlateExpiry: toDateInput(c.cscPlateExpiry),
    eorAmountUsd: c.eorAmountUsd != null ? String(c.eorAmountUsd) : "",
    operationalStatus: c.operationalStatus,
    currentLocode: c.currentLocode,
    currentTerminal: c.currentTerminal,
    storageRatePerDayUsd: c.storageRatePerDayUsd != null ? String(c.storageRatePerDayUsd) : "",
    purchaseDate: toDateInput(c.purchaseDate),
    purchasePriceUsd: String(c.purchasePriceUsd),
    currentBookValueUsd: String(c.currentBookValueUsd),
    notes: c.notes ?? "",
  };

  return (
    <>
      <Link href="/containers" className="mb-4 inline-flex items-center gap-1.5 text-sm text-slate-500 hover:text-slate-900">
        <ArrowLeft className="size-4" /> Реестр контейнеров
      </Link>

      {/* Шапка профиля */}
      <Card className="relative mb-4 overflow-hidden lg:mb-6">
        <div className="absolute inset-y-0 left-0 w-1.5 bg-indigo-600" aria-hidden />
        <div className="flex flex-col gap-4 p-5 pl-6 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <p className="font-mono text-xs tracking-widest text-slate-400 uppercase">
              {isOneOf(SIZE_TYPES, c.sizeType) ? SIZE_TYPE_LABELS[c.sizeType] : c.sizeType} · ISO {c.isoCode} · {teuOf(c.sizeType)} TEU
            </p>
            <h1 className="mt-1">
              <BicCode code={c.bicCode} size="xl" />
            </h1>
            <div className="mt-3 flex flex-wrap gap-1.5">
              <OperationalStatusBadge status={c.operationalStatus} />
              <TechStatusBadge status={c.techStatus} />
              <GradeBadge grade={c.conditionGrade} full />
              <CscBadge csc={flags.csc} />
              {flags.storage.isIdleTooLong && <Badge tone="violet">Простой {formatDays(flags.storage.idleDays ?? 0)}</Badge>}
            </div>
          </div>
          <ContainerProfileActions containerId={c.id} bicLabel={formatBic(c.bicCode)} formValues={formValues} canDelete={!activeTrip && !activeLease} />
        </div>
        {(activeTrip || activeLease) && (
          <div className="border-t border-slate-100 bg-indigo-50/50 px-5 py-3 pl-6 text-sm">
            {activeTrip && tripTiming && (
              <Link href={`/one-way?focus=${activeTrip.id}`} className="flex flex-wrap items-center gap-x-4 gap-y-1 hover:underline">
                <span className="flex items-center gap-1.5 font-medium text-indigo-800"><Route className="size-4" /> One-Way {activeTrip.bookingRef}</span>
                <span className="text-slate-600">{activeTrip.counterpartyName}</span>
                <span className="font-mono text-xs text-slate-500">{activeTrip.pickupLocode} → {activeTrip.dropoffLocode}</span>
                <span className={cn("font-mono text-xs font-semibold", tripTiming.status === "OVERDUE" ? "text-rose-600" : "text-indigo-700")}>
                  {tripTiming.status === "OVERDUE" ? `Просрочка ${formatDays(tripTiming.overdueDays)} → детеншн ${formatUsd(tripTiming.detentionUsd)}` : `Осталось ${formatDays(tripTiming.daysLeft ?? 0)}`}
                </span>
              </Link>
            )}
            {activeLease && (
              <Link href={`/leases/${activeLease.lease.id}`} className="flex flex-wrap items-center gap-x-4 gap-y-1 hover:underline">
                <span className="flex items-center gap-1.5 font-medium text-violet-800"><FileText className="size-4" /> Аренда {activeLease.lease.contractNumber}</span>
                <span className="text-slate-600">{activeLease.lease.lesseeName}</span>
                <span className="font-mono text-xs text-slate-500">{formatUsd(activeLease.lease.dailyRateUsd, 2)}/сут. · до {formatDate(activeLease.lease.endDate)}</span>
              </Link>
            )}
          </div>
        )}
      </Card>

      <div className="grid gap-4 lg:gap-6 xl:grid-cols-[1fr_1fr_1.15fr]">
        <div className="space-y-4 lg:space-y-6">
          <Card>
            <CardHeader icon={<ClipboardList />} title="Паспорт и идентификация" />
            <CardContent>
              <DataList
                items={[
                  { label: "Номер (ISO 6346)", value: formatBic(c.bicCode), mono: true },
                  { label: "Префикс владельца", value: c.bicCode.slice(0, 4), mono: true },
                  { label: "Типоразмер", value: c.sizeType, mono: true },
                  { label: "ISO-код типа", value: c.isoCode, mono: true },
                  { label: "Год выпуска", value: `${c.manufactureYear} (${formatDays(ageYears * 365).replace(/\d+ \S+/, `${ageYears} г.`)})` },
                  { label: "Цвет", value: c.colorRal },
                  { label: "Завод-изготовитель", value: c.manufacturer, full: true },
                  { label: "Тара", value: `${formatNumber(c.tareWeightKg)} кг`, mono: true },
                  { label: "Макс. загрузка", value: `${formatNumber(c.maxPayloadKg)} кг`, mono: true },
                  { label: "Брутто (MGW)", value: `${formatNumber(c.maxGrossWeightKg)} кг`, mono: true },
                ]}
              />
            </CardContent>
          </Card>

          <Card>
            <CardHeader icon={<ShieldCheck />} title="Техсостояние и комплаенс" />
            <CardContent className="space-y-4">
              {flags.csc.level !== "OK" && (
                <div className={cn("rounded-lg px-3 py-2.5 text-sm ring-1", flags.csc.level === "EXPIRED" ? "bg-rose-50 text-rose-800 ring-rose-200" : "bg-amber-50 text-amber-900 ring-amber-200")}>
                  {flags.csc.level === "EXPIRED"
                    ? `Табличка КБК (CSC) просрочена на ${formatDays(-flags.csc.daysLeft)}. Эксплуатация запрещена до освидетельствования ACEP.`
                    : `До истечения КБК (CSC) осталось ${formatDays(flags.csc.daysLeft)}. Запланируйте освидетельствование.`}
                </div>
              )}
              <DataList
                items={[
                  { label: "Грейд", value: isOneOf(CONDITION_GRADES, c.conditionGrade) ? CONDITION_GRADE_LABELS[c.conditionGrade] : c.conditionGrade },
                  { label: "Тех. статус", value: <TechStatusBadge status={c.techStatus} /> },
                  { label: "КБК (CSC) / ACEP до", value: formatDate(c.cscPlateExpiry), mono: true },
                  { label: "EOR (оценка ремонта)", value: c.eorAmountUsd ? formatUsd(c.eorAmountUsd) : "—", mono: true },
                ]}
              />
            </CardContent>
          </Card>
        </div>

        <div className="space-y-4 lg:space-y-6">
          <Card>
            <CardHeader icon={<MapPin />} title="Дислокация" />
            <CardContent>
              <DataList
                items={[
                  { label: "UN/LOCODE", value: c.currentLocode, mono: true },
                  { label: "Город / порт", value: locodeCity(c.currentLocode) },
                  { label: "Терминал / депо", value: c.currentTerminal, full: true },
                  { label: "На стоке с", value: formatDate(c.storageStartDate), mono: true },
                  { label: "Ставка хранения", value: c.storageRatePerDayUsd ? `${formatUsd(c.storageRatePerDayUsd, 2)}/сут.` : "—", mono: true },
                  { label: "Дней на стоке", value: flags.storage.idleDays !== null ? formatDays(flags.storage.idleDays) : "—" },
                  { label: "Накоплено за хранение", value: flags.storage.idleDays !== null ? formatUsd(flags.storage.storageCostUsd) : "—", mono: true },
                ]}
              />
            </CardContent>
          </Card>

          <Card>
            <CardHeader icon={<Banknote />} title="Экономика единицы" description="ROI = (выручка − ремонты − амортизация) / цена покупки" />
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div className="rounded-lg bg-slate-900 p-3 text-white">
                  <p className="text-xs text-slate-400">ROI</p>
                  <p className={cn("font-mono text-2xl font-semibold tabular", economics.roi >= 0 ? "text-emerald-400" : "text-rose-400")}>{formatPercent(economics.roi, 1)}</p>
                </div>
                <div className="rounded-lg bg-slate-50 p-3 ring-1 ring-slate-200">
                  <p className="text-xs text-slate-500">Чистый результат</p>
                  <p className={cn("font-mono text-2xl font-semibold tabular", economics.netResultUsd >= 0 ? "text-slate-900" : "text-rose-600")}>{formatUsd(Math.round(economics.netResultUsd))}</p>
                </div>
              </div>
              <div>
                <div className="mb-1 flex justify-between text-xs text-slate-500">
                  <span>Окупаемость (выручка − ремонты)</span>
                  <span className="font-mono">{formatPercent(economics.paybackRatio)}</span>
                </div>
                <Progress value={economics.paybackRatio} tone={economics.paybackRatio >= 1 ? "emerald" : "indigo"} />
              </div>
              <DataList
                items={[
                  { label: "Дата покупки", value: formatDate(c.purchaseDate), mono: true },
                  { label: "Цена покупки", value: formatUsd(c.purchasePriceUsd), mono: true },
                  { label: "Остаточная стоимость", value: formatUsd(c.currentBookValueUsd), mono: true },
                  { label: "Амортизация", value: formatUsd(economics.depreciationUsd), mono: true },
                  { label: "Накопленная выручка", value: formatUsd(Math.round(c.totalRevenueUsd)), mono: true },
                  { label: "Затраты на ремонты", value: formatUsd(c.totalRepairCostUsd), mono: true },
                ]}
              />
            </CardContent>
          </Card>

          {(c.oneWayTrips.length > 0 || c.leaseItems.length > 0) && (
            <Card>
              <CardHeader icon={<Route />} title="Коммерческая история" description={`${c.oneWayTrips.length} One-Way · ${c.leaseItems.length} аренд`} />
              <ul className="divide-y divide-slate-100 text-sm">
                {c.oneWayTrips.map((t) => {
                  const timing = computeTripTiming(t, now);
                  return (
                    <li key={t.id} className="flex items-center justify-between gap-3 px-4 py-2.5 sm:px-5">
                      <div className="min-w-0">
                        <p className="font-mono text-xs font-semibold">{t.bookingRef}</p>
                        <p className="truncate text-xs text-slate-500">{locodeCity(t.pickupLocode)} → {locodeCity(t.dropoffLocode)} · {formatDate(t.handoverDate)}</p>
                      </div>
                      <div className="flex flex-col items-end gap-0.5">
                        <TripStatusBadge status={timing.status} />
                        {timing.detentionUsd > 0 && <span className="font-mono text-xs text-rose-600">{formatUsd(timing.detentionUsd)}</span>}
                      </div>
                    </li>
                  );
                })}
                {c.leaseItems.map((item) => (
                  <li key={item.id}>
                    <Link href={`/leases/${item.lease.id}`} className="flex items-center justify-between gap-3 px-4 py-2.5 hover:bg-slate-50 sm:px-5">
                      <div className="min-w-0">
                        <p className="font-mono text-xs font-semibold">{item.lease.contractNumber}</p>
                        <p className="truncate text-xs text-slate-500">{item.lease.lesseeName} · {formatDate(item.onHireDate)} — {item.offHireDate ? formatDate(item.offHireDate) : "н.в."}</p>
                      </div>
                      <span className="font-mono text-xs text-slate-600">
                        {formatUsd(rentalDaysInRange(item, item.onHireDate, now) * item.lease.dailyRateUsd)}
                      </span>
                    </Link>
                  </li>
                ))}
              </ul>
            </Card>
          )}
        </div>

        <Card className="xl:row-span-2 xl:self-start">
          <CardHeader icon={<History />} title="История операций" description={`${c.events.length} событий · Audit & Movement Log`} />
          <CardContent>
            <EventTimeline events={c.events} />
          </CardContent>
        </Card>
      </div>

      {c.notes && (
        <Card className="mt-4 border-amber-200 bg-amber-50/50 lg:mt-6">
          <CardHeader icon={<Wrench />} title="Примечания" />
          <CardContent className="text-sm whitespace-pre-line text-slate-700">{c.notes}</CardContent>
        </Card>
      )}
    </>
  );
}

toolUseResult.content:
"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import { ClipboardCheck, Pencil, Plus, Trash2 } from "lucide-react";
import { addContainerEventAction, deleteContainerAction } from "@/actions/containers";
import { Button } from "@/components/ui/button";
import { Field, Input, Select, Textarea } from "@/components/ui/primitives";
import { Sheet } from "@/components/ui/sheet";
import { useServerAction } from "@/components/use-server-action";
import { EVENT_TYPES, EVENT_TYPE_LABELS } from "@/lib/domain/constants";
import { toDateInput } from "@/lib/dates";
import { ContainerForm, type ContainerFormValues } from "./container-form";

interface ContainerProfileActionsProps {
  containerId: string;
  bicLabel: string;
  formValues: ContainerFormValues;
  canDelete: boolean;
}

export function ContainerProfileActions({ containerId, bicLabel, formValues, canDelete }: ContainerProfileActionsProps) {
  const router = useRouter();
  const [editOpen, setEditOpen] = useState(false);
  const [eventOpen, setEventOpen] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const deletion = useServerAction();

  return (
    <>
      <div className="grid grid-cols-3 gap-2 sm:flex">
        <Button variant="outline" onClick={() => setEventOpen(true)}>
          <Plus /> <span className="truncate">Событие</span>
        </Button>
        <Button variant="outline" onClick={() => setEditOpen(true)}>
          <Pencil /> <span className="truncate">Изменить</span>
        </Button>
        <Button variant="ghost" className="text-rose-600 hover:bg-rose-50 hover:text-rose-700" onClick={() => setDeleteOpen(true)}>
          <Trash2 /> <span className="truncate">Списать</span>
        </Button>
      </div>

      <Sheet open={editOpen} onClose={() => setEditOpen(false)} title={`Редактирование ${bicLabel}`} size="lg">
        <ContainerForm containerId={containerId} initial={formValues} onDone={() => setEditOpen(false)} />
      </Sheet>

      <Sheet open={eventOpen} onClose={() => setEventOpen(false)} title="Запись в журнал" description="Акт осмотра, ремонт, перемещение или иное событие">
        <EventForm containerId={containerId} onDone={() => setEventOpen(false)} />
      </Sheet>

      <Sheet
        open={deleteOpen}
        onClose={() => setDeleteOpen(false)}
        title={`Списать ${bicLabel}?`}
        footer={
          <div className="flex gap-2">
            <Button variant="outline" onClick={() => setDeleteOpen(false)}>Отмена</Button>
            <Button
              variant="destructive"
              className="flex-1"
              disabled={!canDelete}
              loading={deletion.isPending}
              onClick={() => deletion.run(() => deleteContainerAction(containerId), () => router.push("/containers"))}
            >
              Списать из парка
            </Button>
          </div>
        }
      >
        <p className="text-sm text-slate-600">
          {canDelete
            ? "Контейнер и вся его история (события, рейсы One-Way, строки договоров аренды) будут удалены из базы. Действие необратимо."
            : "Контейнер находится в активном One-Way или аренде. Сначала оформите возврат (Gate-In / Off-Hire)."}
        </p>
      </Sheet>
    </>
  );
}

function EventForm({ containerId, onDone }: { containerId: string; onDone: () => void }) {
  const [type, setType] = useState<string>("INSPECTION");
  const [occurredAt, setOccurredAt] = useState(toDateInput(new Date()));
  const [description, setDescription] = useState("");
  const [amountUsd, setAmountUsd] = useState("");
  const { run, isPending, fieldErrors } = useServerAction();

  return (
    <form
      className="space-y-4"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => addContainerEventAction(containerId, { type: type as (typeof EVENT_TYPES)[number], occurredAt, description, amountUsd }), onDone);
      }}
    >
      <Field label="Тип события" htmlFor="ev-type" error={fieldErrors.type}>
        <Select id="ev-type" value={type} onChange={(e) => setType(e.target.value)}>
          {EVENT_TYPES.filter((t) => t !== "PURCHASE").map((t) => (
            <option key={t} value={t}>{EVENT_TYPE_LABELS[t]}</option>
          ))}
        </Select>
      </Field>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Дата" htmlFor="ev-date" error={fieldErrors.occurredAt}>
          <Input id="ev-date" type="date" value={occurredAt} onChange={(e) => setOccurredAt(e.target.value)} />
        </Field>
        <Field label="Сумма, $" htmlFor="ev-amount" hint="Необязательно" error={fieldErrors.amountUsd}>
          <Input id="ev-amount" type="number" inputMode="decimal" min={0} value={amountUsd} onChange={(e) => setAmountUsd(e.target.value)} />
        </Field>
      </div>
      <Field label="Описание" htmlFor="ev-desc" error={fieldErrors.description}>
        <Textarea id="ev-desc" rows={4} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Например: осмотр на ВМТП, повреждений не выявлено" required />
      </Field>
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <ClipboardCheck /> Сохранить в журнал
      </Button>
    </form>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { ArrowLeft, Banknote, ClipboardList, History, MapPin, Route, ShieldCheck, Wrench, FileText } from "lucide-react";
import { Badge, Card, CardContent, CardHeader, DataList, Progress } from "@/components/ui/primitives";
import { BicCode, CscBadge, GradeBadge, OperationalStatusBadge, TechStatusBadge, TripStatusBadge } from "@/components/status-badges";
import { EventTimeline } from "@/components/containers/event-timeline";
import { ContainerProfileActions } from "@/components/containers/container-profile-actions";
import type { ContainerFormValues } from "@/components/containers/container-form";
import { getContainerProfile } from "@/lib/queries/containers";
import { attentionFlagsOf, unitEconomicsOf } from "@/lib/domain/container";
import { computeTripTiming } from "@/lib/domain/one-way";
import { rentalDaysInRange } from "@/lib/domain/lease";
import { CONDITION_GRADE_LABELS, SIZE_TYPE_LABELS, isOneOf, CONDITION_GRADES, SIZE_TYPES, locodeCity, teuOf } from "@/lib/domain/constants";
import { formatBic } from "@/lib/iso6346";
import { toDateInput } from "@/lib/dates";
import { formatDate, formatDays, formatNumber, formatPercent, formatUsd } from "@/lib/format";
import { cn } from "@/lib/utils";

type Params = Promise<{ id: string }>;

export async function generateMetadata({ params }: { params: Params }): Promise<Metadata> {
  const { id } = await params;
  const c = await getContainerProfile(id);
  return { title: c ? formatBic(c.bicCode) : "Контейнер не найден" };
}

export default async function ContainerProfilePage({ params }: { params: Params }) {
  const { id } = await params;
  const c = await getContainerProfile(id);
  if (!c) notFound();

  const now = new Date();
  const flags = attentionFlagsOf(c, now);
  const economics = unitEconomicsOf(c);
  const activeTrip = c.oneWayTrips.find((t) => t.status === "ACTIVE");
  const activeLease = c.leaseItems.find((i) => !i.offHireDate && i.lease.status === "ACTIVE");
  const tripTiming = activeTrip ? computeTripTiming(activeTrip, now) : null;
  const ageYears = now.getUTCFullYear() - c.manufactureYear;

  const formValues: ContainerFormValues = {
    bicCode: formatBic(c.bicCode),
    sizeType: c.sizeType,
    isoCode: c.isoCode,
    manufactureYear: String(c.manufactureYear),
    colorRal: c.colorRal,
    manufacturer: c.manufacturer,
    tareWeightKg: String(c.tareWeightKg),
    maxGrossWeightKg: String(c.maxGrossWeightKg),
    conditionGrade: c.conditionGrade,
    techStatus: c.techStatus,
    cscPlateExpiry: toDateInput(c.cscPlateExpiry),
    eorAmountUsd: c.eorAmountUsd != null ? String(c.eorAmountUsd) : "",
    operationalStatus: c.operationalStatus,
    currentLocode: c.currentLocode,
    currentTerminal: c.currentTerminal,
    storageRatePerDayUsd: c.storageRatePerDayUsd != null ? String(c.storageRatePerDayUsd) : "",
    purchaseDate: toDateInput(c.purchaseDate),
    purchasePriceUsd: String(c.purchasePriceUsd),
    currentBookValueUsd: String(c.currentBookValueUsd),
    notes: c.notes ?? "",
  };

  return (
    <>
      <Link href="/containers" className="mb-4 inline-flex items-center gap-1.5 text-sm text-slate-500 hover:text-slate-900">
        <ArrowLeft className="size-4" /> Реестр контейнеров
      </Link>

      {/* Шапка профиля */}
      <Card className="relative mb-4 overflow-hidden lg:mb-6">
        <div className="absolute inset-y-0 left-0 w-1.5 bg-indigo-600" aria-hidden />
        <div className="flex flex-col gap-4 p-5 pl-6 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <p className="font-mono text-xs tracking-widest text-slate-400 uppercase">
              {isOneOf(SIZE_TYPES, c.sizeType) ? SIZE_TYPE_LABELS[c.sizeType] : c.sizeType} · ISO {c.isoCode} · {teuOf(c.sizeType)} TEU
            </p>
            <h1 className="mt-1">
              <BicCode code={c.bicCode} size="xl" />
            </h1>
            <div className="mt-3 flex flex-wrap gap-1.5">
              <OperationalStatusBadge status={c.operationalStatus} />
              <TechStatusBadge status={c.techStatus} />
              <GradeBadge grade={c.conditionGrade} full />
              <CscBadge csc={flags.csc} />
              {flags.storage.isIdleTooLong && <Badge tone="violet">Простой {formatDays(flags.storage.idleDays ?? 0)}</Badge>}
            </div>
          </div>
          <ContainerProfileActions containerId={c.id} bicLabel={formatBic(c.bicCode)} formValues={formValues} canDelete={!activeTrip && !activeLease} />
        </div>
        {(activeTrip || activeLease) && (
          <div className="border-t border-slate-100 bg-indigo-50/50 px-5 py-3 pl-6 text-sm">
            {activeTrip && tripTiming && (
              <Link href={`/one-way?focus=${activeTrip.id}`} className="flex flex-wrap items-center gap-x-4 gap-y-1 hover:underline">
                <span className="flex items-center gap-1.5 font-medium text-indigo-800"><Route className="size-4" /> One-Way {activeTrip.bookingRef}</span>
                <span className="text-slate-600">{activeTrip.counterpartyName}</span>
                <span className="font-mono text-xs text-slate-500">{activeTrip.pickupLocode} → {activeTrip.dropoffLocode}</span>
                <span className={cn("font-mono text-xs font-semibold", tripTiming.status === "OVERDUE" ? "text-rose-600" : "text-indigo-700")}>
                  {tripTiming.status === "OVERDUE" ? `Просрочка ${formatDays(tripTiming.overdueDays)} → детеншн ${formatUsd(tripTiming.detentionUsd)}` : `Осталось ${formatDays(tripTiming.daysLeft ?? 0)}`}
                </span>
              </Link>
            )}
            {activeLease && (
              <Link href={`/leases/${activeLease.lease.id}`} className="flex flex-wrap items-center gap-x-4 gap-y-1 hover:underline">
                <span className="flex items-center gap-1.5 font-medium text-violet-800"><FileText className="size-4" /> Аренда {activeLease.lease.contractNumber}</span>
                <span className="text-slate-600">{activeLease.lease.lesseeName}</span>
                <span className="font-mono text-xs text-slate-500">{formatUsd(activeLease.lease.dailyRateUsd, 2)}/сут. · до {formatDate(activeLease.lease.endDate)}</span>
              </Link>
            )}
          </div>
        )}
      </Card>

      <div className="grid gap-4 lg:gap-6 xl:grid-cols-[1fr_1fr_1.15fr]">
        <div className="space-y-4 lg:space-y-6">
          <Card>
            <CardHeader icon={<ClipboardList />} title="Паспорт и идентификация" />
            <CardContent>
              <DataList
                items={[
                  { label: "Номер (ISO 6346)", value: formatBic(c.bicCode), mono: true },
                  { label: "Префикс владельца", value: c.bicCode.slice(0, 4), mono: true },
                  { label: "Типоразмер", value: c.sizeType, mono: true },
                  { label: "ISO-код типа", value: c.isoCode, mono: true },
                  { label: "Год выпуска", value: `${c.manufactureYear} (${formatDays(ageYears * 365).replace(/\d+ \S+/, `${ageYears} г.`)})` },
                  { label: "Цвет", value: c.colorRal },
                  { label: "Завод-изготовитель", value: c.manufacturer, full: true },
                  { label: "Тара", value: `${formatNumber(c.tareWeightKg)} кг`, mono: true },
                  { label: "Макс. загрузка", value: `${formatNumber(c.maxPayloadKg)} кг`, mono: true },
                  { label: "Брутто (MGW)", value: `${formatNumber(c.maxGrossWeightKg)} кг`, mono: true },
                ]}
              />
            </CardContent>
          </Card>

          <Card>
            <CardHeader icon={<ShieldCheck />} title="Техсостояние и комплаенс" />
            <CardContent className="space-y-4">
              {flags.csc.level !== "OK" && (
                <div className={cn("rounded-lg px-3 py-2.5 text-sm ring-1", flags.csc.level === "EXPIRED" ? "bg-rose-50 text-rose-800 ring-rose-200" : "bg-amber-50 text-amber-900 ring-amber-200")}>
                  {flags.csc.level === "EXPIRED"
                    ? `Табличка КБК (CSC) просрочена на ${formatDays(-flags.csc.daysLeft)}. Эксплуатация запрещена до освидетельствования ACEP.`
                    : `До истечения КБК (CSC) осталось ${formatDays(flags.csc.daysLeft)}. Запланируйте освидетельствование.`}
                </div>
              )}
              <DataList
                items={[
                  { label: "Грейд", value: isOneOf(CONDITION_GRADES, c.conditionGrade) ? CONDITION_GRADE_LABELS[c.conditionGrade] : c.conditionGrade },
                  { label: "Тех. статус", value: <TechStatusBadge status={c.techStatus} /> },
                  { label: "КБК (CSC) / ACEP до", value: formatDate(c.cscPlateExpiry), mono: true },
                  { label: "EOR (оценка ремонта)", value: c.eorAmountUsd ? formatUsd(c.eorAmountUsd) : "—", mono: true },
                ]}
              />
            </CardContent>
          </Card>
        </div>

        <div className="space-y-4 lg:space-y-6">
          <Card>
            <CardHeader icon={<MapPin />} title="Дислокация" />
            <CardContent>
              <DataList
                items={[
                  { label: "UN/LOCODE", value: c.currentLocode, mono: true },
                  { label: "Город / порт", value: locodeCity(c.currentLocode) },
                  { label: "Терминал / депо", value: c.currentTerminal, full: true },
                  { label: "На стоке с", value: formatDate(c.storageStartDate), mono: true },
                  { label: "Ставка хранения", value: c.storageRatePerDayUsd ? `${formatUsd(c.storageRatePerDayUsd, 2)}/сут.` : "—", mono: true },
                  { label: "Дней на стоке", value: flags.storage.idleDays !== null ? formatDays(flags.storage.idleDays) : "—" },
                  { label: "Накоплено за хранение", value: flags.storage.idleDays !== null ? formatUsd(flags.storage.storageCostUsd) : "—", mono: true },
                ]}
              />
            </CardContent>
          </Card>

          <Card>
            <CardHeader icon={<Banknote />} title="Экономика единицы" description="ROI = (выручка − ремонты − амортизация) / цена покупки" />
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div className="rounded-lg bg-slate-900 p-3 text-white">
                  <p className="text-xs text-slate-400">ROI</p>
                  <p className={cn("font-mono text-2xl font-semibold tabular", economics.roi >= 0 ? "text-emerald-400" : "text-rose-400")}>{formatPercent(economics.roi, 1)}</p>
                </div>
                <div className="rounded-lg bg-slate-50 p-3 ring-1 ring-slate-200">
                  <p className="text-xs text-slate-500">Чистый результат</p>
                  <p className={cn("font-mono text-2xl font-semibold tabular", economics.netResultUsd >= 0 ? "text-slate-900" : "text-rose-600")}>{formatUsd(Math.round(economics.netResultUsd))}</p>
                </div>
              </div>
              <div>
                <div className="mb-1 flex justify-between text-xs text-slate-500">
                  <span>Окупаемость (выручка − ремонты)</span>
                  <span className="font-mono">{formatPercent(economics.paybackRatio)}</span>
                </div>
                <Progress value={economics.paybackRatio} tone={economics.paybackRatio >= 1 ? "emerald" : "indigo"} />
              </div>
              <DataList
                items={[
                  { label: "Дата покупки", value: formatDate(c.purchaseDate), mono: true },
                  { label: "Цена покупки", value: formatUsd(c.purchasePriceUsd), mono: true },
                  { label: "Остаточная стоимость", value: formatUsd(c.currentBookValueUsd), mono: true },
                  { label: "Амортизация", value: formatUsd(economics.depreciationUsd), mono: true },
                  { label: "Накопленная выручка", value: formatUsd(Math.round(c.totalRevenueUsd)), mono: true },
                  { label: "Затраты на ремонты", value: formatUsd(c.totalRepairCostUsd), mono: true },
                ]}
              />
            </CardContent>
          </Card>

          {(c.oneWayTrips.length > 0 || c.leaseItems.length > 0) && (
            <Card>
              <CardHeader icon={<Route />} title="Коммерческая история" description={`${c.oneWayTrips.length} One-Way · ${c.leaseItems.length} аренд`} />
              <ul className="divide-y divide-slate-100 text-sm">
                {c.oneWayTrips.map((t) => {
                  const timing = computeTripTiming(t, now);
                  return (
                    <li key={t.id} className="flex items-center justify-between gap-3 px-4 py-2.5 sm:px-5">
                      <div className="min-w-0">
                        <p className="font-mono text-xs font-semibold">{t.bookingRef}</p>
                        <p className="truncate text-xs text-slate-500">{locodeCity(t.pickupLocode)} → {locodeCity(t.dropoffLocode)} · {formatDate(t.handoverDate)}</p>
                      </div>
                      <div className="flex flex-col items-end gap-0.5">
                        <TripStatusBadge status={timing.status} />
                        {timing.detentionUsd > 0 && <span className="font-mono text-xs text-rose-600">{formatUsd(timing.detentionUsd)}</span>}
                      </div>
                    </li>
                  );
                })}
                {c.leaseItems.map((item) => (
                  <li key={item.id}>
                    <Link href={`/leases/${item.lease.id}`} className="flex items-center justify-between gap-3 px-4 py-2.5 hover:bg-slate-50 sm:px-5">
                      <div className="min-w-0">
                        <p className="font-mono text-xs font-semibold">{item.lease.contractNumber}</p>
                        <p className="truncate text-xs text-slate-500">{item.lease.lesseeName} · {formatDate(item.onHireDate)} — {item.offHireDate ? formatDate(item.offHireDate) : "н.в."}</p>
                      </div>
                      <span className="font-mono text-xs text-slate-600">
                        {formatUsd(rentalDaysInRange(item, item.onHireDate, now) * item.lease.dailyRateUsd)}
                      </span>
                    </Link>
                  </li>
                ))}
              </ul>
            </Card>
          )}
        </div>

        <Card className="xl:row-span-2 xl:self-start">
          <CardHeader icon={<History />} title="История операций" description={`${c.events.length} событий · Audit & Movement Log`} />
          <CardContent>
            <EventTimeline events={c.events} />
          </CardContent>
        </Card>
      </div>

      {c.notes && (
        <Card className="mt-4 border-amber-200 bg-amber-50/50 lg:mt-6">
          <CardHeader icon={<Wrench />} title="Примечания" />
          <CardContent className="text-sm whitespace-pre-line text-slate-700">{c.notes}</CardContent>
        </Card>
      )}
    </>
  );
}

input.content:
"use client";

import { useState } from "react";
import { CircleCheck, PackageCheck, TriangleAlert } from "lucide-react";
import { registerOneWayReturnAction } from "@/actions/one-way";
import { Button } from "@/components/ui/button";
import { Field, Input, Textarea } from "@/components/ui/primitives";
import { useServerAction } from "@/components/use-server-action";
import { computeTripTiming } from "@/lib/domain/one-way";
import { locodeCity, terminalsOf } from "@/lib/domain/constants";
import { parseDateInput, toDateInput } from "@/lib/dates";
import { formatDate, formatDays, formatUsd } from "@/lib/format";
import { cn } from "@/lib/utils";

export interface GateInTrip {
  id: string;
  bookingRef: string;
  dropoffLocode: string;
  dropoffTerminal: string;
  handoverDate: Date;
  deadlineDate: Date;
  freeDays: number;
  detentionRatePerDayUsd: number;
}

/** Фиксация возврата по One-Way (Gate-In) с выбором состояния и предпросмотром детеншна. */
export function GateInForm({ trip, onDone }: { trip: GateInTrip; onDone: () => void }) {
  const [returnDate, setReturnDate] = useState(toDateInput(new Date()));
  const [terminal, setTerminal] = useState(trip.dropoffTerminal);
  const [condition, setCondition] = useState<"SOUND" | "DAMAGED">("SOUND");
  const [eorUsd, setEorUsd] = useState("");
  const [note, setNote] = useState("");
  const { run, isPending, fieldErrors } = useServerAction();

  const parsedDate = parseDateInput(returnDate);
  const preview = parsedDate
    ? computeTripTiming({ ...trip, status: "COMPLETED", actualReturnDate: parsedDate }, new Date())
    : null;

  return (
    <form
      className="space-y-5"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => registerOneWayReturnAction(trip.id, { returnDate, terminal, condition, eorUsd, note }), onDone);
      }}
    >
      <div className="rounded-lg bg-slate-50 px-3 py-2.5 text-sm ring-1 ring-slate-200">
        <p className="text-slate-500">Депо назначения</p>
        <p className="font-medium text-slate-900">{locodeCity(trip.dropoffLocode)} · {trip.dropoffTerminal}</p>
        <p className="mt-1 text-xs text-slate-500">Дедлайн: <span className="font-mono">{formatDate(trip.deadlineDate)}</span> · детеншн {formatUsd(trip.detentionRatePerDayUsd)}/сут.</p>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <Field label="Дата Gate-In" htmlFor="gi-date" error={fieldErrors.returnDate}>
          <Input id="gi-date" type="date" value={returnDate} max={toDateInput(new Date())} onChange={(e) => setReturnDate(e.target.value)} />
        </Field>
        <Field label="Терминал приёмки" htmlFor="gi-terminal" error={fieldErrors.terminal}>
          <Input id="gi-terminal" list="gi-terminals" value={terminal} onChange={(e) => setTerminal(e.target.value)} />
          <datalist id="gi-terminals">
            {terminalsOf(trip.dropoffLocode).map((t) => (
              <option key={t} value={t} />
            ))}
          </datalist>
        </Field>
      </div>

      <fieldset>
        <legend className="mb-2 text-xs font-medium text-slate-700">Техническое состояние при приёмке</legend>
        <div className="grid grid-cols-2 gap-2">
          {(
            [
              { value: "SOUND", label: "Исправен", icon: CircleCheck, active: "border-emerald-500 bg-emerald-50 text-emerald-800 ring-emerald-500" },
              { value: "DAMAGED", label: "Поврежден", icon: TriangleAlert, active: "border-rose-500 bg-rose-50 text-rose-800 ring-rose-500" },
            ] as const
          ).map((opt) => (
            <label
              key={opt.value}
              className={cn(
                "flex h-14 cursor-pointer items-center justify-center gap-2 rounded-xl border-2 text-sm font-semibold transition",
                condition === opt.value ? opt.active : "border-slate-200 bg-white text-slate-600 hover:border-slate-300",
              )}
            >
              <input type="radio" name="condition" value={opt.value} checked={condition === opt.value} onChange={() => setCondition(opt.value)} className="sr-only" />
              <opt.icon className="size-5" /> {opt.label}
            </label>
          ))}
        </div>
      </fieldset>

      {condition === "DAMAGED" && (
        <Field label="Оценка ремонта (EOR), $" htmlFor="gi-eor" error={fieldErrors.eorUsd} hint="Будет открыта претензия к контрагенту (статус DISPUTE)">
          <Input id="gi-eor" type="number" inputMode="decimal" min={0} value={eorUsd} onChange={(e) => setEorUsd(e.target.value)} autoFocus />
        </Field>
      )}

      <Field label="Комментарий" htmlFor="gi-note" error={fieldErrors.note}>
        <Textarea id="gi-note" rows={2} value={note} onChange={(e) => setNote(e.target.value)} placeholder="Номер EIR, замечания по пломбе и т.п." />
      </Field>

      {preview && (
        <div className={cn("rounded-lg px-3 py-2.5 text-sm ring-1", preview.overdueDays > 0 ? "bg-rose-50 text-rose-800 ring-rose-200" : "bg-emerald-50 text-emerald-800 ring-emerald-200")}>
          {preview.overdueDays > 0 ? (
            <>Просрочка <b>{formatDays(preview.overdueDays)}</b> → начисляется детеншн <b className="font-mono">{formatUsd(preview.detentionUsd)}</b></>
          ) : (
            <>Возврат в пределах {trip.freeDays} свободных дней — детеншн не начисляется</>
          )}
        </div>
      )}

      <Button type="submit" size="lg" variant="success" className="w-full" loading={isPending}>
        <PackageCheck /> Зафиксировать Gate-In
      </Button>
      <p className="text-center text-xs text-slate-500">Контейнер будет переведён в статус «Свободен на стоке» на терминале назначения</p>
    </form>
  );
}

"use client";

import { useState } from "react";
import { Route } from "lucide-react";
import { createOneWayAction } from "@/actions/one-way";
import { Button } from "@/components/ui/button";
import { Field, Input, Select, Textarea } from "@/components/ui/primitives";
import { useServerAction } from "@/components/use-server-action";
import { LOCATIONS, locodeCity, terminalsOf } from "@/lib/domain/constants";
import { addDays, parseDateInput, toDateInput } from "@/lib/dates";
import { formatBic } from "@/lib/iso6346";
import { formatDate } from "@/lib/format";
import type { IssuableContainer } from "@/lib/queries/containers";

const FREE_DAYS_PRESETS = [14, 21, 30, 45];

export function NewTripForm({ containers, onDone, presetContainerId }: { containers: IssuableContainer[]; onDone: () => void; presetContainerId?: string }) {
  const [v, setV] = useState({
    containerId: presetContainerId ?? containers[0]?.id ?? "",
    counterpartyName: "",
    counterpartyInn: "",
    counterpartyContact: "",
    bookingRef: `OW-${new Date().getUTCFullYear()}-${String(Math.floor(Math.random() * 9000) + 1000)}`,
    dropoffLocode: "RUMOW",
    dropoffTerminal: "ТЛЦ Ворсино",
    handoverDate: toDateInput(new Date()),
    freeDays: "30",
    feeUsd: "0",
    detentionRatePerDayUsd: "15",
    notes: "",
  });
  const { run, isPending, fieldErrors } = useServerAction();
  const set = (key: keyof typeof v, value: string) => setV((prev) => ({ ...prev, [key]: value }));
  const selected = containers.find((c) => c.id === v.containerId);
  const handover = parseDateInput(v.handoverDate);
  const deadline = handover && Number(v.freeDays) > 0 ? addDays(handover, Number(v.freeDays)) : null;

  if (containers.length === 0) {
    return <p className="text-sm text-slate-600">Нет свободных исправных контейнеров для выдачи.</p>;
  }

  return (
    <form
      className="space-y-4"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => createOneWayAction(v), onDone);
      }}
    >
      <Field label="Контейнер (свободен и исправен)" htmlFor="nt-container" error={fieldErrors.containerId}>
        <Select id="nt-container" value={v.containerId} onChange={(e) => set("containerId", e.target.value)} className="font-mono">
          {containers.map((c) => (
            <option key={c.id} value={c.id}>
              {formatBic(c.bicCode)} · {c.sizeType} · {c.currentLocode} {c.currentTerminal}
            </option>
          ))}
        </Select>
      </Field>
      {selected && (
        <p className="-mt-2 text-xs text-slate-500">
          Точка выдачи: <b>{locodeCity(selected.currentLocode)}</b>, {selected.currentTerminal}
        </p>
      )}

      <div className="grid grid-cols-2 gap-3">
        <Field label="Контрагент" htmlFor="nt-cp" error={fieldErrors.counterpartyName} className="col-span-2">
          <Input id="nt-cp" value={v.counterpartyName} onChange={(e) => set("counterpartyName", e.target.value)} placeholder="ООО «…»" required />
        </Field>
        <Field label="ИНН" htmlFor="nt-inn" error={fieldErrors.counterpartyInn}>
          <Input id="nt-inn" inputMode="numeric" value={v.counterpartyInn} onChange={(e) => set("counterpartyInn", e.target.value.replace(/\D/g, ""))} maxLength={12} className="font-mono" />
        </Field>
        <Field label="Заявка / договор" htmlFor="nt-booking" error={fieldErrors.bookingRef}>
          <Input id="nt-booking" value={v.bookingRef} onChange={(e) => set("bookingRef", e.target.value)} className="font-mono" />
        </Field>
        <Field label="Контакт" htmlFor="nt-contact" error={fieldErrors.counterpartyContact} className="col-span-2">
          <Input id="nt-contact" value={v.counterpartyContact} onChange={(e) => set("counterpartyContact", e.target.value)} placeholder="ФИО, телефон" />
        </Field>
        <Field label="Точка возврата (LOCODE)" htmlFor="nt-dropoff" error={fieldErrors.dropoffLocode}>
          <Select id="nt-dropoff" value={v.dropoffLocode} onChange={(e) => setV((p) => ({ ...p, dropoffLocode: e.target.value, dropoffTerminal: terminalsOf(e.target.value)[0] ?? "" }))}>
            {LOCATIONS.map((l) => (
              <option key={l.code} value={l.code}>{l.code} · {l.city}</option>
            ))}
          </Select>
        </Field>
        <Field label="Депо возврата" htmlFor="nt-dterm" error={fieldErrors.dropoffTerminal}>
          <Input id="nt-dterm" list="nt-terminals" value={v.dropoffTerminal} onChange={(e) => set("dropoffTerminal", e.target.value)} />
          <datalist id="nt-terminals">
            {terminalsOf(v.dropoffLocode).map((t) => (
              <option key={t} value={t} />
            ))}
          </datalist>
        </Field>
        <Field label="Дата выдачи (Gate-Out)" htmlFor="nt-date" error={fieldErrors.handoverDate}>
          <Input id="nt-date" type="date" value={v.handoverDate} onChange={(e) => set("handoverDate", e.target.value)} />
        </Field>
        <Field label="Свободных дней" htmlFor="nt-free" error={fieldErrors.freeDays}>
          <Input id="nt-free" type="number" inputMode="numeric" min={1} value={v.freeDays} onChange={(e) => set("freeDays", e.target.value)} />
        </Field>
      </div>
      <div className="-mt-1 flex flex-wrap gap-1.5">
        {FREE_DAYS_PRESETS.map((d) => (
          <button key={d} type="button" onClick={() => set("freeDays", String(d))} className="rounded-full bg-slate-100 px-3 py-1 text-xs font-medium text-slate-600 hover:bg-indigo-100 hover:text-indigo-700">
            {d} дн.
          </button>
        ))}
        {deadline && <span className="ml-auto self-center text-xs text-slate-500">Дедлайн возврата: <b className="font-mono text-slate-900">{formatDate(deadline)}</b></span>}
      </div>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Фикс. ставка / депозит, $" htmlFor="nt-fee" error={fieldErrors.feeUsd} hint="0 — бесплатная выдача">
          <Input id="nt-fee" type="number" inputMode="decimal" min={0} value={v.feeUsd} onChange={(e) => set("feeUsd", e.target.value)} />
        </Field>
        <Field label="Детеншн, $/сутки" htmlFor="nt-det" error={fieldErrors.detentionRatePerDayUsd}>
          <Input id="nt-det" type="number" inputMode="decimal" min={0} value={v.detentionRatePerDayUsd} onChange={(e) => set("detentionRatePerDayUsd", e.target.value)} />
        </Field>
      </div>
      <Field label="Примечание" htmlFor="nt-notes" error={fieldErrors.notes}>
        <Textarea id="nt-notes" rows={2} value={v.notes} onChange={(e) => set("notes", e.target.value)} />
      </Field>
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <Route /> Выдать в One-Way
      </Button>
    </form>
  );
}

