          {containers.map((c) => (
            <label key={c.id} className={cn("flex cursor-pointer items-center gap-3 rounded-md px-2 py-2 text-sm", selected.includes(c.id) ? "bg-indigo-50" : "hover:bg-slate-50")}>
              <input type="checkbox" checked={selected.includes(c.id)} onChange={() => setSelected((p) => toggle(p, c.id))} className="size-4 accent-indigo-600" />
              <BicCode code={c.bicCode} size="sm" />
              <span className="font-mono text-xs text-slate-500">{c.sizeType}</span>
              <span className="ml-auto truncate text-xs text-slate-500">{c.currentLocode} · {c.currentTerminal}</span>
            </label>
          ))}
        </div>
        {fieldErrors.containerIds && <p className="mt-1 text-xs text-rose-600">{fieldErrors.containerIds}</p>}
      </fieldset>

      <Field label="Примечание" htmlFor="nl-notes" error={fieldErrors.notes}>
        <Textarea id="nl-notes" rows={2} value={v.notes} onChange={(e) => set("notes", e.target.value)} />
      </Field>

      <div className="rounded-lg bg-slate-900 px-4 py-3 text-sm text-white">
        <p className="text-slate-400">Стоимость договора за весь срок</p>
        <p className="font-mono text-xl font-semibold">{formatUsd(Math.round(contractValue))}</p>
        <p className="font-mono text-xs text-slate-400">{termDays} сут. × {formatUsd(Number(v.dailyRateUsd || 0), 2)} × {selected.length} ед.</p>
      </div>

      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <FileText /> Оформить договор и On-Hire
      </Button>
    </form>
  );
}

/* ── Продление ───────────────────────────────────────────────────────── */

export function ExtendLeaseForm({ lease, onDone }: { lease: LeaseRow; onDone: () => void }) {
  const [months, setMonths] = useState("3");
  const [rate, setRate] = useState(String(lease.dailyRateUsd));
  const { run, isPending, fieldErrors } = useServerAction();
  const newEnd = Number(months) > 0 ? addMonths(new Date(lease.endDate), Number(months)) : null;

  return (
    <form
      className="space-y-4"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => extendLeaseAction(lease.id, { months, newDailyRateUsd: rate }), onDone);
      }}
    >
      <p className="text-sm text-slate-600">
        Текущий срок окончания: <b className="font-mono">{formatDate(lease.endDate)}</b>
      </p>
      <div className="flex gap-1.5">
        {[3, 6, 12].map((m) => (
          <button key={m} type="button" onClick={() => setMonths(String(m))} className={cn("flex-1 rounded-lg py-2.5 text-sm font-medium ring-1", months === String(m) ? "bg-indigo-600 text-white ring-indigo-600" : "bg-white text-slate-700 ring-slate-200")}>
            +{m} мес.
          </button>
        ))}
      </div>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Продлить на, мес." htmlFor="ex-m" error={fieldErrors.months}>
          <Input id="ex-m" type="number" inputMode="numeric" min={1} value={months} onChange={(e) => setMonths(e.target.value)} />
        </Field>
        <Field label="Per Diem, $/сут." htmlFor="ex-rate" error={fieldErrors.newDailyRateUsd}>
          <Input id="ex-rate" type="number" inputMode="decimal" step="0.05" value={rate} onChange={(e) => setRate(e.target.value)} />
        </Field>
      </div>
      {newEnd && (
        <p className="rounded-lg bg-indigo-50 px-3 py-2 text-sm text-indigo-900 ring-1 ring-indigo-100">
          Новый срок окончания: <b className="font-mono">{formatDate(newEnd)}</b>
        </p>
      )}
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <CalendarPlus /> Продлить договор
      </Button>
    </form>
  );
}

/* ── Off-Hire ────────────────────────────────────────────────────────── */

export function OffHireForm({ lease, onDone }: { lease: LeaseRow; onDone: () => void }) {
  const onHire = lease.items.filter((i) => !i.offHireDate);
  const [itemIds, setItemIds] = useState<string[]>(onHire.map((i) => i.id));
  const [returnDate, setReturnDate] = useState(toDateInput(new Date()));
  const [returnLocode, setReturnLocode] = useState(lease.allowedReturnLocodes[0] ?? "");
  const [terminal, setTerminal] = useState(terminalsOf(lease.allowedReturnLocodes[0] ?? "")[0] ?? "");
  const [condition, setCondition] = useState<"SOUND" | "DAMAGED">("SOUND");
  const [eorUsd, setEorUsd] = useState("");
  const { run, isPending, fieldErrors } = useServerAction();

  return (
    <form
      className="space-y-5"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => offHireAction(lease.id, { itemIds, returnDate, returnLocode, terminal, condition, eorUsd }), onDone);
      }}
    >
      <fieldset>
        <legend className="mb-2 text-xs font-medium text-slate-700">Контейнеры к возврату</legend>
        <div className="space-y-1 rounded-lg border border-slate-200 p-1">
          {onHire.map((i) => (
            <label key={i.id} className={cn("flex min-h-11 cursor-pointer items-center gap-3 rounded-md px-2 text-sm", itemIds.includes(i.id) ? "bg-indigo-50" : "hover:bg-slate-50")}>
              <input type="checkbox" checked={itemIds.includes(i.id)} onChange={() => setItemIds((p) => (p.includes(i.id) ? p.filter((x) => x !== i.id) : [...p, i.id]))} className="size-4 accent-indigo-600" />
              <BicCode code={i.bicCode} size="sm" />
              <span className="ml-auto font-mono text-xs text-slate-500">{i.sizeType}</span>
            </label>
          ))}
        </div>
        {fieldErrors.itemIds && <p className="mt-1 text-xs text-rose-600">{fieldErrors.itemIds}</p>}
      </fieldset>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Дата Off-Hire" htmlFor="oh-date" error={fieldErrors.returnDate}>
          <Input id="oh-date" type="date" value={returnDate} max={toDateInput(new Date())} onChange={(e) => setReturnDate(e.target.value)} />
        </Field>
        <Field label="Регион возврата" htmlFor="oh-loc" error={fieldErrors.returnLocode} hint="Только разрешённые договором">
          <Select id="oh-loc" value={returnLocode} onChange={(e) => { setReturnLocode(e.target.value); setTerminal(terminalsOf(e.target.value)[0] ?? ""); }}>
            {lease.allowedReturnLocodes.map((code) => (
              <option key={code} value={code}>{code} · {locodeCity(code)}</option>
            ))}
          </Select>
        </Field>
        <Field label="Депо возврата" htmlFor="oh-term" error={fieldErrors.terminal} className="col-span-2">
          <Input id="oh-term" list="oh-terminals" value={terminal} onChange={(e) => setTerminal(e.target.value)} />
          <datalist id="oh-terminals">
            {terminalsOf(returnLocode).map((t) => (
              <option key={t} value={t} />
            ))}
          </datalist>
        </Field>
      </div>
      <fieldset>
        <legend className="mb-2 text-xs font-medium text-slate-700">Off-Hire Survey</legend>
        <div className="grid grid-cols-2 gap-2">
          {(
            [
              { value: "SOUND", label: "Без замечаний", icon: CircleCheck, active: "border-emerald-500 bg-emerald-50 text-emerald-800" },
              { value: "DAMAGED", label: "Повреждение", icon: TriangleAlert, active: "border-rose-500 bg-rose-50 text-rose-800" },
            ] as const
          ).map((opt) => (
            <label key={opt.value} className={cn("flex h-12 cursor-pointer items-center justify-center gap-2 rounded-xl border-2 text-sm font-semibold", condition === opt.value ? opt.active : "border-slate-200 text-slate-600")}>
              <input type="radio" className="sr-only" checked={condition === opt.value} onChange={() => setCondition(opt.value)} />
              <opt.icon className="size-4" /> {opt.label}
            </label>
          ))}
        </div>
      </fieldset>
      {condition === "DAMAGED" && (
        <Field label="EOR, $" htmlFor="oh-eor" error={fieldErrors.eorUsd} hint="Выставляется арендатору по условиям договора">
          <Input id="oh-eor" type="number" inputMode="decimal" min={0} value={eorUsd} onChange={(e) => setEorUsd(e.target.value)} />
        </Field>
      )}
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <PackageCheck /> Оформить Off-Hire ({itemIds.length} ед.)
      </Button>
    </form>
  );
}

/* ── Статус оплаты ───────────────────────────────────────────────────── */

export function PaymentStatusForm({ lease, onDone }: { lease: LeaseRow; onDone: () => void }) {
  const { run, isPending } = useServerAction();
  const tones: Record<string, string> = { PAID: "border-emerald-500 bg-emerald-50 text-emerald-800", PENDING: "border-amber-500 bg-amber-50 text-amber-800", OVERDUE: "border-rose-500 bg-rose-50 text-rose-800" };
  return (
    <div className="space-y-2">
      {PAYMENT_STATUSES.map((status) => (
        <button
          key={status}
          type="button"
          disabled={isPending}
          onClick={() => run(() => updatePaymentStatusAction(lease.id, { paymentStatus: status }), onDone)}
          className={cn("flex h-12 w-full items-center justify-between rounded-xl border-2 px-4 text-sm font-semibold transition", lease.paymentStatus === status ? tones[status] : "border-slate-200 text-slate-700 hover:border-slate-300")}
        >
          {PAYMENT_STATUS_LABELS[status]}
          {lease.paymentStatus === status && <span className="text-xs font-normal">текущий</span>}
        </button>
      ))}
    </div>
  );
}

export { formatBic };

toolUseResult.content:
"use client";

import { useState } from "react";
import { CalendarPlus, CircleCheck, FileText, PackageCheck, TriangleAlert } from "lucide-react";
import { createLeaseAction, extendLeaseAction, offHireAction, updatePaymentStatusAction } from "@/actions/leases";
import { Button } from "@/components/ui/button";
import { Field, Input, Select, Textarea } from "@/components/ui/primitives";
import { BicCode } from "@/components/status-badges";
import { useServerAction } from "@/components/use-server-action";
import { LOCATIONS, PAYMENT_STATUSES, PAYMENT_STATUS_LABELS, locodeCity, terminalsOf } from "@/lib/domain/constants";
import { addMonths, parseDateInput, toDateInput } from "@/lib/dates";
import { formatBic } from "@/lib/iso6346";
import { formatDate, formatUsd } from "@/lib/format";
import { cn } from "@/lib/utils";
import type { IssuableContainer } from "@/lib/queries/containers";
import type { LeaseRow } from "@/lib/queries/operations";

/* ── Новый договор ───────────────────────────────────────────────────── */

export function NewLeaseForm({ containers, onDone }: { containers: IssuableContainer[]; onDone: () => void }) {
  const today = new Date();
  const [v, setV] = useState({
    contractNumber: `LC-${today.getUTCFullYear()}/${String(Math.floor(Math.random() * 900) + 100)}`,
    lesseeName: "",
    lesseeInn: "",
    contactPerson: "",
    contactPhone: "",
    contactEmail: "",
    startDate: toDateInput(today),
    endDate: toDateInput(addMonths(today, 12)),
    dailyRateUsd: "2.50",
    depositUsd: "0",
    notes: "",
  });
  const [autoRenewal, setAutoRenewal] = useState(false);
  const [allowed, setAllowed] = useState<string[]>(["RUVVO", "RUMOW"]);
  const [selected, setSelected] = useState<string[]>([]);
  const { run, isPending, fieldErrors } = useServerAction();
  const set = (key: keyof typeof v, value: string) => setV((p) => ({ ...p, [key]: value }));
  const toggle = (list: string[], value: string) => (list.includes(value) ? list.filter((x) => x !== value) : [...list, value]);

  const start = parseDateInput(v.startDate);
  const end = parseDateInput(v.endDate);
  const termDays = start && end ? Math.max(0, Math.round((end.getTime() - start.getTime()) / 86_400_000)) : 0;
  const contractValue = termDays * Number(v.dailyRateUsd || 0) * selected.length;

  return (
    <form
      className="space-y-5"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => createLeaseAction({ ...v, autoRenewal, allowedReturnLocodes: allowed, containerIds: selected }), onDone);
      }}
    >
      <div className="grid grid-cols-2 gap-3">
        <Field label="Номер договора" htmlFor="nl-num" error={fieldErrors.contractNumber}>
          <Input id="nl-num" value={v.contractNumber} onChange={(e) => set("contractNumber", e.target.value)} className="font-mono" />
        </Field>
        <Field label="ИНН арендатора" htmlFor="nl-inn" error={fieldErrors.lesseeInn}>
          <Input id="nl-inn" inputMode="numeric" maxLength={12} value={v.lesseeInn} onChange={(e) => set("lesseeInn", e.target.value.replace(/\D/g, ""))} className="font-mono" />
        </Field>
        <Field label="Арендатор" htmlFor="nl-lessee" error={fieldErrors.lesseeName} className="col-span-2">
          <Input id="nl-lessee" value={v.lesseeName} onChange={(e) => set("lesseeName", e.target.value)} placeholder="ООО «…»" required />
        </Field>
        <Field label="Контактное лицо" htmlFor="nl-person" error={fieldErrors.contactPerson} className="col-span-2">
          <Input id="nl-person" value={v.contactPerson} onChange={(e) => set("contactPerson", e.target.value)} required />
        </Field>
        <Field label="Телефон" htmlFor="nl-phone" error={fieldErrors.contactPhone}>
          <Input id="nl-phone" type="tel" value={v.contactPhone} onChange={(e) => set("contactPhone", e.target.value)} />
        </Field>
        <Field label="Email" htmlFor="nl-email" error={fieldErrors.contactEmail}>
          <Input id="nl-email" type="email" value={v.contactEmail} onChange={(e) => set("contactEmail", e.target.value)} />
        </Field>
        <Field label="On-Hire (начало)" htmlFor="nl-start" error={fieldErrors.startDate}>
          <Input id="nl-start" type="date" value={v.startDate} onChange={(e) => set("startDate", e.target.value)} />
        </Field>
        <Field label="Плановый Off-Hire" htmlFor="nl-end" error={fieldErrors.endDate}>
          <Input id="nl-end" type="date" value={v.endDate} onChange={(e) => set("endDate", e.target.value)} />
        </Field>
        <Field label="Per Diem, $/сутки за ед." htmlFor="nl-rate" error={fieldErrors.dailyRateUsd}>
          <Input id="nl-rate" type="number" inputMode="decimal" step="0.05" min={0} value={v.dailyRateUsd} onChange={(e) => set("dailyRateUsd", e.target.value)} />
        </Field>
        <Field label="Депозит, $" htmlFor="nl-deposit" error={fieldErrors.depositUsd}>
          <Input id="nl-deposit" type="number" inputMode="decimal" min={0} value={v.depositUsd} onChange={(e) => set("depositUsd", e.target.value)} />
        </Field>
      </div>

      <label className="flex items-center gap-3 rounded-lg border border-slate-200 px-3 py-3 text-sm">
        <input type="checkbox" checked={autoRenewal} onChange={(e) => setAutoRenewal(e.target.checked)} className="size-4 accent-indigo-600" />
        Автопролонгация по окончании срока
      </label>

      <fieldset>
        <legend className="mb-2 text-xs font-medium text-slate-700">Разрешённые регионы возврата</legend>
        <div className="flex flex-wrap gap-1.5">
          {LOCATIONS.map((l) => (
            <button
              key={l.code}
              type="button"
              aria-pressed={allowed.includes(l.code)}
              onClick={() => setAllowed((p) => toggle(p, l.code))}
              className={cn("rounded-full px-3 py-1.5 text-xs font-medium ring-1", allowed.includes(l.code) ? "bg-indigo-600 text-white ring-indigo-600" : "bg-white text-slate-600 ring-slate-200")}
            >
              {l.code} · {l.city}
            </button>
          ))}
        </div>
        {fieldErrors.allowedReturnLocodes && <p className="mt-1 text-xs text-rose-600">{fieldErrors.allowedReturnLocodes}</p>}
      </fieldset>

      <fieldset>
        <legend className="mb-2 text-xs font-medium text-slate-700">Контейнеры ({selected.length} выбрано из {containers.length} доступных)</legend>
        <div className="max-h-56 space-y-1 overflow-y-auto rounded-lg border border-slate-200 p-1">
          {containers.length === 0 && <p className="p-3 text-sm text-slate-500">Нет свободных исправных контейнеров</p>}
          {containers.map((c) => (
            <label key={c.id} className={cn("flex cursor-pointer items-center gap-3 rounded-md px-2 py-2 text-sm", selected.includes(c.id) ? "bg-indigo-50" : "hover:bg-slate-50")}>
              <input type="checkbox" checked={selected.includes(c.id)} onChange={() => setSelected((p) => toggle(p, c.id))} className="size-4 accent-indigo-600" />
              <BicCode code={c.bicCode} size="sm" />
              <span className="font-mono text-xs text-slate-500">{c.sizeType}</span>
              <span className="ml-auto truncate text-xs text-slate-500">{c.currentLocode} · {c.currentTerminal}</span>
            </label>
          ))}
        </div>
        {fieldErrors.containerIds && <p className="mt-1 text-xs text-rose-600">{fieldErrors.containerIds}</p>}
      </fieldset>

      <Field label="Примечание" htmlFor="nl-notes" error={fieldErrors.notes}>
        <Textarea id="nl-notes" rows={2} value={v.notes} onChange={(e) => set("notes", e.target.value)} />
      </Field>

      <div className="rounded-lg bg-slate-900 px-4 py-3 text-sm text-white">
        <p className="text-slate-400">Стоимость договора за весь срок</p>
        <p className="font-mono text-xl font-semibold">{formatUsd(Math.round(contractValue))}</p>
        <p className="font-mono text-xs text-slate-400">{termDays} сут. × {formatUsd(Number(v.dailyRateUsd || 0), 2)} × {selected.length} ед.</p>
      </div>

      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <FileText /> Оформить договор и On-Hire
      </Button>
    </form>
  );
}

/* ── Продление ───────────────────────────────────────────────────────── */

export function ExtendLeaseForm({ lease, onDone }: { lease: LeaseRow; onDone: () => void }) {
  const [months, setMonths] = useState("3");
  const [rate, setRate] = useState(String(lease.dailyRateUsd));
  const { run, isPending, fieldErrors } = useServerAction();
  const newEnd = Number(months) > 0 ? addMonths(new Date(lease.endDate), Number(months)) : null;

  return (
    <form
      className="space-y-4"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => extendLeaseAction(lease.id, { months, newDailyRateUsd: rate }), onDone);
      }}
    >
      <p className="text-sm text-slate-600">
        Текущий срок окончания: <b className="font-mono">{formatDate(lease.endDate)}</b>
      </p>
      <div className="flex gap-1.5">
        {[3, 6, 12].map((m) => (
          <button key={m} type="button" onClick={() => setMonths(String(m))} className={cn("flex-1 rounded-lg py-2.5 text-sm font-medium ring-1", months === String(m) ? "bg-indigo-600 text-white ring-indigo-600" : "bg-white text-slate-700 ring-slate-200")}>
            +{m} мес.
          </button>
        ))}
      </div>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Продлить на, мес." htmlFor="ex-m" error={fieldErrors.months}>
          <Input id="ex-m" type="number" inputMode="numeric" min={1} value={months} onChange={(e) => setMonths(e.target.value)} />
        </Field>
        <Field label="Per Diem, $/сут." htmlFor="ex-rate" error={fieldErrors.newDailyRateUsd}>
          <Input id="ex-rate" type="number" inputMode="decimal" step="0.05" value={rate} onChange={(e) => setRate(e.target.value)} />
        </Field>
      </div>
      {newEnd && (
        <p className="rounded-lg bg-indigo-50 px-3 py-2 text-sm text-indigo-900 ring-1 ring-indigo-100">
          Новый срок окончания: <b className="font-mono">{formatDate(newEnd)}</b>
        </p>
      )}
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <CalendarPlus /> Продлить договор
      </Button>
    </form>
  );
}

/* ── Off-Hire ────────────────────────────────────────────────────────── */

export function OffHireForm({ lease, onDone }: { lease: LeaseRow; onDone: () => void }) {
  const onHire = lease.items.filter((i) => !i.offHireDate);
  const [itemIds, setItemIds] = useState<string[]>(onHire.map((i) => i.id));
  const [returnDate, setReturnDate] = useState(toDateInput(new Date()));
  const [returnLocode, setReturnLocode] = useState(lease.allowedReturnLocodes[0] ?? "");
  const [terminal, setTerminal] = useState(terminalsOf(lease.allowedReturnLocodes[0] ?? "")[0] ?? "");
  const [condition, setCondition] = useState<"SOUND" | "DAMAGED">("SOUND");
  const [eorUsd, setEorUsd] = useState("");
  const { run, isPending, fieldErrors } = useServerAction();

  return (
    <form
      className="space-y-5"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => offHireAction(lease.id, { itemIds, returnDate, returnLocode, terminal, condition, eorUsd }), onDone);
      }}
    >
      <fieldset>
        <legend className="mb-2 text-xs font-medium text-slate-700">Контейнеры к возврату</legend>
        <div className="space-y-1 rounded-lg border border-slate-200 p-1">
          {onHire.map((i) => (
            <label key={i.id} className={cn("flex min-h-11 cursor-pointer items-center gap-3 rounded-md px-2 text-sm", itemIds.includes(i.id) ? "bg-indigo-50" : "hover:bg-slate-50")}>
              <input type="checkbox" checked={itemIds.includes(i.id)} onChange={() => setItemIds((p) => (p.includes(i.id) ? p.filter((x) => x !== i.id) : [...p, i.id]))} className="size-4 accent-indigo-600" />
              <BicCode code={i.bicCode} size="sm" />
              <span className="ml-auto font-mono text-xs text-slate-500">{i.sizeType}</span>
            </label>
          ))}
        </div>
        {fieldErrors.itemIds && <p className="mt-1 text-xs text-rose-600">{fieldErrors.itemIds}</p>}
      </fieldset>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Дата Off-Hire" htmlFor="oh-date" error={fieldErrors.returnDate}>
          <Input id="oh-date" type="date" value={returnDate} max={toDateInput(new Date())} onChange={(e) => setReturnDate(e.target.value)} />
        </Field>
        <Field label="Регион возврата" htmlFor="oh-loc" error={fieldErrors.returnLocode} hint="Только разрешённые договором">
          <Select id="oh-loc" value={returnLocode} onChange={(e) => { setReturnLocode(e.target.value); setTerminal(terminalsOf(e.target.value)[0] ?? ""); }}>
            {lease.allowedReturnLocodes.map((code) => (
              <option key={code} value={code}>{code} · {locodeCity(code)}</option>
            ))}
          </Select>
        </Field>
        <Field label="Депо возврата" htmlFor="oh-term" error={fieldErrors.terminal} className="col-span-2">
          <Input id="oh-term" list="oh-terminals" value={terminal} onChange={(e) => setTerminal(e.target.value)} />
          <datalist id="oh-terminals">
            {terminalsOf(returnLocode).map((t) => (
              <option key={t} value={t} />
            ))}
          </datalist>
        </Field>
      </div>
      <fieldset>
        <legend className="mb-2 text-xs font-medium text-slate-700">Off-Hire Survey</legend>
        <div className="grid grid-cols-2 gap-2">
          {(
            [
              { value: "SOUND", label: "Без замечаний", icon: CircleCheck, active: "border-emerald-500 bg-emerald-50 text-emerald-800" },
              { value: "DAMAGED", label: "Повреждение", icon: TriangleAlert, active: "border-rose-500 bg-rose-50 text-rose-800" },
            ] as const
          ).map((opt) => (
            <label key={opt.value} className={cn("flex h-12 cursor-pointer items-center justify-center gap-2 rounded-xl border-2 text-sm font-semibold", condition === opt.value ? opt.active : "border-slate-200 text-slate-600")}>
              <input type="radio" className="sr-only" checked={condition === opt.value} onChange={() => setCondition(opt.value)} />
              <opt.icon className="size-4" /> {opt.label}
            </label>
          ))}
        </div>
      </fieldset>
      {condition === "DAMAGED" && (
        <Field label="EOR, $" htmlFor="oh-eor" error={fieldErrors.eorUsd} hint="Выставляется арендатору по условиям договора">
          <Input id="oh-eor" type="number" inputMode="decimal" min={0} value={eorUsd} onChange={(e) => setEorUsd(e.target.value)} />
        </Field>
      )}
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <PackageCheck /> Оформить Off-Hire ({itemIds.length} ед.)
      </Button>
    </form>
  );
}

/* ── Статус оплаты ───────────────────────────────────────────────────── */

export function PaymentStatusForm({ lease, onDone }: { lease: LeaseRow; onDone: () => void }) {
  const { run, isPending } = useServerAction();
  const tones: Record<string, string> = { PAID: "border-emerald-500 bg-emerald-50 text-emerald-800", PENDING: "border-amber-500 bg-amber-50 text-amber-800", OVERDUE: "border-rose-500 bg-rose-50 text-rose-800" };
  return (
    <div className="space-y-2">
      {PAYMENT_STATUSES.map((status) => (
        <button
          key={status}
          type="button"
          disabled={isPending}
          onClick={() => run(() => updatePaymentStatusAction(lease.id, { paymentStatus: status }), onDone)}
          className={cn("flex h-12 w-full items-center justify-between rounded-xl border-2 px-4 text-sm font-semibold transition", lease.paymentStatus === status ? tones[status] : "border-slate-200 text-slate-700 hover:border-slate-300")}
        >
          {PAYMENT_STATUS_LABELS[status]}
          {lease.paymentStatus === status && <span className="text-xs font-normal">текущий</span>}
        </button>
      ))}
    </div>
  );
}

export { formatBic };

input.content:
"use client";

import Link from "next/link";
import { useMemo, useState } from "react";
import { ChevronRight, FileText, Plus, Repeat, Search } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, EmptyState, Input } from "@/components/ui/primitives";
import { Sheet } from "@/components/ui/sheet";
import { LeaseExpiryBadge, PaymentBadge } from "@/components/status-badges";
import { NewLeaseForm } from "./lease-forms";
import { formatDate, formatUsd } from "@/lib/format";
import { locodeCity } from "@/lib/domain/constants";
import { cn } from "@/lib/utils";
import type { LeaseRow } from "@/lib/queries/operations";
import type { IssuableContainer } from "@/lib/queries/containers";

type Tab = "active" | "attention" | "expiring" | "debt" | "completed";

const TABS: { id: Tab; label: string }[] = [
  { id: "active", label: "Действующие" },
  { id: "attention", label: "Требуют внимания" },
  { id: "expiring", label: "Истекают ≤ 30 дн." },
  { id: "debt", label: "Задолженность" },
  { id: "completed", label: "Закрытые" },
];

function inTab(l: LeaseRow, tab: Tab): boolean {
  const active = l.status === "ACTIVE";
  switch (tab) {
    case "active":
      return active;
    case "attention":
      return active && l.metrics.needsAttention;
    case "expiring":
      return active && ["CRITICAL", "WARNING", "EXPIRED"].includes(l.metrics.expiryLevel);
    case "debt":
      return active && l.paymentStatus === "OVERDUE";
    case "completed":
      return !active;
  }
}

export function LeaseList({ leases, issuable }: { leases: LeaseRow[]; issuable: IssuableContainer[] }) {
  const [tab, setTab] = useState<Tab>("active");
  const [q, setQ] = useState("");
  const [newOpen, setNewOpen] = useState(false);

  const active = leases.filter((l) => l.status === "ACTIVE");
  const totals = {
    units: active.reduce((s, l) => s + l.metrics.activeUnits, 0),
    monthly: active.reduce((s, l) => s + l.metrics.monthlyRunRateUsd, 0),
    accruedMonth: active.reduce((s, l) => s + l.metrics.accruedThisMonthUsd, 0),
    accruedTotal: leases.reduce((s, l) => s + l.metrics.accruedTotalUsd, 0),
  };

  const visible = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return leases.filter((l) => inTab(l, tab)).filter((l) => !needle || l.contractNumber.toLowerCase().includes(needle) || l.lesseeName.toLowerCase().includes(needle));
  }, [leases, tab, q]);

  return (
    <>
      <div className="mb-4 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <Tile label="Единиц в аренде" value={String(totals.units)} sub={`${active.length} действующих договоров`} />
        <Tile label="Доход в месяц (run-rate)" value={formatUsd(Math.round(totals.monthly))} sub="единицы × Per Diem × дни месяца" accent />
        <Tile label="Начислено в этом месяце" value={formatUsd(Math.round(totals.accruedMonth))} sub="с 1-го числа по сегодня" />
        <Tile label="Начислено за всё время" value={formatUsd(Math.round(totals.accruedTotal))} sub="по всем договорам" />
      </div>

      <div className="mb-4 flex flex-col gap-3 2xl:flex-row 2xl:items-center 2xl:justify-between">
        <div className="scrollbar-thin -mx-4 flex gap-1 overflow-x-auto px-4 pb-1 sm:mx-0 sm:px-0" role="tablist">
          {TABS.map((t) => {
            const count = leases.filter((l) => inTab(l, t.id)).length;
            return (
              <button
                key={t.id}
                role="tab"
                aria-selected={tab === t.id}
                onClick={() => setTab(t.id)}
                className={cn("flex shrink-0 items-center gap-1.5 rounded-lg px-3 py-2 text-sm font-medium", tab === t.id ? "bg-slate-900 text-white" : "bg-white text-slate-600 ring-1 ring-slate-200 hover:bg-slate-50")}
              >
                {t.label}
                <span className={cn("rounded px-1.5 font-mono text-xs", tab === t.id ? "bg-white/20" : "bg-slate-100")}>{count}</span>
              </button>
            );
          })}
        </div>
        <div className="flex gap-2">
          <div className="relative flex-1 2xl:w-72">
            <Search className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-slate-400" aria-hidden />
            <Input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Договор или арендатор" className="pl-9" aria-label="Поиск договора" />
          </div>
          <Button className="h-11 lg:h-10" onClick={() => setNewOpen(true)}>
            <Plus /> <span className="hidden sm:inline">Новый договор</span>
          </Button>
        </div>
      </div>

      {visible.length === 0 ? (
        <Card>
          <EmptyState icon={<FileText />} title="Договоров нет" description="В этой категории нет договоров аренды." />
        </Card>
      ) : (
        <>
          <Card className="hidden overflow-hidden xl:block">
            <table className="w-full text-sm">
              <thead className="bg-slate-50 text-left text-xs text-slate-500">
                <tr>
                  <th className="px-4 py-2.5 font-medium">Договор / арендатор</th>
                  <th className="px-3 py-2.5 font-medium">Срок</th>
                  <th className="px-3 py-2.5 text-right font-medium">Ед.</th>
                  <th className="px-3 py-2.5 text-right font-medium">Per Diem</th>
                  <th className="px-3 py-2.5 text-right font-medium">За месяц</th>
                  <th className="px-3 py-2.5 text-right font-medium">За весь срок</th>
                  <th className="px-3 py-2.5 font-medium">Оплата</th>
                  <th className="w-8" />
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {visible.map((l) => (
                  <tr key={l.id} className="group hover:bg-slate-50/80">
                    <td className="px-4 py-3">
                      <Link href={`/leases/${l.id}`} className="block">
                        <span className="font-mono font-semibold text-slate-900 group-hover:text-indigo-700">{l.contractNumber}</span>
                        {l.autoRenewal && <Repeat className="ml-1.5 inline size-3.5 text-indigo-500" aria-label="Автопролонгация" />}
                        <p className="text-slate-600">{l.lesseeName}</p>
                      </Link>
                    </td>
                    <td className="px-3 py-3">
                      <p className="font-mono text-xs text-slate-600">{formatDate(l.startDate)} — {formatDate(l.endDate)}</p>
                      <div className="mt-1"><LeaseExpiryBadge level={l.metrics.expiryLevel} daysToEnd={l.metrics.daysToEnd} /></div>
                    </td>
                    <td className="px-3 py-3 text-right font-mono">{l.metrics.activeUnits}<span className="text-slate-400">/{l.metrics.totalUnits}</span></td>
                    <td className="px-3 py-3 text-right font-mono">{formatUsd(l.dailyRateUsd, 2)}</td>
                    <td className="px-3 py-3 text-right font-mono">{formatUsd(Math.round(l.metrics.accruedThisMonthUsd))}</td>
                    <td className="px-3 py-3 text-right font-mono font-semibold">{formatUsd(Math.round(l.metrics.accruedTotalUsd))}</td>
                    <td className="px-3 py-3"><PaymentBadge status={l.paymentStatus} /></td>
                    <td className="pr-3">
                      <Link href={`/leases/${l.id}`} aria-label={`Открыть ${l.contractNumber}`} className="text-slate-300 group-hover:text-slate-500"><ChevronRight className="size-4" /></Link>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </Card>

          <ul className="grid gap-3 md:grid-cols-2 xl:hidden">
            {visible.map((l) => (
              <li key={l.id}>
                <Link href={`/leases/${l.id}`} className={cn("block rounded-xl border bg-white p-4 shadow-sm active:scale-[0.99]", l.metrics.needsAttention ? "border-amber-300" : "border-slate-200")}>
                  <div className="flex items-start justify-between gap-2">
                    <div className="min-w-0">
                      <p className="font-mono text-base font-semibold text-slate-900">{l.contractNumber}</p>
                      <p className="truncate text-sm text-slate-600">{l.lesseeName}</p>
                    </div>
                    <PaymentBadge status={l.paymentStatus} />
                  </div>
                  <div className="mt-3 grid grid-cols-3 gap-2 rounded-lg bg-slate-50 p-2.5 text-center">
                    <Metric label="Ед." value={`${l.metrics.activeUnits}`} />
                    <Metric label="Per Diem" value={formatUsd(l.dailyRateUsd, 2)} />
                    <Metric label="За месяц" value={formatUsd(Math.round(l.metrics.accruedThisMonthUsd))} />
                  </div>
                  <div className="mt-3 flex flex-wrap items-center gap-1.5 text-xs text-slate-500">
                    <span className="font-mono">до {formatDate(l.endDate)}</span>
                    <LeaseExpiryBadge level={l.metrics.expiryLevel} daysToEnd={l.metrics.daysToEnd} />
                    <span className="ml-auto">Возврат: {l.allowedReturnLocodes.map(locodeCity).join(", ")}</span>
                  </div>
                </Link>
              </li>
            ))}
          </ul>
        </>
      )}

      <Sheet open={newOpen} onClose={() => setNewOpen(false)} title="Новый договор аренды" description="Long-Term Lease: пакет контейнеров по суточной ставке Per Diem" size="lg">
        <NewLeaseForm containers={issuable} onDone={() => setNewOpen(false)} />
      </Sheet>
    </>
  );
}

function Tile({ label, value, sub, accent = false }: { label: string; value: string; sub: string; accent?: boolean }) {
  return (
    <div className={cn("rounded-xl border p-3 shadow-sm sm:p-4", accent ? "border-emerald-200 bg-emerald-50" : "border-slate-200 bg-white")}>
      <p className="text-xs text-slate-500">{label}</p>
      <p className={cn("mt-1 font-mono text-xl font-semibold tabular sm:text-2xl", accent ? "text-emerald-700" : "text-slate-900")}>{value}</p>
      <p className="mt-0.5 text-[11px] text-slate-400">{sub}</p>
    </div>
  );
}

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <p className="text-[11px] text-slate-500">{label}</p>
      <p className="font-mono text-sm font-semibold text-slate-900">{value}</p>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useState } from "react";
import { BadgeDollarSign, CalendarPlus, Calculator, PackageCheck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, Field, Input, Select } from "@/components/ui/primitives";
import { Sheet } from "@/components/ui/sheet";
import { BicCode, TechStatusBadge } from "@/components/status-badges";
import { ExtendLeaseForm, OffHireForm, PaymentStatusForm } from "./lease-forms";
import { rentalDaysInRange } from "@/lib/domain/lease";
import { addDays, parseDateInput, startOfMonthUtc, toDateInput } from "@/lib/dates";
import { formatDate, formatUsd } from "@/lib/format";
import type { LeaseRow } from "@/lib/queries/operations";

export function LeaseActions({ lease }: { lease: LeaseRow }) {
  const [sheet, setSheet] = useState<"extend" | "offhire" | "payment" | null>(null);
  const close = () => setSheet(null);
  const isActive = lease.status === "ACTIVE";

  return (
    <>
      <div className="grid grid-cols-3 gap-2 sm:flex">
        <Button variant="outline" onClick={() => setSheet("payment")}>
          <BadgeDollarSign /> <span className="truncate">Оплата</span>
        </Button>
        <Button variant="outline" onClick={() => setSheet("extend")} disabled={!isActive}>
          <CalendarPlus /> <span className="truncate">Продлить</span>
        </Button>
        <Button onClick={() => setSheet("offhire")} disabled={!isActive || lease.metrics.activeUnits === 0}>
          <PackageCheck /> <span className="truncate">Off-Hire</span>
        </Button>
      </div>
      <Sheet open={sheet === "extend"} onClose={close} title={`Продление ${lease.contractNumber}`}>
        <ExtendLeaseForm lease={lease} onDone={close} />
      </Sheet>
      <Sheet open={sheet === "offhire"} onClose={close} title="Возврат из аренды (Off-Hire)" description={lease.lesseeName}>
        <OffHireForm lease={lease} onDone={close} />
      </Sheet>
      <Sheet open={sheet === "payment"} onClose={close} title="Статус оплаты текущего месяца" description={lease.contractNumber}>
        <PaymentStatusForm lease={lease} onDone={close} />
      </Sheet>
    </>
  );
}

type Period = "month" | "term" | "custom";

/** Калькулятор начислений: дни аренды × Per Diem по каждой единице за выбранный период. */
export function LeaseCalculator({ lease }: { lease: LeaseRow }) {
  const today = new Date();
  const [period, setPeriod] = useState<Period>("month");
  const [from, setFrom] = useState(toDateInput(startOfMonthUtc(today)));
  const [to, setTo] = useState(toDateInput(today));

  const range = (() => {
    if (period === "month") return { start: startOfMonthUtc(today), end: today };
    if (period === "term") return { start: new Date(lease.startDate), end: today };
    return { start: parseDateInput(from) ?? today, end: parseDateInput(to) ?? today };
  })();

  const rows = lease.items.map((item) => {
    const days = rentalDaysInRange({ onHireDate: new Date(item.onHireDate), offHireDate: item.offHireDate ? new Date(item.offHireDate) : null }, range.start, range.end);
    return { ...item, days, amount: days * lease.dailyRateUsd };
  });
  const totalDays = rows.reduce((s, r) => s + r.days, 0);
  const total = rows.reduce((s, r) => s + r.amount, 0);
  const forecastToEnd = lease.status === "ACTIVE" ? Math.max(0, Math.round((new Date(lease.endDate).getTime() - today.getTime()) / 86_400_000)) * lease.metrics.activeUnits * lease.dailyRateUsd : 0;

  return (
    <Card>
      <CardHeader icon={<Calculator />} title="Калькулятор начислений" description="Дни аренды × ставка × единицы (день Off-Hire не тарифицируется)" />
      <CardContent className="space-y-4">
        <div className="grid gap-3 sm:grid-cols-3">
          <Field label="Период" htmlFor="calc-period">
            <Select id="calc-period" value={period} onChange={(e) => setPeriod(e.target.value as Period)}>
              <option value="month">Текущий месяц</option>
              <option value="term">Весь срок договора</option>
              <option value="custom">Произвольный период</option>
            </Select>
          </Field>
          {period === "custom" && (
            <>
              <Field label="С" htmlFor="calc-from">
                <Input id="calc-from" type="date" value={from} onChange={(e) => setFrom(e.target.value)} />
              </Field>
              <Field label="По" htmlFor="calc-to">
                <Input id="calc-to" type="date" value={to} max={toDateInput(addDays(today, 3650))} onChange={(e) => setTo(e.target.value)} />
              </Field>
            </>
          )}
        </div>

        <div className="overflow-hidden rounded-lg border border-slate-200">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-left text-xs text-slate-500">
              <tr>
                <th className="px-3 py-2 font-medium">Контейнер</th>
                <th className="hidden px-3 py-2 font-medium sm:table-cell">On-Hire / Off-Hire</th>
                <th className="px-3 py-2 text-right font-medium">Дней</th>
                <th className="px-3 py-2 text-right font-medium">Сумма</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {rows.map((r) => (
                <tr key={r.id}>
                  <td className="px-3 py-2.5">
                    <Link href={`/containers/${r.containerId}`} className="hover:underline"><BicCode code={r.bicCode} size="sm" /></Link>
                    <div className="mt-0.5 flex items-center gap-1.5 sm:hidden">
                      <span className="font-mono text-[11px] text-slate-400">{formatDate(r.onHireDate)} — {r.offHireDate ? formatDate(r.offHireDate) : "н.в."}</span>
                    </div>
                  </td>
                  <td className="hidden px-3 py-2.5 sm:table-cell">
                    <span className="font-mono text-xs text-slate-600">{formatDate(r.onHireDate)} — {r.offHireDate ? formatDate(r.offHireDate) : "на руках"}</span>
                    {r.techStatus !== "SOUND" && <span className="ml-2"><TechStatusBadge status={r.techStatus} /></span>}
                  </td>
                  <td className="px-3 py-2.5 text-right font-mono">{r.days}</td>
                  <td className="px-3 py-2.5 text-right font-mono">{formatUsd(r.amount, 2)}</td>
                </tr>
              ))}
            </tbody>
            <tfoot className="bg-slate-900 text-white">
              <tr>
                <td className="px-3 py-3 font-medium">Итого · {formatUsd(lease.dailyRateUsd, 2)}/сут.</td>
                <td className="hidden sm:table-cell" />
                <td className="px-3 py-3 text-right font-mono">{totalDays}</td>
                <td className="px-3 py-3 text-right font-mono text-lg font-semibold">{formatUsd(total, 2)}</td>
              </tr>
            </tfoot>
          </table>
        </div>
        {forecastToEnd > 0 && (
          <p className="text-xs text-slate-500">
            Прогноз до планового Off-Hire ({formatDate(lease.endDate)}): <b className="font-mono text-slate-800">{formatUsd(Math.round(forecastToEnd))}</b> при текущих {lease.metrics.activeUnits} ед.
          </p>
        )}
      </CardContent>
    </Card>
  );
}

import type { Metadata } from "next";
import { PageHeader } from "@/components/ui/primitives";
import { LeaseList } from "@/components/leases/lease-list";
import { getLeaseRows } from "@/lib/queries/operations";
import { getIssuableContainers } from "@/lib/queries/containers";

export const metadata: Metadata = { title: "Долгосрочная аренда" };

export default async function LeasesPage() {
  const [leases, issuable] = await Promise.all([getLeaseRows(new Date()), getIssuableContainers()]);
  return (
    <>
      <PageHeader title="Долгосрочная аренда" description="Long-Term Lease: договоры, начисления Per Diem, контроль сроков и оплаты." />
      <LeaseList leases={leases} issuable={issuable} />
    </>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { ArrowLeft, Building2, ClipboardCheck, Repeat } from "lucide-react";
import { Badge, Card, CardContent, CardHeader, DataList } from "@/components/ui/primitives";
import { LeaseExpiryBadge, PaymentBadge } from "@/components/status-badges";
import { LeaseActions, LeaseCalculator } from "@/components/leases/lease-detail-client";
import { getLeaseRow } from "@/lib/queries/operations";
import { SURVEY_STATUS_LABELS, locodeCity } from "@/lib/domain/constants";
import { formatDate, formatUsd } from "@/lib/format";
import { cn } from "@/lib/utils";

type Params = Promise<{ id: string }>;

export async function generateMetadata({ params }: { params: Params }): Promise<Metadata> {
  const { id } = await params;
  const lease = await getLeaseRow(id, new Date());
  return { title: lease ? `Договор ${lease.contractNumber}` : "Договор не найден" };
}

export default async function LeaseDetailPage({ params }: { params: Params }) {
  const { id } = await params;
  const lease = await getLeaseRow(id, new Date());
  if (!lease) notFound();
  const { metrics } = lease;

  return (
    <>
      <Link href="/leases" className="mb-4 inline-flex items-center gap-1.5 text-sm text-slate-500 hover:text-slate-900">
        <ArrowLeft className="size-4" /> Долгосрочная аренда
      </Link>

      <Card className="relative mb-4 overflow-hidden lg:mb-6">
        <div className={cn("absolute inset-y-0 left-0 w-1.5", lease.status === "ACTIVE" ? "bg-violet-600" : "bg-slate-300")} aria-hidden />
        <div className="flex flex-col gap-4 p-5 pl-6 lg:flex-row lg:items-center lg:justify-between">
          <div className="min-w-0">
            <p className="font-mono text-xs tracking-widest text-slate-400 uppercase">Long-Term Lease · Per Diem</p>
            <h1 className="mt-1 font-mono text-2xl font-semibold text-slate-900 sm:text-3xl">{lease.contractNumber}</h1>
            <p className="mt-0.5 text-slate-600">{lease.lesseeName}</p>
            <div className="mt-3 flex flex-wrap gap-1.5">
              {lease.status === "ACTIVE" ? <Badge tone="violet" dot>Действует</Badge> : <Badge tone="slate">Закрыт</Badge>}
              <PaymentBadge status={lease.paymentStatus} />
              <LeaseExpiryBadge level={metrics.expiryLevel} daysToEnd={metrics.daysToEnd} />
              {lease.autoRenewal && <Badge tone="indigo"><Repeat /> Автопролонгация</Badge>}
            </div>
          </div>
          <LeaseActions lease={lease} />
        </div>
        <div className="grid grid-cols-2 border-t border-slate-100 sm:grid-cols-4">
          <Stat label="Единиц на руках" value={`${metrics.activeUnits} / ${metrics.totalUnits}`} />
          <Stat label="Per Diem" value={`${formatUsd(lease.dailyRateUsd, 2)}/сут.`} />
          <Stat label="Начислено за месяц" value={formatUsd(Math.round(metrics.accruedThisMonthUsd))} />
          <Stat label="Начислено за срок" value={formatUsd(Math.round(metrics.accruedTotalUsd))} strong />
        </div>
      </Card>

      <div className="grid gap-4 lg:gap-6 xl:grid-cols-[1fr_1.4fr]">
        <div className="space-y-4 lg:space-y-6">
          <Card>
            <CardHeader icon={<Building2 />} title="Условия договора" />
            <CardContent>
              <DataList
                items={[
                  { label: "Арендатор", value: lease.lesseeName, full: true },
                  { label: "ИНН", value: lease.lesseeInn ?? "—", mono: true },
                  { label: "Контактное лицо", value: lease.contactPerson },
                  { label: "Телефон", value: lease.contactPhone ?? "—" },
                  { label: "Email", value: lease.contactEmail ?? "—" },
                  { label: "On-Hire", value: formatDate(lease.startDate), mono: true },
                  { label: "Плановый Off-Hire", value: formatDate(lease.endDate), mono: true },
                  { label: "Валюта", value: lease.currency },
                  { label: "Депозит", value: formatUsd(lease.depositUsd), mono: true },
                  { label: "Доход в месяц (run-rate)", value: formatUsd(Math.round(metrics.monthlyRunRateUsd)), mono: true },
                  { label: "Разрешённые регионы возврата", value: lease.allowedReturnLocodes.map((c) => `${c} · ${locodeCity(c)}`).join(", "), full: true },
                ]}
              />
            </CardContent>
          </Card>
          <Card>
            <CardHeader icon={<ClipboardCheck />} title="Акты осмотра" />
            <CardContent>
              <DataList
                items={[
                  { label: "On-Hire Survey", value: SURVEY_STATUS_LABELS[lease.onHireSurvey] ?? lease.onHireSurvey },
                  { label: "Off-Hire Survey", value: SURVEY_STATUS_LABELS[lease.offHireSurvey] ?? lease.offHireSurvey },
                ]}
              />
            </CardContent>
          </Card>
          {lease.notes && (
            <Card className="border-amber-200 bg-amber-50/50">
              <CardContent className="text-sm text-slate-700">{lease.notes}</CardContent>
            </Card>
          )}
        </div>
        <LeaseCalculator lease={lease} />
      </div>
    </>
  );
}

function Stat({ label, value, strong = false }: { label: string; value: string; strong?: boolean }) {
  return (
    <div className="border-slate-100 px-5 py-3 odd:border-r sm:border-r sm:last:border-r-0">
      <p className="text-xs text-slate-500">{label}</p>
      <p className={cn("font-mono text-base font-semibold tabular", strong ? "text-violet-700" : "text-slate-900")}>{value}</p>
    </div>
  );
}

toolUseResult.content:
"use client";

import Link from "next/link";
import { useMemo, useState } from "react";
import { ChevronRight, FileText, Plus, Repeat, Search } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, EmptyState, Input } from "@/components/ui/primitives";
import { Sheet } from "@/components/ui/sheet";
import { LeaseExpiryBadge, PaymentBadge } from "@/components/status-badges";
import { NewLeaseForm } from "./lease-forms";
import { formatDate, formatUsd } from "@/lib/format";
import { locodeCity } from "@/lib/domain/constants";
import { cn } from "@/lib/utils";
import type { LeaseRow } from "@/lib/queries/operations";
import type { IssuableContainer } from "@/lib/queries/containers";

type Tab = "active" | "attention" | "expiring" | "debt" | "completed";

const TABS: { id: Tab; label: string }[] = [
  { id: "active", label: "Действующие" },
  { id: "attention", label: "Требуют внимания" },
  { id: "expiring", label: "Истекают ≤ 30 дн." },
  { id: "debt", label: "Задолженность" },
  { id: "completed", label: "Закрытые" },
];

function inTab(l: LeaseRow, tab: Tab): boolean {
  const active = l.status === "ACTIVE";
  switch (tab) {
    case "active":
      return active;
    case "attention":
      return active && l.metrics.needsAttention;
    case "expiring":
      return active && ["CRITICAL", "WARNING", "EXPIRED"].includes(l.metrics.expiryLevel);
    case "debt":
      return active && l.paymentStatus === "OVERDUE";
    case "completed":
      return !active;
  }
}

export function LeaseList({ leases, issuable }: { leases: LeaseRow[]; issuable: IssuableContainer[] }) {
  const [tab, setTab] = useState<Tab>("active");
  const [q, setQ] = useState("");
  const [newOpen, setNewOpen] = useState(false);

  const active = leases.filter((l) => l.status === "ACTIVE");
  const totals = {
    units: active.reduce((s, l) => s + l.metrics.activeUnits, 0),
    monthly: active.reduce((s, l) => s + l.metrics.monthlyRunRateUsd, 0),
    accruedMonth: active.reduce((s, l) => s + l.metrics.accruedThisMonthUsd, 0),
    accruedTotal: leases.reduce((s, l) => s + l.metrics.accruedTotalUsd, 0),
  };

  const visible = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return leases.filter((l) => inTab(l, tab)).filter((l) => !needle || l.contractNumber.toLowerCase().includes(needle) || l.lesseeName.toLowerCase().includes(needle));
  }, [leases, tab, q]);

  return (
    <>
      <div className="mb-4 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <Tile label="Единиц в аренде" value={String(totals.units)} sub={`${active.length} действующих договоров`} />
        <Tile label="Доход в месяц (run-rate)" value={formatUsd(Math.round(totals.monthly))} sub="единицы × Per Diem × дни месяца" accent />
        <Tile label="Начислено в этом месяце" value={formatUsd(Math.round(totals.accruedMonth))} sub="с 1-го числа по сегодня" />
        <Tile label="Начислено за всё время" value={formatUsd(Math.round(totals.accruedTotal))} sub="по всем договорам" />
      </div>

      <div className="mb-4 flex flex-col gap-3 2xl:flex-row 2xl:items-center 2xl:justify-between">
        <div className="scrollbar-thin -mx-4 flex gap-1 overflow-x-auto px-4 pb-1 sm:mx-0 sm:px-0" role="tablist">
          {TABS.map((t) => {
            const count = leases.filter((l) => inTab(l, t.id)).length;
            return (
              <button
                key={t.id}
                role="tab"
                aria-selected={tab === t.id}
                onClick={() => setTab(t.id)}
                className={cn("flex shrink-0 items-center gap-1.5 rounded-lg px-3 py-2 text-sm font-medium", tab === t.id ? "bg-slate-900 text-white" : "bg-white text-slate-600 ring-1 ring-slate-200 hover:bg-slate-50")}
              >
                {t.label}
                <span className={cn("rounded px-1.5 font-mono text-xs", tab === t.id ? "bg-white/20" : "bg-slate-100")}>{count}</span>
              </button>
            );
          })}
        </div>
        <div className="flex gap-2">
          <div className="relative flex-1 2xl:w-72">
            <Search className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-slate-400" aria-hidden />
            <Input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Договор или арендатор" className="pl-9" aria-label="Поиск договора" />
          </div>
          <Button className="h-11 lg:h-10" onClick={() => setNewOpen(true)}>
            <Plus /> <span className="hidden sm:inline">Новый договор</span>
          </Button>
        </div>
      </div>

      {visible.length === 0 ? (
        <Card>
          <EmptyState icon={<FileText />} title="Договоров нет" description="В этой категории нет договоров аренды." />
        </Card>
      ) : (
        <>
          <Card className="hidden overflow-hidden xl:block">
            <table className="w-full text-sm">
              <thead className="bg-slate-50 text-left text-xs text-slate-500">
                <tr>
                  <th className="px-4 py-2.5 font-medium">Договор / арендатор</th>
                  <th className="px-3 py-2.5 font-medium">Срок</th>
                  <th className="px-3 py-2.5 text-right font-medium">Ед.</th>
                  <th className="px-3 py-2.5 text-right font-medium">Per Diem</th>
                  <th className="px-3 py-2.5 text-right font-medium">За месяц</th>
                  <th className="px-3 py-2.5 text-right font-medium">За весь срок</th>
                  <th className="px-3 py-2.5 font-medium">Оплата</th>
                  <th className="w-8" />
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {visible.map((l) => (
                  <tr key={l.id} className="group hover:bg-slate-50/80">
                    <td className="px-4 py-3">
                      <Link href={`/leases/${l.id}`} className="block">
                        <span className="font-mono font-semibold text-slate-900 group-hover:text-indigo-700">{l.contractNumber}</span>
                        {l.autoRenewal && <Repeat className="ml-1.5 inline size-3.5 text-indigo-500" aria-label="Автопролонгация" />}
                        <p className="text-slate-600">{l.lesseeName}</p>
                      </Link>
                    </td>
                    <td className="px-3 py-3">
                      <p className="font-mono text-xs text-slate-600">{formatDate(l.startDate)} — {formatDate(l.endDate)}</p>
                      <div className="mt-1"><LeaseExpiryBadge level={l.metrics.expiryLevel} daysToEnd={l.metrics.daysToEnd} /></div>
                    </td>
                    <td className="px-3 py-3 text-right font-mono">{l.metrics.activeUnits}<span className="text-slate-400">/{l.metrics.totalUnits}</span></td>
                    <td className="px-3 py-3 text-right font-mono">{formatUsd(l.dailyRateUsd, 2)}</td>
                    <td className="px-3 py-3 text-right font-mono">{formatUsd(Math.round(l.metrics.accruedThisMonthUsd))}</td>
                    <td className="px-3 py-3 text-right font-mono font-semibold">{formatUsd(Math.round(l.metrics.accruedTotalUsd))}</td>
                    <td className="px-3 py-3"><PaymentBadge status={l.paymentStatus} /></td>
                    <td className="pr-3">
                      <Link href={`/leases/${l.id}`} aria-label={`Открыть ${l.contractNumber}`} className="text-slate-300 group-hover:text-slate-500"><ChevronRight className="size-4" /></Link>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </Card>

          <ul className="grid gap-3 md:grid-cols-2 xl:hidden">
            {visible.map((l) => (
              <li key={l.id}>
                <Link href={`/leases/${l.id}`} className={cn("block rounded-xl border bg-white p-4 shadow-sm active:scale-[0.99]", l.metrics.needsAttention ? "border-amber-300" : "border-slate-200")}>
                  <div className="flex items-start justify-between gap-2">
                    <div className="min-w-0">
                      <p className="font-mono text-base font-semibold text-slate-900">{l.contractNumber}</p>
                      <p className="truncate text-sm text-slate-600">{l.lesseeName}</p>
                    </div>
                    <PaymentBadge status={l.paymentStatus} />
                  </div>
                  <div className="mt-3 grid grid-cols-3 gap-2 rounded-lg bg-slate-50 p-2.5 text-center">
                    <Metric label="Ед." value={`${l.metrics.activeUnits}`} />
                    <Metric label="Per Diem" value={formatUsd(l.dailyRateUsd, 2)} />
                    <Metric label="За месяц" value={formatUsd(Math.round(l.metrics.accruedThisMonthUsd))} />
                  </div>
                  <div className="mt-3 flex flex-wrap items-center gap-1.5 text-xs text-slate-500">
                    <span className="font-mono">до {formatDate(l.endDate)}</span>
                    <LeaseExpiryBadge level={l.metrics.expiryLevel} daysToEnd={l.metrics.daysToEnd} />
                    <span className="ml-auto">Возврат: {l.allowedReturnLocodes.map(locodeCity).join(", ")}</span>
                  </div>
                </Link>
              </li>
            ))}
          </ul>
        </>
      )}

      <Sheet open={newOpen} onClose={() => setNewOpen(false)} title="Новый договор аренды" description="Long-Term Lease: пакет контейнеров по суточной ставке Per Diem" size="lg">
        <NewLeaseForm containers={issuable} onDone={() => setNewOpen(false)} />
      </Sheet>
    </>
  );
}

function Tile({ label, value, sub, accent = false }: { label: string; value: string; sub: string; accent?: boolean }) {
  return (
    <div className={cn("rounded-xl border p-3 shadow-sm sm:p-4", accent ? "border-emerald-200 bg-emerald-50" : "border-slate-200 bg-white")}>
      <p className="text-xs text-slate-500">{label}</p>
      <p className={cn("mt-1 font-mono text-xl font-semibold tabular sm:text-2xl", accent ? "text-emerald-700" : "text-slate-900")}>{value}</p>
      <p className="mt-0.5 text-[11px] text-slate-400">{sub}</p>
    </div>
  );
}

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <p className="text-[11px] text-slate-500">{label}</p>
      <p className="font-mono text-sm font-semibold text-slate-900">{value}</p>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useState } from "react";
import { BadgeDollarSign, CalendarPlus, Calculator, PackageCheck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, Field, Input, Select } from "@/components/ui/primitives";
import { Sheet } from "@/components/ui/sheet";
import { BicCode, TechStatusBadge } from "@/components/status-badges";
import { ExtendLeaseForm, OffHireForm, PaymentStatusForm } from "./lease-forms";
import { rentalDaysInRange } from "@/lib/domain/lease";
import { addDays, parseDateInput, startOfMonthUtc, toDateInput } from "@/lib/dates";
import { formatDate, formatUsd } from "@/lib/format";
import type { LeaseRow } from "@/lib/queries/operations";

export function LeaseActions({ lease }: { lease: LeaseRow }) {
  const [sheet, setSheet] = useState<"extend" | "offhire" | "payment" | null>(null);
  const close = () => setSheet(null);
  const isActive = lease.status === "ACTIVE";

  return (
    <>
      <div className="grid grid-cols-3 gap-2 sm:flex">
        <Button variant="outline" onClick={() => setSheet("payment")}>
          <BadgeDollarSign /> <span className="truncate">Оплата</span>
        </Button>
        <Button variant="outline" onClick={() => setSheet("extend")} disabled={!isActive}>
          <CalendarPlus /> <span className="truncate">Продлить</span>
        </Button>
        <Button onClick={() => setSheet("offhire")} disabled={!isActive || lease.metrics.activeUnits === 0}>
          <PackageCheck /> <span className="truncate">Off-Hire</span>
        </Button>
      </div>
      <Sheet open={sheet === "extend"} onClose={close} title={`Продление ${lease.contractNumber}`}>
        <ExtendLeaseForm lease={lease} onDone={close} />
      </Sheet>
      <Sheet open={sheet === "offhire"} onClose={close} title="Возврат из аренды (Off-Hire)" description={lease.lesseeName}>
        <OffHireForm lease={lease} onDone={close} />
      </Sheet>
      <Sheet open={sheet === "payment"} onClose={close} title="Статус оплаты текущего месяца" description={lease.contractNumber}>
        <PaymentStatusForm lease={lease} onDone={close} />
      </Sheet>
    </>
  );
}

type Period = "month" | "term" | "custom";

/** Калькулятор начислений: дни аренды × Per Diem по каждой единице за выбранный период. */
export function LeaseCalculator({ lease }: { lease: LeaseRow }) {
  const today = new Date();
  const [period, setPeriod] = useState<Period>("month");
  const [from, setFrom] = useState(toDateInput(startOfMonthUtc(today)));
  const [to, setTo] = useState(toDateInput(today));

  const range = (() => {
    if (period === "month") return { start: startOfMonthUtc(today), end: today };
    if (period === "term") return { start: new Date(lease.startDate), end: today };
    return { start: parseDateInput(from) ?? today, end: parseDateInput(to) ?? today };
  })();

  const rows = lease.items.map((item) => {
    const days = rentalDaysInRange({ onHireDate: new Date(item.onHireDate), offHireDate: item.offHireDate ? new Date(item.offHireDate) : null }, range.start, range.end);
    return { ...item, days, amount: days * lease.dailyRateUsd };
  });
  const totalDays = rows.reduce((s, r) => s + r.days, 0);
  const total = rows.reduce((s, r) => s + r.amount, 0);
  const forecastToEnd = lease.status === "ACTIVE" ? Math.max(0, Math.round((new Date(lease.endDate).getTime() - today.getTime()) / 86_400_000)) * lease.metrics.activeUnits * lease.dailyRateUsd : 0;

  return (
    <Card>
      <CardHeader icon={<Calculator />} title="Калькулятор начислений" description="Дни аренды × ставка × единицы (день Off-Hire не тарифицируется)" />
      <CardContent className="space-y-4">
        <div className="grid gap-3 sm:grid-cols-3">
          <Field label="Период" htmlFor="calc-period">
            <Select id="calc-period" value={period} onChange={(e) => setPeriod(e.target.value as Period)}>
              <option value="month">Текущий месяц</option>
              <option value="term">Весь срок договора</option>
              <option value="custom">Произвольный период</option>
            </Select>
          </Field>
          {period === "custom" && (
            <>
              <Field label="С" htmlFor="calc-from">
                <Input id="calc-from" type="date" value={from} onChange={(e) => setFrom(e.target.value)} />
              </Field>
              <Field label="По" htmlFor="calc-to">
                <Input id="calc-to" type="date" value={to} max={toDateInput(addDays(today, 3650))} onChange={(e) => setTo(e.target.value)} />
              </Field>
            </>
          )}
        </div>

        <div className="overflow-hidden rounded-lg border border-slate-200">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-left text-xs text-slate-500">
              <tr>
                <th className="px-3 py-2 font-medium">Контейнер</th>
                <th className="hidden px-3 py-2 font-medium sm:table-cell">On-Hire / Off-Hire</th>
                <th className="px-3 py-2 text-right font-medium">Дней</th>
                <th className="px-3 py-2 text-right font-medium">Сумма</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {rows.map((r) => (
                <tr key={r.id}>
                  <td className="px-3 py-2.5">
                    <Link href={`/containers/${r.containerId}`} className="hover:underline"><BicCode code={r.bicCode} size="sm" /></Link>
                    <div className="mt-0.5 flex items-center gap-1.5 sm:hidden">
                      <span className="font-mono text-[11px] text-slate-400">{formatDate(r.onHireDate)} — {r.offHireDate ? formatDate(r.offHireDate) : "н.в."}</span>
                    </div>
                  </td>
                  <td className="hidden px-3 py-2.5 sm:table-cell">
                    <span className="font-mono text-xs text-slate-600">{formatDate(r.onHireDate)} — {r.offHireDate ? formatDate(r.offHireDate) : "на руках"}</span>
                    {r.techStatus !== "SOUND" && <span className="ml-2"><TechStatusBadge status={r.techStatus} /></span>}
                  </td>
                  <td className="px-3 py-2.5 text-right font-mono">{r.days}</td>
                  <td className="px-3 py-2.5 text-right font-mono">{formatUsd(r.amount, 2)}</td>
                </tr>
              ))}
            </tbody>
            <tfoot className="bg-slate-900 text-white">
              <tr>
                <td className="px-3 py-3 font-medium">Итого · {formatUsd(lease.dailyRateUsd, 2)}/сут.</td>
                <td className="hidden sm:table-cell" />
                <td className="px-3 py-3 text-right font-mono">{totalDays}</td>
                <td className="px-3 py-3 text-right font-mono text-lg font-semibold">{formatUsd(total, 2)}</td>
              </tr>
            </tfoot>
          </table>
        </div>
        {forecastToEnd > 0 && (
          <p className="text-xs text-slate-500">
            Прогноз до планового Off-Hire ({formatDate(lease.endDate)}): <b className="font-mono text-slate-800">{formatUsd(Math.round(forecastToEnd))}</b> при текущих {lease.metrics.activeUnits} ед.
          </p>
        )}
      </CardContent>
    </Card>
  );
}

import type { Metadata } from "next";
import { PageHeader } from "@/components/ui/primitives";
import { LeaseList } from "@/components/leases/lease-list";
import { getLeaseRows } from "@/lib/queries/operations";
import { getIssuableContainers } from "@/lib/queries/containers";

export const metadata: Metadata = { title: "Долгосрочная аренда" };

export default async function LeasesPage() {
  const [leases, issuable] = await Promise.all([getLeaseRows(new Date()), getIssuableContainers()]);
  return (
    <>
      <PageHeader title="Долгосрочная аренда" description="Long-Term Lease: договоры, начисления Per Diem, контроль сроков и оплаты." />
      <LeaseList leases={leases} issuable={issuable} />
    </>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { ArrowLeft, Building2, ClipboardCheck, Repeat } from "lucide-react";
import { Badge, Card, CardContent, CardHeader, DataList } from "@/components/ui/primitives";
import { LeaseExpiryBadge, PaymentBadge } from "@/components/status-badges";
import { LeaseActions, LeaseCalculator } from "@/components/leases/lease-detail-client";
import { getLeaseRow } from "@/lib/queries/operations";
import { SURVEY_STATUS_LABELS, locodeCity } from "@/lib/domain/constants";
import { formatDate, formatUsd } from "@/lib/format";
import { cn } from "@/lib/utils";

type Params = Promise<{ id: string }>;

export async function generateMetadata({ params }: { params: Params }): Promise<Metadata> {
  const { id } = await params;
  const lease = await getLeaseRow(id, new Date());
  return { title: lease ? `Договор ${lease.contractNumber}` : "Договор не найден" };
}

export default async function LeaseDetailPage({ params }: { params: Params }) {
  const { id } = await params;
  const lease = await getLeaseRow(id, new Date());
  if (!lease) notFound();
  const { metrics } = lease;

  return (
    <>
      <Link href="/leases" className="mb-4 inline-flex items-center gap-1.5 text-sm text-slate-500 hover:text-slate-900">
        <ArrowLeft className="size-4" /> Долгосрочная аренда
      </Link>

      <Card className="relative mb-4 overflow-hidden lg:mb-6">
        <div className={cn("absolute inset-y-0 left-0 w-1.5", lease.status === "ACTIVE" ? "bg-violet-600" : "bg-slate-300")} aria-hidden />
        <div className="flex flex-col gap-4 p-5 pl-6 lg:flex-row lg:items-center lg:justify-between">
          <div className="min-w-0">
            <p className="font-mono text-xs tracking-widest text-slate-400 uppercase">Long-Term Lease · Per Diem</p>
            <h1 className="mt-1 font-mono text-2xl font-semibold text-slate-900 sm:text-3xl">{lease.contractNumber}</h1>
            <p className="mt-0.5 text-slate-600">{lease.lesseeName}</p>
            <div className="mt-3 flex flex-wrap gap-1.5">
              {lease.status === "ACTIVE" ? <Badge tone="violet" dot>Действует</Badge> : <Badge tone="slate">Закрыт</Badge>}
              <PaymentBadge status={lease.paymentStatus} />
              <LeaseExpiryBadge level={metrics.expiryLevel} daysToEnd={metrics.daysToEnd} />
              {lease.autoRenewal && <Badge tone="indigo"><Repeat /> Автопролонгация</Badge>}
            </div>
          </div>
          <LeaseActions lease={lease} />
        </div>
        <div className="grid grid-cols-2 border-t border-slate-100 sm:grid-cols-4">
          <Stat label="Единиц на руках" value={`${metrics.activeUnits} / ${metrics.totalUnits}`} />
          <Stat label="Per Diem" value={`${formatUsd(lease.dailyRateUsd, 2)}/сут.`} />
          <Stat label="Начислено за месяц" value={formatUsd(Math.round(metrics.accruedThisMonthUsd))} />
          <Stat label="Начислено за срок" value={formatUsd(Math.round(metrics.accruedTotalUsd))} strong />
        </div>
      </Card>

      <div className="grid gap-4 lg:gap-6 xl:grid-cols-[1fr_1.4fr]">
        <div className="space-y-4 lg:space-y-6">
          <Card>
            <CardHeader icon={<Building2 />} title="Условия договора" />
            <CardContent>
              <DataList
                items={[
                  { label: "Арендатор", value: lease.lesseeName, full: true },
                  { label: "ИНН", value: lease.lesseeInn ?? "—", mono: true },
                  { label: "Контактное лицо", value: lease.contactPerson },
                  { label: "Телефон", value: lease.contactPhone ?? "—" },
                  { label: "Email", value: lease.contactEmail ?? "—" },
                  { label: "On-Hire", value: formatDate(lease.startDate), mono: true },
                  { label: "Плановый Off-Hire", value: formatDate(lease.endDate), mono: true },
                  { label: "Валюта", value: lease.currency },
                  { label: "Депозит", value: formatUsd(lease.depositUsd), mono: true },
                  { label: "Доход в месяц (run-rate)", value: formatUsd(Math.round(metrics.monthlyRunRateUsd)), mono: true },
                  { label: "Разрешённые регионы возврата", value: lease.allowedReturnLocodes.map((c) => `${c} · ${locodeCity(c)}`).join(", "), full: true },
                ]}
              />
            </CardContent>
          </Card>
          <Card>
            <CardHeader icon={<ClipboardCheck />} title="Акты осмотра" />
            <CardContent>
              <DataList
                items={[
                  { label: "On-Hire Survey", value: SURVEY_STATUS_LABELS[lease.onHireSurvey] ?? lease.onHireSurvey },
                  { label: "Off-Hire Survey", value: SURVEY_STATUS_LABELS[lease.offHireSurvey] ?? lease.offHireSurvey },
                ]}
              />
            </CardContent>
          </Card>
          {lease.notes && (
            <Card className="border-amber-200 bg-amber-50/50">
              <CardContent className="text-sm text-slate-700">{lease.notes}</CardContent>
            </Card>
          )}
        </div>
        <LeaseCalculator lease={lease} />
      </div>
    </>
  );
}

function Stat({ label, value, strong = false }: { label: string; value: string; strong?: boolean }) {
  return (
    <div className="border-slate-100 px-5 py-3 odd:border-r sm:border-r sm:last:border-r-0">
      <p className="text-xs text-slate-500">{label}</p>
      <p className={cn("font-mono text-base font-semibold tabular", strong ? "text-violet-700" : "text-slate-900")}>{value}</p>
    </div>
  );
}

