input.content:
"use client";

import { useState } from "react";
import { ArrowDownToLine, ArrowUpFromLine, ClipboardCheck, ShieldCheck } from "lucide-react";
import { gateInAction, gateOutAction, inspectContainerAction, renewCscAction } from "@/actions/inspector";
import { Button } from "@/components/ui/button";
import { Field, Input, Select, Textarea } from "@/components/ui/primitives";
import { useServerAction } from "@/components/use-server-action";
import { CONDITION_GRADES, CONDITION_GRADE_LABELS, LOCATIONS, TECH_STATUSES, TECH_STATUS_LABELS, terminalsOf, type TechStatus } from "@/lib/domain/constants";
import { addMonths, toDateInput } from "@/lib/dates";
import { cn } from "@/lib/utils";
import type { ContainerRow } from "@/lib/queries/containers";

const TECH_TONES: Record<TechStatus, string> = {
  SOUND: "border-emerald-500 bg-emerald-50 text-emerald-800",
  DAMAGED: "border-rose-500 bg-rose-50 text-rose-800",
  IN_REPAIR: "border-amber-500 bg-amber-50 text-amber-800",
  HOLD: "border-slate-600 bg-slate-100 text-slate-800",
};

export function InspectionForm({ row, presetTech, onDone }: { row: ContainerRow; presetTech?: TechStatus; onDone: () => void }) {
  const [techStatus, setTechStatus] = useState<TechStatus>(presetTech ?? (row.techStatus as TechStatus));
  const [grade, setGrade] = useState(presetTech === "DAMAGED" ? "DAMAGED" : row.conditionGrade);
  const [eorUsd, setEorUsd] = useState(row.eorAmountUsd ? String(row.eorAmountUsd) : "");
  const [comment, setComment] = useState("");
  const { run, isPending, fieldErrors } = useServerAction();
  const needsEor = techStatus === "DAMAGED" || techStatus === "IN_REPAIR";
  const closesRepair = (row.techStatus === "DAMAGED" || row.techStatus === "IN_REPAIR") && techStatus === "SOUND";

  return (
    <form
      className="space-y-5"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => inspectContainerAction(row.id, { techStatus, conditionGrade: grade as (typeof CONDITION_GRADES)[number], eorUsd, comment }), onDone);
      }}
    >
      <fieldset>
        <legend className="mb-2 text-xs font-medium text-slate-700">Технический статус</legend>
        <div className="grid grid-cols-2 gap-2">
          {TECH_STATUSES.map((s) => (
            <label key={s} className={cn("flex h-14 cursor-pointer items-center justify-center rounded-xl border-2 text-sm font-semibold transition", techStatus === s ? TECH_TONES[s] : "border-slate-200 bg-white text-slate-600")}>
              <input
                type="radio"
                className="sr-only"
                checked={techStatus === s}
                onChange={() => {
                  setTechStatus(s);
                  if (s === "DAMAGED") setGrade("DAMAGED");
                  if (s === "SOUND" && grade === "DAMAGED") setGrade("CW");
                }}
              />
              {TECH_STATUS_LABELS[s]}
            </label>
          ))}
        </div>
      </fieldset>
      <Field label="Грейд состояния" htmlFor="in-grade" error={fieldErrors.conditionGrade}>
        <Select id="in-grade" value={grade} onChange={(e) => setGrade(e.target.value)}>
          {CONDITION_GRADES.map((g) => (
            <option key={g} value={g}>{CONDITION_GRADE_LABELS[g]}</option>
          ))}
        </Select>
      </Field>
      {needsEor && (
        <Field label="Оценка ремонта (EOR), $" htmlFor="in-eor" error={fieldErrors.eorUsd}>
          <Input id="in-eor" type="number" inputMode="decimal" min={0} value={eorUsd} onChange={(e) => setEorUsd(e.target.value)} className="h-12 text-lg" />
        </Field>
      )}
      {closesRepair && (
        <p className="rounded-lg bg-emerald-50 px-3 py-2 text-sm text-emerald-800 ring-1 ring-emerald-200">
          Ремонт будет закрыт: EOR {row.eorAmountUsd ? `$${row.eorAmountUsd}` : ""} спишется в затраты на ремонт, контейнер вернётся на сток.
        </p>
      )}
      <Field label="Замечания" htmlFor="in-comment" error={fieldErrors.comment}>
        <Textarea id="in-comment" rows={3} value={comment} onChange={(e) => setComment(e.target.value)} placeholder="Вмятины, пломба, чистота, номер EIR…" />
      </Field>
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <ClipboardCheck /> Сохранить акт осмотра
      </Button>
    </form>
  );
}

export function GateInHereForm({ row, onDone }: { row: ContainerRow; onDone: () => void }) {
  const [locode, setLocode] = useState(row.currentLocode);
  const [terminal, setTerminal] = useState(terminalsOf(row.currentLocode)[0] ?? "");
  const { run, isPending, fieldErrors } = useServerAction();
  return (
    <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); run(() => gateInAction(row.id, { locode, terminal }), onDone); }}>
      <Field label="Город / порт" htmlFor="gin-loc" error={fieldErrors.locode}>
        <Select id="gin-loc" value={locode} onChange={(e) => { setLocode(e.target.value); setTerminal(terminalsOf(e.target.value)[0] ?? ""); }}>
          {LOCATIONS.map((l) => (
            <option key={l.code} value={l.code}>{l.code} · {l.city}</option>
          ))}
        </Select>
      </Field>
      <div className="grid grid-cols-1 gap-2">
        {terminalsOf(locode).map((t) => (
          <button key={t} type="button" onClick={() => setTerminal(t)} className={cn("h-12 rounded-xl border-2 px-4 text-left text-sm font-medium", terminal === t ? "border-indigo-500 bg-indigo-50 text-indigo-800" : "border-slate-200 text-slate-700")}>
            {t}
          </button>
        ))}
      </div>
      <Field label="Или другой терминал" htmlFor="gin-term" error={fieldErrors.terminal}>
        <Input id="gin-term" value={terminal} onChange={(e) => setTerminal(e.target.value)} />
      </Field>
      <Button type="submit" size="lg" variant="success" className="w-full" loading={isPending}>
        <ArrowDownToLine /> Gate-In: принять на терминал
      </Button>
    </form>
  );
}

export function GateOutForm({ row, onDone }: { row: ContainerRow; onDone: () => void }) {
  const [destination, setDestination] = useState(LOCATIONS.find((l) => l.code !== row.currentLocode)?.code ?? "RUMOW");
  const [note, setNote] = useState("");
  const { run, isPending, fieldErrors } = useServerAction();
  return (
    <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); run(() => gateOutAction(row.id, { destinationLocode: destination, note }), onDone); }}>
      <p className="text-sm text-slate-600">Отправка в собственный рейс (гружёный или порожний). Для выдачи контрагенту используйте модуль One-Way.</p>
      <Field label="Пункт назначения" htmlFor="gout-dest" error={fieldErrors.destinationLocode}>
        <Select id="gout-dest" value={destination} onChange={(e) => setDestination(e.target.value)}>
          {LOCATIONS.filter((l) => l.code !== row.currentLocode).map((l) => (
            <option key={l.code} value={l.code}>{l.code} · {l.city}</option>
          ))}
        </Select>
      </Field>
      <Field label="Комментарий" htmlFor="gout-note" error={fieldErrors.note}>
        <Input id="gout-note" value={note} onChange={(e) => setNote(e.target.value)} placeholder="Номер поезда / судна, пломба" />
      </Field>
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <ArrowUpFromLine /> Gate-Out
      </Button>
    </form>
  );
}

export function CscRenewForm({ row, onDone }: { row: ContainerRow; onDone: () => void }) {
  // ACEP: следующее освидетельствование — не позднее чем через 30 месяцев.
  const [date, setDate] = useState(toDateInput(addMonths(new Date(), 30)));
  const { run, isPending, fieldErrors } = useServerAction();
  return (
    <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); run(() => renewCscAction(row.id, { cscPlateExpiry: date }), onDone); }}>
      <p className="text-sm text-slate-600">По программе ACEP следующее освидетельствование — не позднее 30 месяцев с даты осмотра.</p>
      <Field label="Новая дата действия КБК (CSC)" htmlFor="csc-date" error={fieldErrors.cscPlateExpiry}>
        <Input id="csc-date" type="date" value={date} onChange={(e) => setDate(e.target.value)} className="h-12 text-lg" />
      </Field>
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <ShieldCheck /> Продлить КБК
      </Button>
    </form>
  );
}

"use client";

import Link from "next/link";
import { useMemo, useRef, useState } from "react";
import { ArrowDownToLine, ArrowLeft, ArrowUpFromLine, ClipboardCheck, FileText, MapPin, PackageCheck, ScanLine, Search, ShieldCheck, X } from "lucide-react";
import { Card, EmptyState, Input } from "@/components/ui/primitives";
import { Sheet } from "@/components/ui/sheet";
import { BicCode, CscBadge, GradeBadge, OperationalStatusBadge, TechStatusBadge } from "@/components/status-badges";
import { EventTimeline } from "@/components/containers/event-timeline";
import { GateInForm, type GateInTrip } from "@/components/one-way/gate-in-form";
import { CscRenewForm, GateInHereForm, GateOutForm, InspectionForm } from "./inspector-forms";
import { TECH_STATUSES, TECH_STATUS_LABELS, locodeCity, type TechStatus } from "@/lib/domain/constants";
import { normalizeBic } from "@/lib/iso6346";
import { formatDays } from "@/lib/format";
import { cn } from "@/lib/utils";
import type { ContainerRow } from "@/lib/queries/containers";

type ActionSheet = { kind: "inspect"; tech?: TechStatus } | { kind: "gateIn" } | { kind: "gateOut" } | { kind: "csc" } | { kind: "oneWayReturn" };

interface TerminalInspectorProps {
  rows: ContainerRow[];
  tripsByContainer: Record<string, GateInTrip>;
  leaseByContainer: Record<string, { id: string; contractNumber: string }>;
  initialId?: string;
}

const MAX_RESULTS = 8;

export function TerminalInspector({ rows, tripsByContainer, leaseByContainer, initialId }: TerminalInspectorProps) {
  const [q, setQ] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(initialId ?? null);
  const [action, setAction] = useState<ActionSheet | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const results = useMemo(() => {
    const needle = normalizeBic(q);
    if (!needle) return [];
    return rows.filter((r) => r.bicCode.includes(needle)).slice(0, MAX_RESULTS);
  }, [rows, q]);

  const selected = rows.find((r) => r.id === selectedId) ?? null;
  const closeAction = () => setAction(null);

  if (selected) {
    const trip = tripsByContainer[selected.id];
    const lease = leaseByContainer[selected.id];
    const onSite = selected.operationalStatus === "AVAILABLE" || selected.operationalStatus === "MAINTENANCE";

    return (
      <div className="mx-auto max-w-2xl">
        <button type="button" onClick={() => { setSelectedId(null); setTimeout(() => inputRef.current?.focus(), 50); }} className="mb-3 inline-flex h-11 items-center gap-1.5 text-sm font-medium text-slate-600">
          <ArrowLeft className="size-4" /> Другой контейнер
        </button>

        <Card className="overflow-hidden">
          <div className="bg-slate-900 p-5 text-white">
            <p className="font-mono text-xs tracking-widest text-indigo-300 uppercase">{selected.sizeType} · ISO {selected.isoCode}</p>
            <BicCode code={selected.bicCode} size="xl" className="text-white [&>span:last-child]:bg-indigo-500" />
            <p className="mt-2 flex items-center gap-1.5 text-sm text-slate-300">
              <MapPin className="size-4" /> {locodeCity(selected.currentLocode)} · {selected.currentTerminal}
            </p>
          </div>
          <div className="flex flex-wrap gap-1.5 p-4">
            <OperationalStatusBadge status={selected.operationalStatus} />
            <TechStatusBadge status={selected.techStatus} />
            <GradeBadge grade={selected.conditionGrade} full />
            <CscBadge csc={selected.csc} />
            {selected.idleDays !== null && <span className="text-xs text-slate-500">На стоке {formatDays(selected.idleDays)}</span>}
          </div>
        </Card>

        <h2 className="mt-5 mb-2 text-xs font-semibold tracking-wide text-slate-400 uppercase">Быстрая смена тех. статуса</h2>
        <div className="grid grid-cols-4 gap-2">
          {TECH_STATUSES.map((s) => (
            <button
              key={s}
              type="button"
              onClick={() => setAction({ kind: "inspect", tech: s })}
              aria-pressed={selected.techStatus === s}
              className={cn(
                "flex h-16 flex-col items-center justify-center rounded-xl border-2 px-1 text-xs font-semibold leading-tight transition active:scale-95",
                selected.techStatus === s ? "border-slate-900 bg-slate-900 text-white" : "border-slate-200 bg-white text-slate-700",
              )}
            >
              {TECH_STATUS_LABELS[s]}
            </button>
          ))}
        </div>

        <h2 className="mt-5 mb-2 text-xs font-semibold tracking-wide text-slate-400 uppercase">Действия на терминале</h2>
        <div className="grid grid-cols-2 gap-2">
          <BigAction icon={<ClipboardCheck />} label="Акт осмотра" hint="Грейд, повреждения, EOR" onClick={() => setAction({ kind: "inspect" })} tone="indigo" />
          {trip ? (
            <BigAction icon={<PackageCheck />} label="Возврат One-Way" hint={trip.bookingRef} onClick={() => setAction({ kind: "oneWayReturn" })} tone="emerald" />
          ) : lease ? (
            <Link href={`/leases/${lease.id}`} className="contents">
              <BigAction icon={<FileText />} label="Off-Hire" hint={lease.contractNumber} tone="violet" />
            </Link>
          ) : (
            <BigAction icon={<ArrowDownToLine />} label="Gate-In" hint="Принять на терминал" onClick={() => setAction({ kind: "gateIn" })} tone="emerald" />
          )}
          <BigAction
            icon={<ArrowUpFromLine />}
            label="Gate-Out"
            hint={selected.operationalStatus === "AVAILABLE" && selected.techStatus === "SOUND" ? "Собственный рейс" : "Недоступно"}
            onClick={() => setAction({ kind: "gateOut" })}
            disabled={!(selected.operationalStatus === "AVAILABLE" && selected.techStatus === "SOUND")}
            tone="sky"
          />
          <BigAction icon={<ShieldCheck />} label="Продлить КБК" hint="ACEP / CSC" onClick={() => setAction({ kind: "csc" })} tone="teal" />
        </div>
        {!onSite && !trip && !lease && (
          <p className="mt-2 text-xs text-slate-500">Контейнер в пути — после прибытия зафиксируйте Gate-In.</p>
        )}

        <Card className="mt-5 p-4">
          <div className="mb-3 flex items-center justify-between">
            <h2 className="text-sm font-semibold text-slate-900">Последние события</h2>
            <Link href={`/containers/${selected.id}`} className="text-xs font-medium text-indigo-600">Полный профиль →</Link>
          </div>
          <EventTimeline events={selected.recentEvents} compact />
        </Card>

        <Sheet open={action?.kind === "inspect"} onClose={closeAction} title="Акт осмотра" description={<BicCode code={selected.bicCode} size="sm" />}>
          {action?.kind === "inspect" && <InspectionForm key={action.tech ?? "x"} row={selected} presetTech={action.tech} onDone={closeAction} />}
        </Sheet>
        <Sheet open={action?.kind === "gateIn"} onClose={closeAction} title="Gate-In на терминал">
          <GateInHereForm row={selected} onDone={closeAction} />
        </Sheet>
        <Sheet open={action?.kind === "gateOut"} onClose={closeAction} title="Gate-Out">
          <GateOutForm row={selected} onDone={closeAction} />
        </Sheet>
        <Sheet open={action?.kind === "csc"} onClose={closeAction} title="Освидетельствование КБК (CSC)">
          <CscRenewForm row={selected} onDone={closeAction} />
        </Sheet>
        <Sheet open={action?.kind === "oneWayReturn"} onClose={closeAction} title="Возврат по One-Way (Gate-In)" description={trip?.bookingRef}>
          {trip && <GateInForm trip={trip} onDone={closeAction} />}
        </Sheet>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-2xl">
      <div className="relative">
        <Search className="pointer-events-none absolute top-1/2 left-4 size-5 -translate-y-1/2 text-slate-400" aria-hidden />
        <Input
          ref={inputRef}
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Номер или последние цифры"
          className="h-16 rounded-2xl pr-12 pl-12 font-mono text-xl tracking-wide uppercase shadow-md lg:h-16"
          aria-label="Номер контейнера"
          autoFocus
          autoComplete="off"
          inputMode="text"
        />
        {q && (
          <button type="button" onClick={() => setQ("")} className="absolute top-1/2 right-3 -translate-y-1/2 rounded-full p-2 text-slate-400" aria-label="Очистить">
            <X className="size-5" />
          </button>
        )}
      </div>

      {q === "" ? (
        <Card className="mt-4">
          <EmptyState icon={<ScanLine />} title="Найдите контейнер по номеру" description="Достаточно 3–4 последних цифр, например 2918. Пробелы и дефисы можно не вводить." />
        </Card>
      ) : results.length === 0 ? (
        <Card className="mt-4">
          <EmptyState title="Контейнер не найден" description="Проверьте номер или найдите его в реестре." />
        </Card>
      ) : (
        <ul className="mt-4 space-y-2">
          {results.map((r) => (
            <li key={r.id}>
              <button type="button" onClick={() => setSelectedId(r.id)} className="flex min-h-20 w-full items-center gap-3 rounded-2xl border border-slate-200 bg-white p-4 text-left shadow-sm active:scale-[0.99] active:bg-slate-50">
                <div className="min-w-0 flex-1">
                  <BicCode code={r.bicCode} size="lg" />
                  <p className="mt-1 truncate text-sm text-slate-500">{r.sizeType} · {locodeCity(r.currentLocode)} · {r.currentTerminal}</p>
                </div>
                <div className="flex flex-col items-end gap-1">
                  <OperationalStatusBadge status={r.operationalStatus} />
                  {r.techStatus !== "SOUND" && <TechStatusBadge status={r.techStatus} />}
                </div>
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

const ACTION_TONES = {
  indigo: "bg-indigo-50 text-indigo-700",
  emerald: "bg-emerald-50 text-emerald-700",
  sky: "bg-sky-50 text-sky-700",
  teal: "bg-teal-50 text-teal-700",
  violet: "bg-violet-50 text-violet-700",
} as const;

function BigAction({ icon, label, hint, onClick, disabled = false, tone }: { icon: React.ReactNode; label: string; hint: string; onClick?: () => void; disabled?: boolean; tone: keyof typeof ACTION_TONES }) {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      className="flex min-h-24 flex-col items-start justify-between rounded-2xl border border-slate-200 bg-white p-4 text-left shadow-sm transition active:scale-[0.98] disabled:opacity-40"
    >
      <span className={cn("rounded-lg p-2 [&_svg]:size-5", ACTION_TONES[tone])}>{icon}</span>
      <span>
        <span className="block text-sm font-semibold text-slate-900">{label}</span>
        <span className="block truncate text-xs text-slate-500">{hint}</span>
      </span>
    </button>
  );
}

import type { Metadata } from "next";
import { PageHeader } from "@/components/ui/primitives";
import { TerminalInspector } from "@/components/inspector/terminal-inspector";
import type { GateInTrip } from "@/components/one-way/gate-in-form";
import { getContainerRows } from "@/lib/queries/containers";
import { prisma } from "@/lib/prisma";

export const metadata: Metadata = { title: "Терминальный инспектор" };

export default async function InspectorPage({ searchParams }: { searchParams: Promise<{ id?: string }> }) {
  const { id } = await searchParams;
  const now = new Date();
  const [rows, trips, leaseItems] = await Promise.all([
    getContainerRows(now),
    prisma.oneWayTrip.findMany({ where: { status: "ACTIVE" } }),
    prisma.leaseItem.findMany({ where: { offHireDate: null, lease: { status: "ACTIVE" } }, include: { lease: { select: { id: true, contractNumber: true } } } }),
  ]);

  const tripsByContainer: Record<string, GateInTrip> = Object.fromEntries(
    trips.map((t) => [
      t.containerId,
      {
        id: t.id,
        bookingRef: t.bookingRef,
        dropoffLocode: t.dropoffLocode,
        dropoffTerminal: t.dropoffTerminal,
        handoverDate: t.handoverDate,
        deadlineDate: t.deadlineDate,
        freeDays: t.freeDays,
        detentionRatePerDayUsd: t.detentionRatePerDayUsd,
      },
    ]),
  );
  const leaseByContainer = Object.fromEntries(leaseItems.map((i) => [i.containerId, i.lease]));

  return (
    <>
      <div className="mx-auto max-w-2xl">
        <PageHeader title="Терминальный инспектор" description="Поиск по номеру, акт осмотра и смена статуса — одной рукой со смартфона." />
      </div>
      <TerminalInspector rows={rows} tripsByContainer={tripsByContainer} leaseByContainer={leaseByContainer} initialId={id} />
    </>
  );
}

toolUseResult.content:
"use client";

import { useState } from "react";
import { ArrowDownToLine, ArrowUpFromLine, ClipboardCheck, ShieldCheck } from "lucide-react";
import { gateInAction, gateOutAction, inspectContainerAction, renewCscAction } from "@/actions/inspector";
import { Button } from "@/components/ui/button";
import { Field, Input, Select, Textarea } from "@/components/ui/primitives";
import { useServerAction } from "@/components/use-server-action";
import { CONDITION_GRADES, CONDITION_GRADE_LABELS, LOCATIONS, TECH_STATUSES, TECH_STATUS_LABELS, terminalsOf, type TechStatus } from "@/lib/domain/constants";
import { addMonths, toDateInput } from "@/lib/dates";
import { cn } from "@/lib/utils";
import type { ContainerRow } from "@/lib/queries/containers";

const TECH_TONES: Record<TechStatus, string> = {
  SOUND: "border-emerald-500 bg-emerald-50 text-emerald-800",
  DAMAGED: "border-rose-500 bg-rose-50 text-rose-800",
  IN_REPAIR: "border-amber-500 bg-amber-50 text-amber-800",
  HOLD: "border-slate-600 bg-slate-100 text-slate-800",
};

export function InspectionForm({ row, presetTech, onDone }: { row: ContainerRow; presetTech?: TechStatus; onDone: () => void }) {
  const [techStatus, setTechStatus] = useState<TechStatus>(presetTech ?? (row.techStatus as TechStatus));
  const [grade, setGrade] = useState(presetTech === "DAMAGED" ? "DAMAGED" : row.conditionGrade);
  const [eorUsd, setEorUsd] = useState(row.eorAmountUsd ? String(row.eorAmountUsd) : "");
  const [comment, setComment] = useState("");
  const { run, isPending, fieldErrors } = useServerAction();
  const needsEor = techStatus === "DAMAGED" || techStatus === "IN_REPAIR";
  const closesRepair = (row.techStatus === "DAMAGED" || row.techStatus === "IN_REPAIR") && techStatus === "SOUND";

  return (
    <form
      className="space-y-5"
      onSubmit={(e) => {
        e.preventDefault();
        run(() => inspectContainerAction(row.id, { techStatus, conditionGrade: grade as (typeof CONDITION_GRADES)[number], eorUsd, comment }), onDone);
      }}
    >
      <fieldset>
        <legend className="mb-2 text-xs font-medium text-slate-700">Технический статус</legend>
        <div className="grid grid-cols-2 gap-2">
          {TECH_STATUSES.map((s) => (
            <label key={s} className={cn("flex h-14 cursor-pointer items-center justify-center rounded-xl border-2 text-sm font-semibold transition", techStatus === s ? TECH_TONES[s] : "border-slate-200 bg-white text-slate-600")}>
              <input
                type="radio"
                className="sr-only"
                checked={techStatus === s}
                onChange={() => {
                  setTechStatus(s);
                  if (s === "DAMAGED") setGrade("DAMAGED");
                  if (s === "SOUND" && grade === "DAMAGED") setGrade("CW");
                }}
              />
              {TECH_STATUS_LABELS[s]}
            </label>
          ))}
        </div>
      </fieldset>
      <Field label="Грейд состояния" htmlFor="in-grade" error={fieldErrors.conditionGrade}>
        <Select id="in-grade" value={grade} onChange={(e) => setGrade(e.target.value)}>
          {CONDITION_GRADES.map((g) => (
            <option key={g} value={g}>{CONDITION_GRADE_LABELS[g]}</option>
          ))}
        </Select>
      </Field>
      {needsEor && (
        <Field label="Оценка ремонта (EOR), $" htmlFor="in-eor" error={fieldErrors.eorUsd}>
          <Input id="in-eor" type="number" inputMode="decimal" min={0} value={eorUsd} onChange={(e) => setEorUsd(e.target.value)} className="h-12 text-lg" />
        </Field>
      )}
      {closesRepair && (
        <p className="rounded-lg bg-emerald-50 px-3 py-2 text-sm text-emerald-800 ring-1 ring-emerald-200">
          Ремонт будет закрыт: EOR {row.eorAmountUsd ? `$${row.eorAmountUsd}` : ""} спишется в затраты на ремонт, контейнер вернётся на сток.
        </p>
      )}
      <Field label="Замечания" htmlFor="in-comment" error={fieldErrors.comment}>
        <Textarea id="in-comment" rows={3} value={comment} onChange={(e) => setComment(e.target.value)} placeholder="Вмятины, пломба, чистота, номер EIR…" />
      </Field>
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <ClipboardCheck /> Сохранить акт осмотра
      </Button>
    </form>
  );
}

export function GateInHereForm({ row, onDone }: { row: ContainerRow; onDone: () => void }) {
  const [locode, setLocode] = useState(row.currentLocode);
  const [terminal, setTerminal] = useState(terminalsOf(row.currentLocode)[0] ?? "");
  const { run, isPending, fieldErrors } = useServerAction();
  return (
    <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); run(() => gateInAction(row.id, { locode, terminal }), onDone); }}>
      <Field label="Город / порт" htmlFor="gin-loc" error={fieldErrors.locode}>
        <Select id="gin-loc" value={locode} onChange={(e) => { setLocode(e.target.value); setTerminal(terminalsOf(e.target.value)[0] ?? ""); }}>
          {LOCATIONS.map((l) => (
            <option key={l.code} value={l.code}>{l.code} · {l.city}</option>
          ))}
        </Select>
      </Field>
      <div className="grid grid-cols-1 gap-2">
        {terminalsOf(locode).map((t) => (
          <button key={t} type="button" onClick={() => setTerminal(t)} className={cn("h-12 rounded-xl border-2 px-4 text-left text-sm font-medium", terminal === t ? "border-indigo-500 bg-indigo-50 text-indigo-800" : "border-slate-200 text-slate-700")}>
            {t}
          </button>
        ))}
      </div>
      <Field label="Или другой терминал" htmlFor="gin-term" error={fieldErrors.terminal}>
        <Input id="gin-term" value={terminal} onChange={(e) => setTerminal(e.target.value)} />
      </Field>
      <Button type="submit" size="lg" variant="success" className="w-full" loading={isPending}>
        <ArrowDownToLine /> Gate-In: принять на терминал
      </Button>
    </form>
  );
}

export function GateOutForm({ row, onDone }: { row: ContainerRow; onDone: () => void }) {
  const [destination, setDestination] = useState(LOCATIONS.find((l) => l.code !== row.currentLocode)?.code ?? "RUMOW");
  const [note, setNote] = useState("");
  const { run, isPending, fieldErrors } = useServerAction();
  return (
    <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); run(() => gateOutAction(row.id, { destinationLocode: destination, note }), onDone); }}>
      <p className="text-sm text-slate-600">Отправка в собственный рейс (гружёный или порожний). Для выдачи контрагенту используйте модуль One-Way.</p>
      <Field label="Пункт назначения" htmlFor="gout-dest" error={fieldErrors.destinationLocode}>
        <Select id="gout-dest" value={destination} onChange={(e) => setDestination(e.target.value)}>
          {LOCATIONS.filter((l) => l.code !== row.currentLocode).map((l) => (
            <option key={l.code} value={l.code}>{l.code} · {l.city}</option>
          ))}
        </Select>
      </Field>
      <Field label="Комментарий" htmlFor="gout-note" error={fieldErrors.note}>
        <Input id="gout-note" value={note} onChange={(e) => setNote(e.target.value)} placeholder="Номер поезда / судна, пломба" />
      </Field>
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <ArrowUpFromLine /> Gate-Out
      </Button>
    </form>
  );
}

export function CscRenewForm({ row, onDone }: { row: ContainerRow; onDone: () => void }) {
  // ACEP: следующее освидетельствование — не позднее чем через 30 месяцев.
  const [date, setDate] = useState(toDateInput(addMonths(new Date(), 30)));
  const { run, isPending, fieldErrors } = useServerAction();
  return (
    <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); run(() => renewCscAction(row.id, { cscPlateExpiry: date }), onDone); }}>
      <p className="text-sm text-slate-600">По программе ACEP следующее освидетельствование — не позднее 30 месяцев с даты осмотра.</p>
      <Field label="Новая дата действия КБК (CSC)" htmlFor="csc-date" error={fieldErrors.cscPlateExpiry}>
        <Input id="csc-date" type="date" value={date} onChange={(e) => setDate(e.target.value)} className="h-12 text-lg" />
      </Field>
      <Button type="submit" size="lg" className="w-full" loading={isPending}>
        <ShieldCheck /> Продлить КБК
      </Button>
    </form>
  );
}

"use client";

import Link from "next/link";
import { useMemo, useRef, useState } from "react";
import { ArrowDownToLine, ArrowLeft, ArrowUpFromLine, ClipboardCheck, FileText, MapPin, PackageCheck, ScanLine, Search, ShieldCheck, X } from "lucide-react";
import { Card, EmptyState, Input } from "@/components/ui/primitives";
import { Sheet } from "@/components/ui/sheet";
import { BicCode, CscBadge, GradeBadge, OperationalStatusBadge, TechStatusBadge } from "@/components/status-badges";
import { EventTimeline } from "@/components/containers/event-timeline";
import { GateInForm, type GateInTrip } from "@/components/one-way/gate-in-form";
import { CscRenewForm, GateInHereForm, GateOutForm, InspectionForm } from "./inspector-forms";
import { TECH_STATUSES, TECH_STATUS_LABELS, locodeCity, type TechStatus } from "@/lib/domain/constants";
import { normalizeBic } from "@/lib/iso6346";
import { formatDays } from "@/lib/format";
import { cn } from "@/lib/utils";
import type { ContainerRow } from "@/lib/queries/containers";

type ActionSheet = { kind: "inspect"; tech?: TechStatus } | { kind: "gateIn" } | { kind: "gateOut" } | { kind: "csc" } | { kind: "oneWayReturn" };

interface TerminalInspectorProps {
  rows: ContainerRow[];
  tripsByContainer: Record<string, GateInTrip>;
  leaseByContainer: Record<string, { id: string; contractNumber: string }>;
  initialId?: string;
}

const MAX_RESULTS = 8;

export function TerminalInspector({ rows, tripsByContainer, leaseByContainer, initialId }: TerminalInspectorProps) {
  const [q, setQ] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(initialId ?? null);
  const [action, setAction] = useState<ActionSheet | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const results = useMemo(() => {
    const needle = normalizeBic(q);
    if (!needle) return [];
    return rows.filter((r) => r.bicCode.includes(needle)).slice(0, MAX_RESULTS);
  }, [rows, q]);

  const selected = rows.find((r) => r.id === selectedId) ?? null;
  const closeAction = () => setAction(null);

  if (selected) {
    const trip = tripsByContainer[selected.id];
    const lease = leaseByContainer[selected.id];
    const onSite = selected.operationalStatus === "AVAILABLE" || selected.operationalStatus === "MAINTENANCE";

    return (
      <div className="mx-auto max-w-2xl">
        <button type="button" onClick={() => { setSelectedId(null); setTimeout(() => inputRef.current?.focus(), 50); }} className="mb-3 inline-flex h-11 items-center gap-1.5 text-sm font-medium text-slate-600">
          <ArrowLeft className="size-4" /> Другой контейнер
        </button>

        <Card className="overflow-hidden">
          <div className="bg-slate-900 p-5 text-white">
            <p className="font-mono text-xs tracking-widest text-indigo-300 uppercase">{selected.sizeType} · ISO {selected.isoCode}</p>
            <BicCode code={selected.bicCode} size="xl" className="text-white [&>span:last-child]:bg-indigo-500" />
            <p className="mt-2 flex items-center gap-1.5 text-sm text-slate-300">
              <MapPin className="size-4" /> {locodeCity(selected.currentLocode)} · {selected.currentTerminal}
            </p>
          </div>
          <div className="flex flex-wrap gap-1.5 p-4">
            <OperationalStatusBadge status={selected.operationalStatus} />
            <TechStatusBadge status={selected.techStatus} />
            <GradeBadge grade={selected.conditionGrade} full />
            <CscBadge csc={selected.csc} />
            {selected.idleDays !== null && <span className="text-xs text-slate-500">На стоке {formatDays(selected.idleDays)}</span>}
          </div>
        </Card>

        <h2 className="mt-5 mb-2 text-xs font-semibold tracking-wide text-slate-400 uppercase">Быстрая смена тех. статуса</h2>
        <div className="grid grid-cols-4 gap-2">
          {TECH_STATUSES.map((s) => (
            <button
              key={s}
              type="button"
              onClick={() => setAction({ kind: "inspect", tech: s })}
              aria-pressed={selected.techStatus === s}
              className={cn(
                "flex h-16 flex-col items-center justify-center rounded-xl border-2 px-1 text-xs font-semibold leading-tight transition active:scale-95",
                selected.techStatus === s ? "border-slate-900 bg-slate-900 text-white" : "border-slate-200 bg-white text-slate-700",
              )}
            >
              {TECH_STATUS_LABELS[s]}
            </button>
          ))}
        </div>

        <h2 className="mt-5 mb-2 text-xs font-semibold tracking-wide text-slate-400 uppercase">Действия на терминале</h2>
        <div className="grid grid-cols-2 gap-2">
          <BigAction icon={<ClipboardCheck />} label="Акт осмотра" hint="Грейд, повреждения, EOR" onClick={() => setAction({ kind: "inspect" })} tone="indigo" />
          {trip ? (
            <BigAction icon={<PackageCheck />} label="Возврат One-Way" hint={trip.bookingRef} onClick={() => setAction({ kind: "oneWayReturn" })} tone="emerald" />
          ) : lease ? (
            <Link href={`/leases/${lease.id}`} className="contents">
              <BigAction icon={<FileText />} label="Off-Hire" hint={lease.contractNumber} tone="violet" />
            </Link>
          ) : (
            <BigAction icon={<ArrowDownToLine />} label="Gate-In" hint="Принять на терминал" onClick={() => setAction({ kind: "gateIn" })} tone="emerald" />
          )}
          <BigAction
            icon={<ArrowUpFromLine />}
            label="Gate-Out"
            hint={selected.operationalStatus === "AVAILABLE" && selected.techStatus === "SOUND" ? "Собственный рейс" : "Недоступно"}
