("""/** Контейнеры, которые можно выдать (One-Way / аренда): свободны, исправны, КБК действует. */
export async function getIssuableContainers() {
  return prisma.container.findMany({
    where: { operationalStatus: "AVAILABLE", techStatus: "SOUND", cscPlateExpiry: { gte: startOfDayUtc(new Date()) } },
    orderBy: [{ currentLocode: "asc" }, { bicCode: "asc" }],
    select: { id: true, bicCode: true, sizeType: true, currentLocode: true, currentTerminal: true, conditionGrade: true },
  });
}

export type IssuableContainer = Awaited<ReturnType<typeof getIssuableContainers>>[number];""", """export interface IssuableContainer {
  id: string;
  bicCode: string;
  sizeType: string;
  currentLocode: string;
  currentTerminal: string;
  conditionGrade: string;
  /** Причина запрета выдачи; null — контейнер можно выдать. */
  blockReason: string | null;
}

/**
 * Контейнеры на стоке — кандидаты на выдачу (One-Way / аренда).
 * Заблокированные (неисправен, просрочена КБК) возвращаются с причиной, чтобы форма показала её явно.
 */
export async function getIssuableContainers(now: Date = new Date()): Promise<IssuableContainer[]> {
  const containers = await prisma.container.findMany({
    where: { operationalStatus: "AVAILABLE" },
    orderBy: [{ currentLocode: "asc" }, { bicCode: "asc" }],
    select: { id: true, bicCode: true, sizeType: true, currentLocode: true, currentTerminal: true, conditionGrade: true, operationalStatus: true, techStatus: true, cscPlateExpiry: true },
  });
  return containers
    .map(({ operationalStatus, techStatus, cscPlateExpiry, ...c }) => ({ ...c, blockReason: issueBlockReason({ operationalStatus, techStatus, cscPlateExpiry }, now) }))
    .sort((a, b) => Number(a.blockReason !== null) - Number(b.blockReason !== null));
}"""),
