/**
 * Применение схемы к пустой базе без схемного движка Prisma (schema-engine).
 *
 * Зачем: в некоторых окружениях (замечено на Windows с Neon) `prisma db push` зависает или падает
 * с P1017, хотя Prisma Client работает. Скрипт генерирует SQL из prisma/schema.prisma офлайн
 * (`prisma migrate diff --from-empty`) и выполняет его через Prisma Client в одной транзакции.
 *
 * Идемпотентен: если таблицы уже созданы — ничего не меняет. Для обновления существующей схемы
 * используйте `npm run db:push` из окружения, где schema-engine доступен (CI, Linux, Vercel).
 *
 * Запуск: npm run db:init
 */
import { execFileSync } from "node:child_process";
import { PrismaClient } from "@prisma/client";

const EXPECTED_TABLES = ["User", "Container", "ContainerEvent", "OneWayTrip", "LeaseContract", "LeaseItem"];

function generateSql(): string {
  const prismaBin = process.platform === "win32" ? "npx.cmd" : "npx";
  return execFileSync(prismaBin, ["prisma", "migrate", "diff", "--from-empty", "--to-schema-datamodel", "prisma/schema.prisma", "--script"], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "ignore"],
    shell: process.platform === "win32",
  });
}

/** Разбивает скрипт Prisma на отдельные операторы (каждый блок начинается с комментария «-- …»). */
function splitStatements(sql: string): string[] {
  return sql
    .split(/;\s*\n/)
    .map((chunk) =>
      chunk
        .split("\n")
        .filter((line) => !line.trim().startsWith("--"))
        .join("\n")
        .trim(),
    )
    .filter(Boolean);
}

async function main(): Promise<void> {
  const prisma = new PrismaClient();
  try {
    const existing = await prisma.$queryRaw<{ table_name: string }[]>`
      select table_name from information_schema.tables where table_schema = 'public'`;
    const present = EXPECTED_TABLES.filter((t) => existing.some((e) => e.table_name === t));

    if (present.length === EXPECTED_TABLES.length) {
