  exact["хост Neon из .env"] = u.hostname;
  exact["endpoint Neon из .env"] = u.hostname.split(".")[0].replace("-pooler", "");
  exact["строка DATABASE_URL целиком"] = db;
}
exact["AUTH_SECRET из .env"] = get("AUTH_SECRET");
const patterns = {
  "postgres-URL с паролем": /postgres(ql)?:\/\/[^\s:"'`<>]+:(?!password@)[^\s@"'`<>]{6,}@/g,
  "хост *.neon.tech": /[a-z0-9-]+\.[a-z0-9-]+\.aws\.neon\.tech|ep-[a-z0-9]+-[a-z0-9]+-[a-z0-9]+(-pooler)?\.[a-z0-9.-]*neon\.tech/g,
  "пароль Neon (npg_…)": /npg_[A-Za-z0-9]{8,}/g,
