  for (const [name, value] of Object.entries(exact)) {
    if (value && value.length >= 6 && text.includes(value)) (report[name] ??= []).push(f);
  }
  for (const [name, re] of Object.entries(patterns)) {
    const m = text.match(re);
    if (m) (report[name] ??= []).push(`${f} (${m.length})`);
  }
}
console.log("Проверено файлов:", files.length);
for (const name of [...Object.keys(exact), ...Object.keys(patterns)]) {
  console.log(`${report[name] ? "⚠ НАЙДЕНО" : "✓ чисто   "} — ${name}${report[name] ? ": " + report[name].join(", ") : ""}`);
}
